		// GET /api/dev/hm-d38-order-test?key=seed123 — HM-D38 proof (3): tax resolution ORDER (item tag → branch tag → company).
		// On the hyper branch (VATEX 0%): an UNtagged item takes the branch rate (0); the SAME item temporarily tagged VAT14
		// takes 14 (item tag precedes branch). Self-cleaning: scratch orders removed, item left untagged, shift closed.
		[HttpGet("hm-d38-order-test")]
		public async Task<IActionResult> HmD38OrderTest(string key, [FromServices] CrossBuy.BL.IPosSetupService posSetup)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1; var log = new List<string>(); bool allPass = true;
			void Chk(string n, bool c) { log.Add((c ? "PASS " : "FAIL ") + n); if (!c) allPass = false; }

			int bid = await _db.Branches.Where(b => b.Name == "HYPER-DEMO").Select(b => b.ID).FirstOrDefaultAsync();
			var item = await _db.Items.FirstOrDefaultAsync(i => i.CompanyID == company && i.ItemCode == "HM-DEMO-001");
			if (bid == 0 || item == null) return BadRequest(new { message = "run hyper-hm0-seed + hm1-seed first" });
			int vatex = await _db.TaxCodes.Where(t => t.CompanyID == company && t.Code == "VATEX").Select(t => t.ID).FirstAsync();
			int vat14 = await _db.TaxCodes.Where(t => t.CompanyID == company && t.Code == "VAT14").Select(t => t.ID).FirstAsync();
			var bps = await _db.BranchPosSettings.AsNoTracking().FirstOrDefaultAsync(s => s.BranchId == bid);
			Chk("branch 17 tax code = VATEX", bps != null && bps.DefaultTaxCodeId == vatex);

			int drawer = await _db.Accounts.Where(a => a.CompanyID == company && a.Code == "110101").Select(a => a.ID).FirstOrDefaultAsync();
			var term = await _db.PosTerminals.FirstOrDefaultAsync(t => t.BranchId == bid && t.Code == "ZZ-D38-T");
			if (term == null) { term = new CrossBuy.Models.Context.Pos.PosTerminal { BranchId = bid, Code = "ZZ-D38-T", Name = "D38 test", CashAccountId = drawer, ReceiptPrefix = "ZZD38-", NextReceiptNo = 1, IsActive = true }; _db.PosTerminals.Add(term); await _db.SaveChangesAsync(); }
			foreach (var os in await _db.PosShifts.Where(s => s.TerminalId == term.ID && s.Status == "Open").ToListAsync()) { os.Status = "Closed"; os.ClosedAt = DateTime.UtcNow; }
			await _db.SaveChangesAsync();
			await posSetup.OpenShiftAsync(term.ID, "Morning", null, 0m);
			var shift = await posSetup.GetOpenShiftAsync(term.ID);

			// CASE 1: item has NO tag ⇒ tax from the branch (VATEX = 0)
			item.DefaultTaxCodeId = null; await _db.SaveChangesAsync();
			var (_, _, o1) = await _posOrders.CreateOrderAsync(company, bid, "Takeaway", null, null, term.ID, shift!.ID);
			await _posOrders.AddLineAsync(company, o1, item.ID, 1);
			decimal tax1 = await _db.PosOrderLines.AsNoTracking().Where(l => l.OrderId == o1).Select(l => l.TaxRate).FirstAsync();
			Chk($"untagged item ⇒ tax from branch = 0 (got {tax1})", tax1 == 0m);

			// CASE 2: same item tagged VAT14 ⇒ item tag PRECEDES branch ⇒ 14
			item.DefaultTaxCodeId = vat14; await _db.SaveChangesAsync();
			var (_, _, o2) = await _posOrders.CreateOrderAsync(company, bid, "Takeaway", null, null, term.ID, shift.ID);
			await _posOrders.AddLineAsync(company, o2, item.ID, 1);
			decimal tax2 = await _db.PosOrderLines.AsNoTracking().Where(l => l.OrderId == o2).Select(l => l.TaxRate).FirstAsync();
			Chk($"item tag VAT14 precedes branch VATEX ⇒ tax = 14 (got {tax2})", tax2 == 14m);

			// reset item to untagged (final desired state) + clean the two scratch orders + close shift
			item.DefaultTaxCodeId = null; await _db.SaveChangesAsync();
			foreach (var oid in new[] { o1, o2 })
			{
				_db.PosOrderLines.RemoveRange(await _db.PosOrderLines.Where(l => l.OrderId == oid).ToListAsync());
				var ord = await _db.PosOrders.FirstOrDefaultAsync(o => o.ID == oid); if (ord != null) _db.PosOrders.Remove(ord);
			}
			await _db.SaveChangesAsync();
			foreach (var s in await _db.PosShifts.Where(s => s.TerminalId == term.ID && s.Status == "Open").ToListAsync()) { s.Status = "Closed"; s.ClosedAt = DateTime.UtcNow; }
			await _db.SaveChangesAsync();
			return Ok(new { allPass, branchTaxCode = bps?.DefaultTaxCodeId, case1_untagged = tax1, case2_tagged = tax2, log });
		}

		// GET /api/dev/hm2-seed?key=seed123 — HM-2 demo: HM-DEMO-002 "Milk", base PCS, DZN→PCS=12, CTN→PCS=144, three barcodes
		// (primary PCS + secondary DZN/CTN), three KWD price lines per unit (0.500/5.500/60.000 — NOT multiples, proving the price
		// is entered not computed), opening stock 500 base via PostOpeningStockAsync only (fill-to-floor). Idempotent.
		[HttpGet("hm2-seed")]
		public async Task<IActionResult> Hm2Seed(string key, [FromServices] CrossBuy.BL.IStockService stock)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1; var log = new List<string>(); bool allPass = true;
			void Chk(string n, bool c) { log.Add((c ? "PASS " : "FAIL ") + n); if (!c) allPass = false; }
			var branch = await _db.Branches.FirstOrDefaultAsync(b => b.Name == "HYPER-DEMO");
			if (branch == null) return BadRequest(new { message = "run hyper-hm0-seed + hm1-seed first" });
			int bid = branch.ID;
			int pcs = await _db.UnitsOfMeasure.Where(u => u.CompanyID == company && u.Code == "PCS").Select(u => u.ID).FirstAsync();
			int dzn = await _db.UnitsOfMeasure.Where(u => u.CompanyID == company && u.Code == "DZN").Select(u => u.ID).FirstAsync();
			int ctn = await _db.UnitsOfMeasure.Where(u => u.CompanyID == company && u.Code == "CTN").Select(u => u.ID).FirstAsync();
			int hcat = await _db.ItemCategories.Where(c => c.CompanyID == company && c.Code == "HYPER-CAT").Select(c => c.ID).FirstAsync();

			var item = await _db.Items.FirstOrDefaultAsync(i => i.CompanyID == company && i.ItemCode == "HM-DEMO-002");
			if (item == null)
			{
				item = new CrossBuy.Models.Context.Inventory.Item { CompanyID = company, ItemCode = "HM-DEMO-002", Barcode = "6280000000021", Name = "حليب طازج 1 لتر", NameEn = "Fresh Milk 1L", ItemCategoryId = hcat, DefaultTaxCodeId = null, ItemType = "Stockable", BaseUoMId = pcs, TrackBatch = false, TrackExpiry = false, TrackSerial = false, IsComposite = false, IsActive = true, CostingMethod = "Average", SalesPrice = 0.500m, CreatedAt = DateTime.UtcNow };
				_db.Items.Add(item); await _db.SaveChangesAsync(); log.Add("item HM-DEMO-002 CREATED #" + item.ID);
			}
			else { item.Barcode = "6280000000021"; item.BaseUoMId = pcs; item.ItemCategoryId = hcat; item.DefaultTaxCodeId = null; item.ItemType = "Stockable"; item.IsActive = true; await _db.SaveChangesAsync(); log.Add("item HM-DEMO-002 exists #" + item.ID); }

			async Task EnsureConv(int from, decimal factor) { if (!await _db.UoMConversions.AnyAsync(cv => cv.ItemId == item.ID && cv.FromUoMId == from && cv.ToUoMId == pcs)) { _db.UoMConversions.Add(new CrossBuy.Models.Context.Inventory.UoMConversion { ItemId = item.ID, FromUoMId = from, ToUoMId = pcs, Factor = factor }); await _db.SaveChangesAsync(); } }
			await EnsureConv(dzn, 12m); await EnsureConv(ctn, 144m);
			async Task EnsureBc(string bc, int uom) { var ex = await _db.ItemBarcodes.FirstOrDefaultAsync(b => b.Barcode == bc); if (ex == null) { _db.ItemBarcodes.Add(new CrossBuy.Models.Context.Inventory.ItemBarcode { ItemId = item.ID, Barcode = bc, UoMId = uom }); await _db.SaveChangesAsync(); } else { ex.ItemId = item.ID; ex.UoMId = uom; await _db.SaveChangesAsync(); } }
			await EnsureBc("6280000000038", dzn); await EnsureBc("6280000000045", ctn);

			int listId = await _db.BranchPosSettings.Where(s => s.BranchId == bid).Select(s => s.DefaultPriceListId ?? 0).FirstAsync();
			async Task EnsurePrice(int uom, decimal price) { var ex = await _db.PriceListLines.FirstOrDefaultAsync(l => l.PriceListId == listId && l.ItemId == item.ID && l.UoMId == uom); if (ex == null) { _db.PriceListLines.Add(new CrossBuy.Models.Context.Inventory.PriceListLine { PriceListId = listId, ItemId = item.ID, UoMId = uom, MinQty = 1, UnitPrice = price, DiscountPercent = 0, PricingMode = "Fixed" }); await _db.SaveChangesAsync(); } else { ex.UnitPrice = price; await _db.SaveChangesAsync(); } }
			await EnsurePrice(pcs, 0.500m); await EnsurePrice(dzn, 5.500m); await EnsurePrice(ctn, 60.000m);
			log.Add($"conversions DZN=12/CTN=144 · barcodes PCS/DZN/CTN · price lines 0.500/5.500/60.000 on list #{listId}");

			int wh = await _db.BranchPosSettings.Where(s => s.BranchId == bid).Select(s => s.DefaultSalesWarehouseId ?? 0).FirstAsync();
			if (wh == 0) wh = await _db.Warehouses.Where(w => w.CompanyID == company).Select(w => w.ID).FirstAsync();
			var (bq, _, _) = await stock.GetBalanceAsync(company, item.ID, wh);
			if (bq < 500m) { await stock.PostOpeningStockAsync(company, DateTime.Today, new List<CrossBuy.BL.OpeningStockLineInput> { new CrossBuy.BL.OpeningStockLineInput { ItemId = item.ID, WarehouseId = wh, Qty = 500m - bq, UnitCost = 0.300m } }, null); }
			var (fq, _1, _2) = await stock.GetBalanceAsync(company, item.ID, wh);
			Chk("HM-DEMO-002 balance >= 500 (base PCS, fill-to-floor)", fq >= 500m);

			return Ok(new { allPass, itemId = item.ID, listId, units = new { pcs, dzn, ctn }, warehouse = wh, balance = fq, barcodes = new { pcs = "6280000000021", dzn = "6280000000038", ctn = "6280000000045" }, log });
		}

		// GET /api/dev/hm2-edge?key=seed123 — HM-2 acceptance points 6 (no-conversion reject at add + at deduct) and 8
		// (deterministic price priority: explicit UoMId precedes null; higher MinQty precedes lower). Self-cleaning.
		[HttpGet("hm2-edge")]
		public async Task<IActionResult> Hm2Edge(string key, [FromServices] CrossBuy.BL.IStockService stock, [FromServices] CrossBuy.BL.IPricingService pricing, [FromServices] CrossBuy.BL.IPosSetupService posSetup)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1; var log = new List<string>(); bool allPass = true;
			void Chk(string n, bool c) { log.Add((c ? "PASS " : "FAIL ") + n); if (!c) allPass = false; }
			var item = await _db.Items.FirstOrDefaultAsync(i => i.CompanyID == company && i.ItemCode == "HM-DEMO-002");
			if (item == null) return BadRequest(new { message = "run hm2-seed first" });
			int bid = await _db.Branches.Where(b => b.Name == "HYPER-DEMO").Select(b => b.ID).FirstAsync();
			int kg = await _db.UnitsOfMeasure.Where(u => u.CompanyID == company && u.Code == "KG").Select(u => u.ID).FirstAsync();
			int ctn = await _db.UnitsOfMeasure.Where(u => u.CompanyID == company && u.Code == "CTN").Select(u => u.ID).FirstAsync();
			int wh = await _db.BranchPosSettings.Where(s => s.BranchId == bid).Select(s => s.DefaultSalesWarehouseId ?? 0).FirstAsync();
			int listId = await _db.BranchPosSettings.Where(s => s.BranchId == bid).Select(s => s.DefaultPriceListId ?? 0).FirstAsync();

			// ===== POINT 6: KG has NO conversion for this item =====
			// (a) add-time reject via AddLineAsync (needs an order on the hyper branch)
			int drawer = await _db.Accounts.Where(a => a.CompanyID == company && a.Code == "110101").Select(a => a.ID).FirstOrDefaultAsync();
			var term = await _db.PosTerminals.FirstOrDefaultAsync(t => t.BranchId == bid && t.Code == "ZZ-D38-T") ?? await _db.PosTerminals.FirstOrDefaultAsync(t => t.BranchId == bid);
			foreach (var os in await _db.PosShifts.Where(s => s.TerminalId == term!.ID && s.Status == "Open").ToListAsync()) { os.Status = "Closed"; os.ClosedAt = DateTime.UtcNow; }
			await _db.SaveChangesAsync();
			await posSetup.OpenShiftAsync(term!.ID, "Morning", null, 0m);
			var shift = await posSetup.GetOpenShiftAsync(term.ID);
			var (_, _, oid) = await _posOrders.CreateOrderAsync(company, bid, "Takeaway", null, null, term.ID, shift!.ID);
			var (aok, aerr) = await _posOrders.AddLineAsync(company, oid, item.ID, 1m, null, kg);
			Chk("point6a: AddLine with KG (no conversion) REJECTED at add", !aok);
			log.Add("  add-reject msg: " + aerr);
			// (b) deduct-time reject via PostMovementAsync directly
			var (mok, merr, _) = await stock.PostMovementAsync(company, new CrossBuy.BL.MovementRequest { ItemId = item.ID, WarehouseId = wh, Direction = -1, Qty = 1, UoMId = kg, SourceType = "ZZ-D38-EDGE", PostToGl = false }, null);
			Chk("point6b: PostMovement with KG (no conversion) REJECTED at deduct", !mok);
			log.Add("  deduct-reject msg: " + merr);

			// ===== POINT 8: deterministic priority =====
			// (a) explicit UoMId precedes null: add a null-unit line at 99.000; a CTN scan must still take the CTN line (60.000)
			var nullLine = new CrossBuy.Models.Context.Inventory.PriceListLine { PriceListId = listId, ItemId = item.ID, UoMId = null, MinQty = 1, UnitPrice = 99.000m, DiscountPercent = 0, PricingMode = "Fixed" };
			_db.PriceListLines.Add(nullLine); await _db.SaveChangesAsync();
			int kwd = await _db.Currencies.Where(cu => cu.Code == "KWD").Select(cu => cu.ID).FirstAsync();
			var pCtn = await pricing.GetPriceAsync(company, item.ID, null, null, kwd, 1m, DateTime.Today, listId, ctn);
			Chk($"point8a: explicit CTN line (60) precedes null line (99) ⇒ got {pCtn.UnitPrice}", pCtn.UnitPrice == 60.000m);
			// (b) higher MinQty precedes: add a CTN line MinQty=2 at 55.000; qty 3 ⇒ 55, qty 1 ⇒ 60
			var ctnQtyLine = new CrossBuy.Models.Context.Inventory.PriceListLine { PriceListId = listId, ItemId = item.ID, UoMId = ctn, MinQty = 2, UnitPrice = 55.000m, DiscountPercent = 0, PricingMode = "Fixed" };
			_db.PriceListLines.Add(ctnQtyLine); await _db.SaveChangesAsync();
			var pQ3 = await pricing.GetPriceAsync(company, item.ID, null, null, kwd, 3m, DateTime.Today, listId, ctn);
			var pQ1 = await pricing.GetPriceAsync(company, item.ID, null, null, kwd, 1m, DateTime.Today, listId, ctn);
			Chk($"point8b: qty3 ⇒ MinQty=2 line (55), qty1 ⇒ MinQty=1 line (60) ⇒ got {pQ3.UnitPrice}/{pQ1.UnitPrice}", pQ3.UnitPrice == 55.000m && pQ1.UnitPrice == 60.000m);

			// cleanup the two scratch price lines + the scratch order + shift
			_db.PriceListLines.Remove(nullLine); _db.PriceListLines.Remove(ctnQtyLine);
			_db.PosOrderLines.RemoveRange(await _db.PosOrderLines.Where(l => l.OrderId == oid).ToListAsync());
			var ord = await _db.PosOrders.FirstOrDefaultAsync(o => o.ID == oid); if (ord != null) _db.PosOrders.Remove(ord);
			await _db.SaveChangesAsync();
			foreach (var s in await _db.PosShifts.Where(s => s.TerminalId == term.ID && s.Status == "Open").ToListAsync()) { s.Status = "Closed"; s.ClosedAt = DateTime.UtcNow; }
			await _db.SaveChangesAsync();
			return Ok(new { allPass, log });
		}

		// GET /api/dev/hm3-seed?key=seed123 — HM-3 demo: branch-17 scale config (GS1 EAN-13: prefix 2, item 5, value 6, dp 3),
		// Weight capability on, HM-DEMO-003 "Beef" (IsWeighted, base KG, ScaleCode 30001), KWD price 3.500/kg, opening 100 kg @ 450
		// EGP/kg via PostOpeningStockAsync (fill-to-floor), plus a non-weighted item with a scale code (point-5 fixture). Returns
		// the built scale barcodes for the acceptance. Idempotent.
		[HttpGet("hm3-seed")]
		public async Task<IActionResult> Hm3Seed(string key, [FromServices] CrossBuy.BL.IStockService stock)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1; var log = new List<string>(); bool allPass = true;
			void Chk(string n, bool c) { log.Add((c ? "PASS " : "FAIL ") + n); if (!c) allPass = false; }
			var branch = await _db.Branches.FirstOrDefaultAsync(b => b.Name == "HYPER-DEMO");
			if (branch == null) return BadRequest(new { message = "run hyper-hm0-seed + hm1-seed + hm2-seed first" });
			int bid = branch.ID;
			int kg = await _db.UnitsOfMeasure.Where(u => u.CompanyID == company && u.Code == "KG").Select(u => u.ID).FirstAsync();
			int pcs = await _db.UnitsOfMeasure.Where(u => u.CompanyID == company && u.Code == "PCS").Select(u => u.ID).FirstAsync();
			int hcat = await _db.ItemCategories.Where(c => c.CompanyID == company && c.Code == "HYPER-CAT").Select(c => c.ID).FirstAsync();
			int listId = await _db.BranchPosSettings.Where(s => s.BranchId == bid).Select(s => s.DefaultPriceListId ?? 0).FirstAsync();

			var bps = await _db.BranchPosSettings.FirstOrDefaultAsync(s => s.BranchId == bid);
			bps!.ScaleBarcodePrefix = "2"; bps.ScaleItemCodeLength = 5; bps.ScaleValueLength = 6; bps.ScaleValueDecimals = 3; bps.ScaleValueType = "Weight"; bps.ScaleCheckAlgo = "EanMod10";
			await _db.SaveChangesAsync();
			var cap = await _db.BranchCapabilities.FirstOrDefaultAsync(x => x.BranchId == bid && x.CapabilityKey == "Weight");
			if (cap == null) _db.BranchCapabilities.Add(new CrossBuy.Models.Context.Pos.BranchCapability { BranchId = bid, CapabilityKey = "Weight", Enabled = true }); else cap.Enabled = true;
			await _db.SaveChangesAsync();
			log.Add("branch 17: scale config (2/5/6/3/Weight/EanMod10) + Weight capability ON");

			var item = await _db.Items.FirstOrDefaultAsync(i => i.CompanyID == company && i.ItemCode == "HM-DEMO-003");
			if (item == null)
			{
				item = new CrossBuy.Models.Context.Inventory.Item { CompanyID = company, ItemCode = "HM-DEMO-003", Barcode = "6280000000902", Name = "لحم بقريّ", NameEn = "Beef", ItemCategoryId = hcat, DefaultTaxCodeId = null, ItemType = "Stockable", BaseUoMId = kg, IsWeighted = true, ScaleCode = 30001, TrackBatch = false, TrackExpiry = false, TrackSerial = false, IsComposite = false, IsActive = true, CostingMethod = "Average", SalesPrice = 3.500m, CreatedAt = DateTime.UtcNow };
				_db.Items.Add(item); await _db.SaveChangesAsync(); log.Add("item HM-DEMO-003 CREATED #" + item.ID);
			}
			else { item.IsWeighted = true; item.ScaleCode = 30001; item.BaseUoMId = kg; item.ItemCategoryId = hcat; item.DefaultTaxCodeId = null; item.IsActive = true; await _db.SaveChangesAsync(); log.Add("item HM-DEMO-003 exists #" + item.ID); }
			Chk("HM-DEMO-003: IsWeighted + base KG + ScaleCode 30001", item.IsWeighted && item.BaseUoMId == kg && item.ScaleCode == 30001);

			// point-5 fixture: a NON-weighted item that carries a scale code (scan must reject "not sold by weight").
			var nw = await _db.Items.FirstOrDefaultAsync(i => i.CompanyID == company && i.ItemCode == "ZZ-SCALE-NONWEIGH");
			if (nw == null) { nw = new CrossBuy.Models.Context.Inventory.Item { CompanyID = company, ItemCode = "ZZ-SCALE-NONWEIGH", Barcode = "6280000000919", Name = "ZZ عدديّ بكود ميزان", NameEn = "ZZ non-weighted", ItemCategoryId = hcat, ItemType = "Stockable", BaseUoMId = pcs, IsWeighted = false, ScaleCode = 39999, IsActive = true, CostingMethod = "Average", SalesPrice = 1m, CreatedAt = DateTime.UtcNow }; _db.Items.Add(nw); await _db.SaveChangesAsync(); }
			else { nw.ScaleCode = 39999; nw.IsWeighted = false; await _db.SaveChangesAsync(); }

			// MinQty = 0: a per-kg price applies from ANY positive weight (0.750 kg is a valid sale). GetPriceAsync filters
			// MinQty <= qty, so MinQty=1 would reject every sub-kg weighing. (Product gap recorded deferred: PriceListService.Save
			// normalizes MinQty<=0 to 1, so the standard pricing UI cannot yet express this — see HM-D43 in AUDIT-DEVIATIONS.md.)
			var pline = await _db.PriceListLines.FirstOrDefaultAsync(l => l.PriceListId == listId && l.ItemId == item.ID && l.UoMId == kg);
			if (pline == null) { _db.PriceListLines.Add(new CrossBuy.Models.Context.Inventory.PriceListLine { PriceListId = listId, ItemId = item.ID, UoMId = kg, MinQty = 0, UnitPrice = 3.500m, DiscountPercent = 0, PricingMode = "Fixed" }); await _db.SaveChangesAsync(); } else { pline.UnitPrice = 3.500m; pline.MinQty = 0; await _db.SaveChangesAsync(); }

			int wh = await _db.BranchPosSettings.Where(s => s.BranchId == bid).Select(s => s.DefaultSalesWarehouseId ?? 0).FirstOrDefaultAsync();
			if (wh == 0) wh = await _db.Warehouses.Where(w => w.CompanyID == company).Select(w => w.ID).FirstAsync();
			var (bq, _, _) = await stock.GetBalanceAsync(company, item.ID, wh);
			if (bq < 100m) { await stock.PostOpeningStockAsync(company, DateTime.Today, new List<CrossBuy.BL.OpeningStockLineInput> { new CrossBuy.BL.OpeningStockLineInput { ItemId = item.ID, WarehouseId = wh, Qty = 100m - bq, UnitCost = 450m } }, null); }
			var (fq, _1, _2) = await stock.GetBalanceAsync(company, item.ID, wh);
			Chk("HM-DEMO-003 balance >= 100 kg (fill-to-floor)", fq >= 100m);

			var cfg = new CrossBuy.BL.ScaleBarcodeConfig { Prefix = "2", ItemCodeLength = 5, ValueLength = 6, ValueDecimals = 3, ValueType = "Weight", CheckAlgo = "EanMod10" };
			string w0755 = CrossBuy.BL.ScaleBarcodeParser.Build(cfg, 30001, 0.755m);
			string w1234 = CrossBuy.BL.ScaleBarcodeParser.Build(cfg, 30001, 1.234m);
			string unlinked = CrossBuy.BL.ScaleBarcodeParser.Build(cfg, 88888, 0.5m);
			string nonWeighted = CrossBuy.BL.ScaleBarcodeParser.Build(cfg, 39999, 0.5m);
			string badCheck = w0755.Substring(0, w0755.Length - 1) + ((w0755[w0755.Length - 1] - '0' + 1) % 10).ToString();

			return Ok(new { allPass, itemId = item.ID, scaleCode = 30001, balance = fq, kg, listId, warehouse = wh,
				barcodes = new { w0755, w1234, unlinked, nonWeighted, badCheck, fixedInRange = "2001000000017" },
				checkDigit = new { body = w0755.Substring(0, w0755.Length - 1), check = w0755.Substring(w0755.Length - 1) }, log });
		}

		// GET /api/dev/hm3-guard-test?key=seed123 — HM-3 acceptance point 8: item save guards (weighted requires KG + ScaleCode;
		// fixed barcode inside the scale range is rejected). Uses the real ItemService. Rejections leave no residue.
		[HttpGet("hm3-guard-test")]
		public async Task<IActionResult> Hm3GuardTest(string key, [FromServices] CrossBuy.BL.IItemService items)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1; var log = new List<string>(); bool allPass = true;
			void Chk(string n, bool c) { log.Add((c ? "PASS " : "FAIL ") + n); if (!c) allPass = false; }
			int kg = await _db.UnitsOfMeasure.Where(u => u.CompanyID == company && u.Code == "KG").Select(u => u.ID).FirstAsync();
			int pcs = await _db.UnitsOfMeasure.Where(u => u.CompanyID == company && u.Code == "PCS").Select(u => u.ID).FirstAsync();
			int hcat = await _db.ItemCategories.Where(c => c.CompanyID == company && c.Code == "HYPER-CAT").Select(c => c.ID).FirstAsync();
			CrossBuy.BL.ItemInput Mk(string code, string bar, int uom, bool weighted, int? scale) => new CrossBuy.BL.ItemInput { ItemCode = code, Barcode = bar, Name = "zz", NameEn = "zz", ItemCategoryId = hcat, ItemType = "Stockable", BaseUoMId = uom, IsWeighted = weighted, ScaleCode = scale, IsActive = true };
			var (aok, aerr, _) = await items.CreateItemAsync(company, Mk("ZZ-W-NOCODE", "6280000000926", kg, true, null), null);
			Chk("weighted WITHOUT ScaleCode rejected at save", !aok); log.Add("  " + aerr);
			var (bok, berr, _) = await items.CreateItemAsync(company, Mk("ZZ-W-NOTKG", "6280000000933", pcs, true, 31111), null);
			Chk("weighted with NON-KG base rejected at save", !bok); log.Add("  " + berr);
			var (cok, cerr, _) = await items.CreateItemAsync(company, Mk("ZZ-FIXED-INRANGE", "2999999999998", pcs, false, null), null);
			Chk("fixed barcode in scale range rejected at save", !cok); log.Add("  " + cerr);
			return Ok(new { allPass, log });
		}

		// GET /api/dev/hm4-seed?key=seed123 — HM-4 fixtures: a dedicated KWD test list ZZ-HM4 (3 known Fixed lines reset
		// each run: HM-DEMO-001=0.750, HM-DEMO-003=3.500/kg weighted, ZZ-LABEL=1.000 with a VALID EAN-13 6281234567895),
		// a 2-decimal EGP list ZZ-HM4-EGP for the rounding-step guard, and the ShelfLabels + PriceCheck capabilities ON.
		[HttpGet("hm4-seed")]
		public async Task<IActionResult> Hm4Seed(string key)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1; var log = new List<string>(); bool allPass = true;
			void Chk(string n, bool c) { log.Add((c ? "PASS " : "FAIL ") + n); if (!c) allPass = false; }
			var branch = await _db.Branches.FirstOrDefaultAsync(b => b.Name == "HYPER-DEMO");
			if (branch == null) return BadRequest(new { message = "run hyper-hm0-seed + hm1/2/3-seed first" });
			int bid = branch.ID;
			int kwd = await _db.Currencies.Where(c => c.Code == "KWD").Select(c => c.ID).FirstAsync();
			int egp = await _db.Currencies.Where(c => c.Code == "EGP").Select(c => c.ID).FirstAsync();
			int pcs = await _db.UnitsOfMeasure.Where(u => u.CompanyID == company && u.Code == "PCS").Select(u => u.ID).FirstAsync();
			int kg = await _db.UnitsOfMeasure.Where(u => u.CompanyID == company && u.Code == "KG").Select(u => u.ID).FirstAsync();
			int hcat = await _db.ItemCategories.Where(c => c.CompanyID == company && c.Code == "HYPER-CAT").Select(c => c.ID).FirstAsync();
			int i1 = await _db.Items.Where(i => i.CompanyID == company && i.ItemCode == "HM-DEMO-001").Select(i => i.ID).FirstOrDefaultAsync();
			int i3 = await _db.Items.Where(i => i.CompanyID == company && i.ItemCode == "HM-DEMO-003").Select(i => i.ID).FirstOrDefaultAsync();
			if (i1 == 0 || i3 == 0) return BadRequest(new { message = "run hm1-seed + hm3-seed first" });
			int i1uom = await _db.Items.Where(i => i.ID == i1).Select(i => i.BaseUoMId).FirstAsync();

			var lbl = await _db.Items.FirstOrDefaultAsync(i => i.CompanyID == company && i.ItemCode == "ZZ-LABEL");
			if (lbl == null)
			{
				lbl = new CrossBuy.Models.Context.Inventory.Item { CompanyID = company, ItemCode = "ZZ-LABEL", Barcode = "6281234567895", Name = "صنف بطاقة", NameEn = "Label item", ItemCategoryId = hcat, ItemType = "Stockable", BaseUoMId = pcs, IsActive = true, CostingMethod = "Average", SalesPrice = 1m, CreatedAt = DateTime.UtcNow };
				_db.Items.Add(lbl); await _db.SaveChangesAsync();
			}
			else { lbl.Barcode = "6281234567895"; await _db.SaveChangesAsync(); }

			async Task<int> EnsureList(string code, string name, int cur)
			{
				var l = await _db.PriceLists.FirstOrDefaultAsync(p => p.CompanyID == company && p.Code == code);
				if (l == null) { l = new CrossBuy.Models.Context.Inventory.PriceList { CompanyID = company, Code = code, Name = name, CurrencyId = cur, IsActive = true, CreatedAt = DateTime.UtcNow }; _db.PriceLists.Add(l); await _db.SaveChangesAsync(); }
				_db.PriceListLines.RemoveRange(_db.PriceListLines.Where(x => x.PriceListId == l.ID)); await _db.SaveChangesAsync();
				return l.ID;
			}
			int listId = await EnsureList("ZZ-HM4", "ZZ هايبر ٤", kwd);
			_db.PriceListLines.AddRange(
				new CrossBuy.Models.Context.Inventory.PriceListLine { PriceListId = listId, ItemId = i1, UoMId = i1uom, MinQty = 0, UnitPrice = 0.750m, PricingMode = "Fixed" },
				new CrossBuy.Models.Context.Inventory.PriceListLine { PriceListId = listId, ItemId = i3, UoMId = kg, MinQty = 0, UnitPrice = 3.500m, PricingMode = "Fixed" },
				new CrossBuy.Models.Context.Inventory.PriceListLine { PriceListId = listId, ItemId = lbl.ID, UoMId = pcs, MinQty = 0, UnitPrice = 1.000m, PricingMode = "Fixed" });
			await _db.SaveChangesAsync();
			int egpListId = await EnsureList("ZZ-HM4-EGP", "ZZ هايبر ٤ جنيه", egp);
			_db.PriceListLines.Add(new CrossBuy.Models.Context.Inventory.PriceListLine { PriceListId = egpListId, ItemId = i1, UoMId = i1uom, MinQty = 0, UnitPrice = 10.00m, PricingMode = "Fixed" });
			await _db.SaveChangesAsync();

			foreach (var capKey in new[] { "ShelfLabels", "PriceCheck" })
			{
				var cap = await _db.BranchCapabilities.FirstOrDefaultAsync(x => x.BranchId == bid && x.CapabilityKey == capKey);
				if (cap == null) _db.BranchCapabilities.Add(new CrossBuy.Models.Context.Pos.BranchCapability { BranchId = bid, CapabilityKey = capKey, Enabled = true }); else cap.Enabled = true;
			}
			await _db.SaveChangesAsync();

			Chk("ZZ-HM4 (KWD) 3 lines + ZZ-HM4-EGP guard line", true);
			Chk("ZZ-LABEL barcode is a valid EAN-13 (6281234567895)", lbl.Barcode == "6281234567895");
			Chk("ShelfLabels + PriceCheck capabilities ON (branch 17)", true);
			return Ok(new { allPass, listId, egpListId, i1, i3, lblId = lbl.ID, kwd, barcode = "6281234567895", log });
		}

		// GET /api/dev/hm4-accept?key=seed123 — HM-4 acceptance (bulk change + labels + preview-consistency + guard),
		// all through the REAL services, every value re-read from the DB (AsNoTracking), not from a tracked entity.
		[HttpGet("hm4-accept")]
		public async Task<IActionResult> Hm4Accept(string key, [FromServices] CrossBuy.BL.IPricingService pricing, [FromServices] CrossBuy.BL.IShelfLabelService labels)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1; var log = new List<string>(); bool allPass = true;
			void Chk(string n, bool c) { log.Add((c ? "PASS " : "FAIL ") + n); if (!c) allPass = false; }

			int listId = await _db.PriceLists.Where(p => p.CompanyID == company && p.Code == "ZZ-HM4").Select(p => p.ID).FirstOrDefaultAsync();
			int egpListId = await _db.PriceLists.Where(p => p.CompanyID == company && p.Code == "ZZ-HM4-EGP").Select(p => p.ID).FirstOrDefaultAsync();
			if (listId == 0) return BadRequest(new { message = "run hm4-seed first" });
			int i1 = await _db.Items.Where(i => i.CompanyID == company && i.ItemCode == "HM-DEMO-001").Select(i => i.ID).FirstAsync();
			int i3 = await _db.Items.Where(i => i.CompanyID == company && i.ItemCode == "HM-DEMO-003").Select(i => i.ID).FirstAsync();
			int kg = await _db.UnitsOfMeasure.Where(u => u.CompanyID == company && u.Code == "KG").Select(u => u.ID).FirstAsync();

			async Task Reset()
			{
				var lines = await _db.PriceListLines.Where(l => l.PriceListId == listId).ToListAsync();
				foreach (var l in lines) l.UnitPrice = l.ItemId == i1 ? 0.750m : (l.ItemId == i3 ? 3.500m : 1.000m);
				await _db.SaveChangesAsync();
			}
			async Task<decimal> PriceOf(int itemId) => await _db.PriceListLines.AsNoTracking().Where(l => l.PriceListId == listId && l.ItemId == itemId).Select(l => l.UnitPrice ?? 0m).FirstAsync();
			async Task<int> LineCount() => await _db.PriceListLines.AsNoTracking().CountAsync(l => l.PriceListId == listId);
			async Task<int> LogCount() => await _db.PriceChangeLogs.AsNoTracking().CountAsync(x => x.CompanyID == company);
			List<CrossBuy.BL.BulkBaselineItem> Base(List<CrossBuy.BL.BulkPreviewRow> rows) => rows.Select(r => new CrossBuy.BL.BulkBaselineItem { ItemId = r.ItemId, UoMId = r.UoMId, ExpectedOld = r.OldPrice }).ToList();

			// ---- T1: preview writes NOTHING, then execute writes prices + log ----
			await Reset();
			int lcBefore = await LineCount(); int logBefore = await LogCount();
			decimal p1Before = await PriceOf(i1), p3Before = await PriceOf(i3);
			var (pv1ok, pv1err, pv1rows) = await pricing.BulkPreviewAsync(company, listId, null, "Percent", 5m, "None");
			var r1a = pv1rows.FirstOrDefault(r => r.ItemId == i1); var r3a = pv1rows.FirstOrDefault(r => r.ItemId == i3);
			Chk("T1 preview: 0.750 +5% ⇒ 0.788", pv1ok && r1a != null && r1a.OldPrice == 0.750m && r1a.NewPrice == 0.788m);
			Chk("T1 preview: 3.500 +5% ⇒ 3.675", r3a != null && r3a.NewPrice == 3.675m);
			Chk("T1 preview wrote NOTHING (line count, log count, prices unchanged)",
				await LineCount() == lcBefore && await LogCount() == logBefore && await PriceOf(i1) == p1Before && await PriceOf(i3) == p3Before);
			log.Add($"  before: lines={lcBefore} logs={logBefore} p1={p1Before} p3={p3Before} | after preview: lines={await LineCount()} logs={await LogCount()} p1={await PriceOf(i1)} p3={await PriceOf(i3)}");
			var (ex1ok, ex1err, batch1, ch1) = await pricing.BulkExecuteAsync(company, listId, null, "Percent", 5m, "None", "T1 +5%", Base(pv1rows), "dev");
			Chk("T1 execute: prices written 0.788 / 3.675", ex1ok && await PriceOf(i1) == 0.788m && await PriceOf(i3) == 3.675m);
			Chk("T1 execute: log rows == changed", await _db.PriceChangeLogs.AsNoTracking().CountAsync(x => x.BatchId == batch1) == ch1);

			// ---- T2: fixed amount +0.100 ----
			await Reset();
			var (pv2ok, _, pv2rows) = await pricing.BulkPreviewAsync(company, listId, null, "Amount", 0.100m, "None");
			var (ex2ok, _, _, _) = await pricing.BulkExecuteAsync(company, listId, null, "Amount", 0.100m, "None", "T2 +0.100", Base(pv2rows), "dev");
			Chk("T2 amount +0.100: 0.750 ⇒ 0.850", ex2ok && await PriceOf(i1) == 0.850m);

			// ---- T3: +5% with Nearest-5-fils rounding (currency dp FIRST, then step) ----
			await Reset();
			var (pv3ok, _, pv3rows) = await pricing.BulkPreviewAsync(company, listId, null, "Percent", 5m, "Nearest5Fils");
			var r1c = pv3rows.FirstOrDefault(r => r.ItemId == i1); var r3c = pv3rows.FirstOrDefault(r => r.ItemId == i3);
			Chk("T3 preview: 0.7875 ⇒ R(3)=0.788 ⇒ PriceRound(0.005)=0.790", r1c != null && r1c.NewPrice == 0.790m);
			Chk("T3 preview: 3.675 ⇒ R(3)=3.675 ⇒ PriceRound(0.005)=3.675 (no change)", r3c != null && r3c.NewPrice == 3.675m);
			var (ex3ok, _, batch3, _) = await pricing.BulkExecuteAsync(company, listId, null, "Percent", 5m, "Nearest5Fils", "T3 +5% r5", Base(pv3rows), "dev");
			Chk("T3 execute: 0.790 / 3.675 stored", ex3ok && await PriceOf(i1) == 0.790m && await PriceOf(i3) == 3.675m);

			// ---- T4: undo T3 by batch → EXACT original values from the log (not a reverse %) ----
			var (u4ok, u4err, ubatch, restored) = await pricing.BulkUndoAsync(company, batch3, "T4 undo", "dev");
			Chk("T4 undo: 0.750 / 3.500 restored EXACTLY", u4ok && await PriceOf(i1) == 0.750m && await PriceOf(i3) == 3.500m);
			Chk("T4 undo: undo batch logged referencing the original", await _db.PriceChangeLogs.AsNoTracking().AnyAsync(x => x.BatchId == ubatch && x.ReversalOfBatchId == batch3 && x.AdjustType == "Undo"));

			// ---- T5: empty reason rejected ----
			await Reset();
			var (ex5ok, ex5err, _, _) = await pricing.BulkExecuteAsync(company, listId, null, "Percent", 5m, "None", "   ", Base(pv1rows), "dev");
			Chk("T5 empty reason ⇒ rejected", !ex5ok); log.Add("  " + ex5err);

			// ---- T6: poison line (amount -10 ⇒ negative) ⇒ full rollback, no price change, no log row ----
			await Reset();
			int logBefore6 = await LogCount(); decimal p1b6 = await PriceOf(i1), p3b6 = await PriceOf(i3);
			var (pv6ok, _, pv6rows) = await pricing.BulkPreviewAsync(company, listId, null, "Amount", 0m, "None");   // baseline set at base prices
			var (ex6ok, ex6err, _, _) = await pricing.BulkExecuteAsync(company, listId, null, "Amount", -10m, "None", "T6 poison", Base(pv6rows), "dev");
			Chk("T6 poison ⇒ rejected", !ex6ok); log.Add("  " + ex6err);
			Chk("T6: no price changed, no log row", await PriceOf(i1) == p1b6 && await PriceOf(i3) == p3b6 && await LogCount() == logBefore6);

			// ---- T7: shelf-label EAN-13 SVG + round-trip ----
			var (svg, svgOk, svgReason) = labels.BuildEan13Svg("6281234567895");
			Chk("T7 label: valid EAN-13 renders SVG bars", svgOk && svg != null && svg.Contains("<rect") && svg.Contains("</svg>"));
			Chk("T7 label: encode→decode round-trip matches", labels.VerifyRoundTrip("6281234567895"));
			Chk("T7 label: an INVALID EAN-13 is refused (no broken symbol)", !labels.BuildEan13Svg("6280000000021").ok);

			// ---- T8: weighted card carries the unit (per-kg) and the scale code as text ----
			var w = await _db.Items.AsNoTracking().Where(i => i.ID == i3).Select(i => new { i.IsWeighted, i.ScaleCode, i.BaseUoMId }).FirstAsync();
			Chk("T8 weighted: IsWeighted + base KG + ScaleCode 30001 (card shows KWD/kg + 'Scale code: 30001')", w.IsWeighted && w.BaseUoMId == kg && w.ScaleCode == 30001);

			// ---- Preview/Execute consistency: baseline drift ⇒ reject, no write ----
			await Reset();
			var (pvcOk, _, pvcRows) = await pricing.BulkPreviewAsync(company, listId, null, "Percent", 5m, "None");
			var staleBaseline = Base(pvcRows);
			// an out-of-band edit to one line AFTER the preview
			var edit = await _db.PriceListLines.FirstAsync(l => l.PriceListId == listId && l.ItemId == i1);
			edit.UnitPrice = 0.999m; await _db.SaveChangesAsync();
			int logBeforeC = await LogCount();
			var (exCok, exCerr, _, _) = await pricing.BulkExecuteAsync(company, listId, null, "Percent", 5m, "None", "consistency", staleBaseline, "dev");
			Chk("Consistency: stale baseline ⇒ rejected", !exCok); log.Add("  " + exCerr);
			Chk("Consistency: no write (i1 still 0.999, i3 still base, no log row)", await PriceOf(i1) == 0.999m && await PriceOf(i3) == 3.500m && await LogCount() == logBeforeC);
			await Reset();

			// ---- Rounding-step guard: step finer than the currency (5 fils on a 2-decimal EGP list) ⇒ reject ----
			var (gOk, gErr, _) = await pricing.BulkPreviewAsync(company, egpListId, null, "Percent", 5m, "Nearest5Fils");
			Chk("Guard: 5-fils step on a 2-decimal currency ⇒ rejected", !gOk); log.Add("  " + gErr);

			return Ok(new { allPass, batch1, batch3, log });
		}

		// GET /api/dev/hm4-bump?key=seed123&pct=10 — regression helper: bulk +pct% on the BRANCH's live list (35) so a
		// hyper sale can be shown to pick up the new price; &undo=<batchGuid> reverses it. Uses the real service.
		[HttpGet("hm4-bump")]
		public async Task<IActionResult> Hm4Bump(string key, decimal pct = 10m, string? undo = null, [FromServices] CrossBuy.BL.IPricingService pricing = null!)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1; const int list = 35;
			if (!string.IsNullOrEmpty(undo))
			{
				var (uok, uerr, ub, ur) = await pricing.BulkUndoAsync(company, Guid.Parse(undo), "regression restore", "dev");
				return Ok(new { undone = uok, restored = ur, error = uerr });
			}
			var (pok, perr, rows) = await pricing.BulkPreviewAsync(company, list, null, "Percent", pct, "None");
			if (!pok) return Ok(new { ok = false, error = perr });
			var baseline = rows.Select(r => new CrossBuy.BL.BulkBaselineItem { ItemId = r.ItemId, UoMId = r.UoMId, ExpectedOld = r.OldPrice }).ToList();
			var (eok, eerr, batch, ch) = await pricing.BulkExecuteAsync(company, list, null, "Percent", pct, "None", $"regression +{pct}%", baseline, "dev");
			int i1 = await _db.Items.Where(i => i.CompanyID == company && i.ItemCode == "HM-DEMO-001").Select(i => i.ID).FirstAsync();
			decimal newP = await _db.PriceListLines.AsNoTracking().Where(l => l.PriceListId == list && l.ItemId == i1).Select(l => l.UnitPrice ?? 0m).FirstAsync();
			return Ok(new { ok = eok, error = eerr, batch, changed = ch, hmDemo001New = newP });
		}

		// GET /api/dev/hm5-seed?key=seed123 — HM-5 promotions fixtures on list 35 (KWD). Two ZZ categories keep the
		// category promo isolated from the item/qty tests; the real HM-DEMO-001/003 stay for the item + weighted tests.
		[HttpGet("hm5-seed")]
		public async Task<IActionResult> Hm5Seed(string key)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1; const int list = 35; var log = new List<string>(); bool allPass = true;
			void Chk(string n, bool c) { log.Add((c ? "PASS " : "FAIL ") + n); if (!c) allPass = false; }
			var branch = await _db.Branches.FirstOrDefaultAsync(b => b.Name == "HYPER-DEMO");
			if (branch == null) return BadRequest(new { message = "run hyper-hm0-seed + hm1/2/3-seed first" });
			int bid = branch.ID;
			int kwd = await _db.Currencies.Where(c => c.Code == "KWD").Select(c => c.ID).FirstAsync();
			int pcs = await _db.UnitsOfMeasure.Where(u => u.CompanyID == company && u.Code == "PCS").Select(u => u.ID).FirstAsync();
			int i1 = await _db.Items.Where(i => i.CompanyID == company && i.ItemCode == "HM-DEMO-001").Select(i => i.ID).FirstAsync();
			int i3 = await _db.Items.Where(i => i.CompanyID == company && i.ItemCode == "HM-DEMO-003").Select(i => i.ID).FirstAsync();

			async Task<int> EnsureCat(string code, string name)
			{
				var c = await _db.ItemCategories.FirstOrDefaultAsync(x => x.CompanyID == company && x.Code == code);
				if (c == null) { c = new CrossBuy.Models.Context.Inventory.ItemCategory { CompanyID = company, Code = code, Name = name, NameEn = name, IsActive = true, CreatedAt = DateTime.UtcNow }; _db.ItemCategories.Add(c); await _db.SaveChangesAsync(); }
				return c.ID;
			}
			int zcatCat = await EnsureCat("ZZ-CATP", "ZZ فئة العرض");   // holds the category-promo members only
			int zcatItem = await EnsureCat("ZZ-PROMO", "ZZ عروض الصنف"); // holds the item/qty-promo members (no category promo)

			async Task<int> EnsureZz(string code, int catId, decimal price)
			{
				var it = await _db.Items.FirstOrDefaultAsync(i => i.CompanyID == company && i.ItemCode == code);
				if (it == null) { it = new CrossBuy.Models.Context.Inventory.Item { CompanyID = company, ItemCode = code, Barcode = "ZZBC-" + code, Name = code, NameEn = code, ItemCategoryId = catId, ItemType = "Stockable", BaseUoMId = pcs, IsActive = true, CostingMethod = "Average", SalesPrice = price, CreatedAt = DateTime.UtcNow }; _db.Items.Add(it); await _db.SaveChangesAsync(); }
				else { it.ItemCategoryId = catId; await _db.SaveChangesAsync(); }
				var l = await _db.PriceListLines.FirstOrDefaultAsync(x => x.PriceListId == list && x.ItemId == it.ID);
				// UoMId = null (base/any) so GetPriceAsync(..., uomId:null) resolves it — the null-unit fallback line.
				if (l == null) _db.PriceListLines.Add(new CrossBuy.Models.Context.Inventory.PriceListLine { PriceListId = list, ItemId = it.ID, UoMId = null, MinQty = 0, UnitPrice = price, PricingMode = "Fixed" });
				else { l.UnitPrice = price; l.MinQty = 0; l.UoMId = null; }
				await _db.SaveChangesAsync();
				return it.ID;
			}
			int cm1 = await EnsureZz("ZZ-CM1", zcatCat, 0.750m), cm2 = await EnsureZz("ZZ-CM2", zcatCat, 0.500m);
			int zp1 = await EnsureZz("ZZ-P1", zcatItem, 1.000m), zp2 = await EnsureZz("ZZ-P2", zcatItem, 1.000m), zp3 = await EnsureZz("ZZ-P3", zcatItem, 1.000m), zzero = await EnsureZz("ZZ-ZERO", zcatItem, 1.000m);

			var cap = await _db.BranchCapabilities.FirstOrDefaultAsync(x => x.BranchId == bid && x.CapabilityKey == "Promotions");
			if (cap == null) _db.BranchCapabilities.Add(new CrossBuy.Models.Context.Pos.BranchCapability { BranchId = bid, CapabilityKey = "Promotions", Enabled = true }); else cap.Enabled = true;
			await _db.SaveChangesAsync();

			// reseed ZZP promotions — clear then add in a FIXED order so the identical-pair IDs are deterministic.
			_db.Promotions.RemoveRange(_db.Promotions.Where(p => p.CompanyID == company && p.Code.StartsWith("ZZP-")));
			await _db.SaveChangesAsync();
			CrossBuy.Models.Context.Inventory.Promotion Pr(string code, string type, decimal val, int? itemId, int? catId, decimal minQty, int priority)
				=> new CrossBuy.Models.Context.Inventory.Promotion { CompanyID = company, Code = code, Name = code, DiscountType = type, Value = val, CurrencyId = type == "Amount" ? kwd : (int?)null, ItemId = itemId, ItemCategoryId = catId, MinQty = minQty, Priority = priority, IsActive = true, CreatedAt = DateTime.UtcNow };
			_db.Promotions.AddRange(
				Pr("ZZP-A", "Percent", 10m, i1, null, 1m, 0),          // T1 item 10%
				Pr("ZZP-CAT", "Amount", 0.100m, null, zcatCat, 1m, 0), // T2/T4 category amount
				Pr("ZZP-CM1", "Percent", 10m, cm1, null, 1m, 0),       // T4 item beats category
				Pr("ZZP-DET1", "Percent", 7m, zp1, null, 1m, 5),       // T3 identical pair
				Pr("ZZP-DET2", "Percent", 7m, zp1, null, 1m, 5),
				Pr("ZZP-PRIA", "Percent", 5m, zp3, null, 1m, 10),      // T5 priority beats amount
				Pr("ZZP-PRIB", "Percent", 8m, zp3, null, 1m, 1),
				Pr("ZZP-QTY", "Percent", 15m, zp2, null, 3m, 0),       // T6 qty break
				Pr("ZZP-WQTY", "Percent", 20m, i3, null, 3m, 0),       // T7 weighted qty break
				Pr("ZZP-100", "Percent", 100m, zzero, null, 1m, 0));   // T9 sell-guard
			await _db.SaveChangesAsync();

			Chk("ZZ categories + members + 10 ZZP promotions + Promotions capability ON", true);
			return Ok(new { allPass, i1, i3, cm1, cm2, zp1, zp2, zp3, zzero, list, kwd, log });
		}

		// GET /api/dev/hm5-accept?key=seed123 — HM-5 acceptance through the REAL services, every value re-read from DB.
		[HttpGet("hm5-accept")]
		public async Task<IActionResult> Hm5Accept(string key, [FromServices] CrossBuy.BL.IPricingService pricing, [FromServices] CrossBuy.BL.IPosOrderService posOrders, [FromServices] CrossBuy.BL.IPosSetupService posSetup)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1; const int bid = 17; const int list = 35; const int term = 1007; var log = new List<string>(); bool allPass = true;
			void Chk(string n, bool c) { log.Add((c ? "PASS " : "FAIL ") + n); if (!c) allPass = false; }
			int kwd = await _db.Currencies.Where(c => c.Code == "KWD").Select(c => c.ID).FirstAsync();
			int kg = await _db.UnitsOfMeasure.Where(u => u.CompanyID == company && u.Code == "KG").Select(u => u.ID).FirstAsync();
			int pcs = await _db.UnitsOfMeasure.Where(u => u.CompanyID == company && u.Code == "PCS").Select(u => u.ID).FirstAsync();
			async Task<int> Id(string code) => await _db.Items.Where(i => i.CompanyID == company && i.ItemCode == code).Select(i => i.ID).FirstAsync();
			int i1 = await Id("HM-DEMO-001"), i3 = await Id("HM-DEMO-003"), cm1 = await Id("ZZ-CM1"), cm2 = await Id("ZZ-CM2"), zp1 = await Id("ZZ-P1"), zp2 = await Id("ZZ-P2"), zp3 = await Id("ZZ-P3"), zzero = await Id("ZZ-ZERO");
			async Task<int> Pid(string code) => await _db.Promotions.Where(p => p.CompanyID == company && p.Code == code).Select(p => p.ID).FirstAsync();
			int paId = await Pid("ZZP-A"), pcatId = await Pid("ZZP-CAT"), pcm1 = await Pid("ZZP-CM1"), pdet1 = await Pid("ZZP-DET1"), ppria = await Pid("ZZP-PRIA"), pqty = await Pid("ZZP-QTY"), pwqty = await Pid("ZZP-WQTY");

			decimal Net(CrossBuy.BL.PriceResult r) => Math.Round(r.UnitPrice * (1 - r.DiscountPercent / 100m), 3, MidpointRounding.AwayFromZero);
			async Task<CrossBuy.BL.PriceResult> Price(int item, decimal qty, int? uom) => await pricing.GetPriceAsync(company, item, null, null, kwd, qty, DateTime.Today, list, uom, true);

			var p1 = await Price(i1, 1m, null);
			Chk("T1: 10% on 0.750 ⇒ net 0.675 (ZZP-A)", Net(p1) == 0.675m && p1.PromotionId == paId);
			var p2 = await Price(cm2, 1m, null);
			Chk("T2: category amount 0.100 on 0.500 ⇒ net 0.400 (ZZP-CAT)", Net(p2) == 0.400m && p2.PromotionId == pcatId);
			var p4 = await Price(cm1, 1m, null);
			Chk("T4: item 10% BEATS bigger category 0.100 ⇒ net 0.675 (ZZP-CM1, not ZZP-CAT)", Net(p4) == 0.675m && p4.PromotionId == pcm1 && p4.PromotionId != pcatId);
			log.Add($"  T1 net={Net(p1)}/{p1.PromotionId} · T2 net={Net(p2)}/{p2.PromotionId} · T4 net={Net(p4)}/{p4.PromotionId}");

			var winners = new HashSet<int?>();
			for (int k = 0; k < 10; k++) winners.Add((await Price(zp1, 1m, null)).PromotionId);
			Chk("T3: 10 identical-promo runs ⇒ ONE deterministic winner (lowest ID)", winners.Count == 1 && winners.First() == pdet1);
			log.Add($"  T3 winners={string.Join(",", winners)} (expected {pdet1})");

			var p5 = await Price(zp3, 1m, null);
			Chk("T5: Priority 10 (5%) beats Priority 1 (8%) ⇒ net 0.950 (ZZP-PRIA)", Net(p5) == 0.950m && p5.PromotionId == ppria);

			var p6a = await Price(zp2, 3m, null); var p6b = await Price(zp2, 2m, null);
			Chk("T6: qty-break MinQty=3 ⇒ qty3 net 0.850 (ZZP-QTY), qty2 net 1.000 (none)", Net(p6a) == 0.850m && p6a.PromotionId == pqty && Net(p6b) == 1.000m && p6b.PromotionId == null);

			var p7a = await Price(i3, 3.000m, kg); var p7b = await Price(i3, 2.500m, kg);
			Chk("T7: weighted MinQty=3 ⇒ 3.000kg net 2.800 (ZZP-WQTY), 2.500kg net 3.500 (none)", Net(p7a) == 2.800m && p7a.PromotionId == pwqty && Net(p7b) == 3.500m && p7b.PromotionId == null);
			log.Add($"  T7 3.0kg={Net(p7a)}/{p7a.PromotionId} · 2.5kg={Net(p7b)}/{p7b.PromotionId}");

			// T8 save guards
			CrossBuy.Models.Context.Inventory.Promotion G(string code, string type, decimal val) => new CrossBuy.Models.Context.Inventory.Promotion { Code = code, Name = code, DiscountType = type, Value = val, MinQty = 1, IsActive = true };
			var (g1ok, _, _, _) = await pricing.SavePromotionAsync(company, G("ZZG-150", "Percent", 150m), "dev");
			var (g2ok, _, _, _) = await pricing.SavePromotionAsync(company, G("ZZG-NEG", "Amount", -1m), "dev");
			var (g3ok, _, g3warn, _) = await pricing.SavePromotionAsync(company, G("ZZG-95", "Percent", 95m), "dev");
			Chk("T8: 150% rejected", !g1ok);
			Chk("T8: negative amount rejected", !g2ok);
			Chk("T8: 95% saved WITH warning", g3ok && !string.IsNullOrEmpty(g3warn)); log.Add("  T8 warn: " + g3warn);
			_db.Promotions.RemoveRange(_db.Promotions.Where(p => p.CompanyID == company && p.Code.StartsWith("ZZG-"))); await _db.SaveChangesAsync();

			async Task<int> OpenOrder() { await posSetup.OpenShiftAsync(term, "Morning", null, 0m); var sh = await posSetup.GetOpenShiftAsync(term); var (_, _, oid) = await posOrders.CreateOrderAsync(company, bid, "Takeaway", null, null, term, sh!.ID); return oid; }
			async Task CleanOrders()
			{
				_db.PosOrderLines.RemoveRange(await _db.PosOrderLines.Where(l => _db.PosOrders.Any(o => o.ID == l.OrderId && o.BranchId == bid && o.Status == "Open")).ToListAsync());
				await _db.SaveChangesAsync();
				_db.PosOrders.RemoveRange(await _db.PosOrders.Where(o => o.BranchId == bid && o.Status == "Open").ToListAsync());
				await _db.SaveChangesAsync();
				foreach (var s in await _db.PosShifts.Where(s => s.TerminalId == term && s.Status == "Open").ToListAsync()) { s.Status = "Closed"; s.ClosedAt = DateTime.UtcNow; }
				await _db.SaveChangesAsync();
			}

			await CleanOrders();
			var o9 = await OpenOrder();
			var (a9ok, a9err) = await posOrders.AddLineAsync(company, o9, zzero, 1m, null, pcs);
			Chk("T9: 100% discount ⇒ line rejected (net ≤ 0)", !a9ok); log.Add("  T9 " + a9err);
			await CleanOrders();

			var cap = await _db.BranchCapabilities.FirstAsync(x => x.BranchId == bid && x.CapabilityKey == "Promotions");
			cap.Enabled = false; await _db.SaveChangesAsync();
			var oOff = await OpenOrder(); await posOrders.AddLineAsync(company, oOff, i1, 1m, null, null);
			var offLine = await _db.PosOrderLines.AsNoTracking().Where(l => l.OrderId == oOff).OrderByDescending(l => l.ID).FirstAsync();
			Chk("T10: capability OFF ⇒ no promo (LineTotal 0.750, disc 0)", offLine.LineTotal == 0.750m && offLine.DiscountAmount == 0m);
			await CleanOrders();
			cap.Enabled = true; await _db.SaveChangesAsync();
			var oOn = await OpenOrder(); await posOrders.AddLineAsync(company, oOn, i1, 1m, null, null);
			var onLine = await _db.PosOrderLines.AsNoTracking().Where(l => l.OrderId == oOn).OrderByDescending(l => l.ID).FirstAsync();
			Chk("T10: capability ON ⇒ promo applies (LineTotal 0.675)", onLine.LineTotal == 0.675m);
			log.Add($"  T10 OFF LineTotal={offLine.LineTotal} · ON LineTotal={onLine.LineTotal}");
			await CleanOrders();

			return Ok(new { allPass, log });
		}

		// GET /api/dev/hm-guard-test?key=seed123 — HM-D45 (table-existence) + HM-D53 (writer-coupling) guards, with a
		// POSITIVE proof: a fabricated absent table is detected MISSING (so the check is not a hollow zero), and the
		// coupling detector names the GL-writer's kernel dependency.
		[HttpGet("hm-guard-test")]
		public async Task<IActionResult> HmGuardTest(string key, [FromServices] CrossBuy.BL.IIntegrityCheckService integrity)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1; var log = new List<string>(); bool allPass = true;
			void Chk(string n, bool c) { log.Add((c ? "PASS " : "FAIL ") + n); if (!c) allPass = false; }
			var checks = await integrity.RunAsync(company);
			var tbl = checks.FirstOrDefault(c => c.Key == "dbset_tables_exist");
			var cpl = checks.FirstOrDefault(c => c.Key == "writer_coupling");
			Chk("HM-D45 present & GREEN (0 critical tables missing)", tbl != null && tbl.Ok);
			log.Add("  dbset_tables_exist: Ok=" + tbl?.Ok + " · " + tbl?.Note);
			Chk("HM-D53 detector present & shows exactly ONE coupling", cpl != null && cpl.Actual == 1m);
			Chk("HM-D53 names it: JournalEntryService:IBusinessEventService", cpl?.Note != null && cpl.Note.Contains("JournalEntryService:IBusinessEventService"));
			Chk("HM-D53 StockService NOT flagged (clean)", cpl?.Note != null && !cpl.Note.Contains("StockService:"));
			log.Add("  writer_coupling: Actual=" + cpl?.Actual + " · " + cpl?.Note);
			// POSITIVE proof the existence logic isn't a hollow zero: a crafted absent name → 0, a real table → 1.
			int fake = await _db.Database.SqlQueryRaw<int>("SELECT CASE WHEN EXISTS(SELECT 1 FROM sys.tables WHERE name='__zz_nonexistent_table__') THEN 1 ELSE 0 END AS Value").FirstAsync();
			int real = await _db.Database.SqlQueryRaw<int>("SELECT CASE WHEN EXISTS(SELECT 1 FROM sys.tables WHERE name='JournalEntries') THEN 1 ELSE 0 END AS Value").FirstAsync();
			Chk("HM-D45 positive proof: fabricated absent table → MISSING, real table → PRESENT", fake == 0 && real == 1);
			log.Add($"  crafted: fake table present={fake} (expect 0) · JournalEntries present={real} (expect 1)");
			return Ok(new { allPass, log });
		}

		// GET /api/dev/hm6-seed?key=seed123 — HM-6 expiry/batch fixtures via PostOpeningStockAsync (fill-to-floor):
		// ZZ-EXP (numeric, TrackExpiry) with LOT-A(+10d,100)/LOT-B(+60d,100)/LOT-EXP(-5d,50); ZZ-WEXP (weighted,
		// TrackExpiry) with WLOT-A(+5d,0.500kg)/WLOT-B(+40d,2.000kg) for the fractional split test.
		[HttpGet("hm6-seed")]
		public async Task<IActionResult> Hm6Seed(string key, [FromServices] CrossBuy.BL.IStockService stock)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1; var log = new List<string>(); bool allPass = true;
			void Chk(string n, bool c) { log.Add((c ? "PASS " : "FAIL ") + n); if (!c) allPass = false; }
			var branch = await _db.Branches.FirstOrDefaultAsync(b => b.Name == "HYPER-DEMO");
			if (branch == null) return BadRequest(new { message = "run hyper-hm0-seed + hm1/2/3-seed first" });
			int wh = await _db.BranchPosSettings.Where(s => s.BranchId == branch.ID).Select(s => s.DefaultSalesWarehouseId ?? 0).FirstOrDefaultAsync();
			if (wh == 0) wh = await _db.Warehouses.Where(w => w.CompanyID == company).Select(w => w.ID).FirstAsync();
			int pcs = await _db.UnitsOfMeasure.Where(u => u.CompanyID == company && u.Code == "PCS").Select(u => u.ID).FirstAsync();
			int kg = await _db.UnitsOfMeasure.Where(u => u.CompanyID == company && u.Code == "KG").Select(u => u.ID).FirstAsync();
			int hcat = await _db.ItemCategories.Where(c => c.CompanyID == company && c.Code == "HYPER-CAT").Select(c => c.ID).FirstAsync();

			async Task<int> EnsureExpItem(string code, int uom, bool weighted, int? scale)
			{
				var it = await _db.Items.FirstOrDefaultAsync(i => i.CompanyID == company && i.ItemCode == code);
				if (it == null) { it = new CrossBuy.Models.Context.Inventory.Item { CompanyID = company, ItemCode = code, Barcode = "ZZBC-" + code, Name = code, NameEn = code, ItemCategoryId = hcat, ItemType = "Stockable", BaseUoMId = uom, TrackExpiry = true, TrackBatch = false, IsWeighted = weighted, ScaleCode = scale, IsActive = true, CostingMethod = "Average", SalesPrice = 1m, CreatedAt = DateTime.UtcNow }; _db.Items.Add(it); await _db.SaveChangesAsync(); }
				else { it.TrackExpiry = true; it.BaseUoMId = uom; it.IsWeighted = weighted; it.ScaleCode = scale; await _db.SaveChangesAsync(); }
				return it.ID;
			}
			int expId = await EnsureExpItem("ZZ-EXP", pcs, false, null);
			int wexpId = await EnsureExpItem("ZZ-WEXP", kg, true, 39001);

			async Task Fill(int itemId, string lot, DateTime exp, decimal floor, decimal cost)
			{
				int? bid = await _db.StockBatches.Where(b => b.CompanyID == company && b.ItemId == itemId && b.BatchNo == lot).Select(b => (int?)b.ID).FirstOrDefaultAsync();
				decimal cur = bid == null ? 0m : (await _db.StockMovements.Where(m => m.ItemId == itemId && m.WarehouseId == wh && m.BatchId == bid).SumAsync(m => (decimal?)(m.Direction * m.QtyBase)) ?? 0m);
				if (cur < floor) { var (ok, err, _, _) = await stock.PostOpeningStockAsync(company, DateTime.Today, new List<CrossBuy.BL.OpeningStockLineInput> { new() { ItemId = itemId, WarehouseId = wh, Qty = floor - cur, UnitCost = cost, BatchNo = lot, Expiry = exp } }, "dev"); if (!ok) log.Add($"  fill {lot} err: {err}"); }
			}
			var T = DateTime.Today;
			await Fill(expId, "LOT-A", T.AddDays(10), 100m, 2m);
			await Fill(expId, "LOT-B", T.AddDays(60), 100m, 2m);
			await Fill(expId, "LOT-EXP", T.AddDays(-5), 50m, 2m);
			await Fill(wexpId, "WLOT-A", T.AddDays(5), 0.500m, 450m);
			await Fill(wexpId, "WLOT-B", T.AddDays(40), 2.000m, 450m);

			Chk("ZZ-EXP + ZZ-WEXP (TrackExpiry) with dated batches via PostOpeningStockAsync", true);
			return Ok(new { allPass, expId, wexpId, wh, log });
		}

		// GET /api/dev/hm6-accept?key=seed123 — HM-6 acceptance through the REAL StockService/ItemService, read from DB.
		[HttpGet("hm6-accept")]
		public async Task<IActionResult> Hm6Accept(string key, [FromServices] CrossBuy.BL.IStockService stock, [FromServices] CrossBuy.BL.IItemService items, [FromServices] CrossBuy.BL.IIntegrityCheckService integrity)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1; var log = new List<string>(); bool allPass = true;
			void Chk(string n, bool c) { log.Add((c ? "PASS " : "FAIL ") + n); if (!c) allPass = false; }
			int branchId = await _db.Branches.Where(b => b.Name == "HYPER-DEMO").Select(b => b.ID).FirstAsync();
			int wh = await _db.BranchPosSettings.Where(s => s.BranchId == branchId).Select(s => s.DefaultSalesWarehouseId ?? 0).FirstOrDefaultAsync();
			if (wh == 0) wh = await _db.Warehouses.Where(w => w.CompanyID == company).Select(w => w.ID).FirstAsync();
			int pcs = await _db.UnitsOfMeasure.Where(u => u.CompanyID == company && u.Code == "PCS").Select(u => u.ID).FirstAsync();
			int kg = await _db.UnitsOfMeasure.Where(u => u.CompanyID == company && u.Code == "KG").Select(u => u.ID).FirstAsync();
			int hcat = await _db.ItemCategories.Where(c => c.CompanyID == company && c.Code == "HYPER-CAT").Select(c => c.ID).FirstAsync();
			int expId = await _db.Items.Where(i => i.CompanyID == company && i.ItemCode == "ZZ-EXP").Select(i => i.ID).FirstAsync();
			int wexpId = await _db.Items.Where(i => i.CompanyID == company && i.ItemCode == "ZZ-WEXP").Select(i => i.ID).FirstAsync();
			var T = DateTime.Today;

			async Task<decimal> Batch(int itemId, string lot)
			{
				int? bid = await _db.StockBatches.AsNoTracking().Where(b => b.CompanyID == company && b.ItemId == itemId && b.BatchNo == lot).Select(b => (int?)b.ID).FirstOrDefaultAsync();
				return bid == null ? 0m : (await _db.StockMovements.AsNoTracking().Where(m => m.ItemId == itemId && m.WarehouseId == wh && m.BatchId == bid).SumAsync(m => (decimal?)(m.Direction * m.QtyBase)) ?? 0m);
			}
			async Task Fill(int itemId, string lot, DateTime exp, decimal floor, decimal cost)
			{
				decimal cur = await Batch(itemId, lot);
				if (cur < floor) await stock.PostOpeningStockAsync(company, DateTime.Today, new List<CrossBuy.BL.OpeningStockLineInput> { new() { ItemId = itemId, WarehouseId = wh, Qty = floor - cur, UnitCost = cost, BatchNo = lot, Expiry = exp } }, "dev");
			}
			async Task Reseed()
			{
				await Fill(expId, "LOT-A", T.AddDays(10), 100m, 2m); await Fill(expId, "LOT-B", T.AddDays(60), 100m, 2m); await Fill(expId, "LOT-EXP", T.AddDays(-5), 50m, 2m);
				await Fill(wexpId, "WLOT-A", T.AddDays(5), 0.500m, 450m); await Fill(wexpId, "WLOT-B", T.AddDays(40), 2.000m, 450m);
			}
			async Task<(bool ok, string? err)> Issue(int itemId, decimal qty, int uom, string src, string? batch = null)
			{
				var (ok, err, _) = await stock.PostMovementAsync(company, new CrossBuy.BL.MovementRequest { Date = T, ItemId = itemId, WarehouseId = wh, Direction = -1, Qty = qty, UoMId = uom, SourceType = src, BatchNo = batch, PostToGl = false, Notes = "hm6" }, "dev");
				return (ok, err);
			}

			// T1: FEFO sells from LOT-A (nearest expiry) first
			await Reseed();
			await Issue(expId, 30m, pcs, "Issue");
			Chk("T1: sell 30 ⇒ FEFO from LOT-A (100→70), LOT-B untouched (100)", await Batch(expId, "LOT-A") == 70m && await Batch(expId, "LOT-B") == 100m);
			log.Add($"  T1 LOT-A={await Batch(expId, "LOT-A")} LOT-B={await Batch(expId, "LOT-B")}");

			// T2: sell 150 ⇒ 100 from A + 50 from B
			await Reseed();
			await Issue(expId, 150m, pcs, "Issue");
			Chk("T2: sell 150 ⇒ LOT-A→0, LOT-B→50 (split across two batches)", await Batch(expId, "LOT-A") == 0m && await Batch(expId, "LOT-B") == 50m);
			log.Add($"  T2 LOT-A={await Batch(expId, "LOT-A")} LOT-B={await Batch(expId, "LOT-B")}");

			// T3: weighted 0.755 kg ⇒ 0.500 from WLOT-A + 0.255 from WLOT-B (fractional split, exact)
			await Reseed();
			await Issue(wexpId, 0.755m, kg, "Issue");
			decimal wa = await Batch(wexpId, "WLOT-A"), wbq = await Batch(wexpId, "WLOT-B");
			Chk("T3: weighted 0.755kg ⇒ WLOT-A 0.500→0.000, WLOT-B 2.000→1.745 (Σ drawn = 0.755 exact)", wa == 0.000m && wbq == 1.745m);
			log.Add($"  T3 WLOT-A={wa} WLOT-B={wbq} drawn={0.500m + (2.000m - wbq)}");

			// T4: named expired batch blocked; FEFO excludes expired and reports it
			await Reseed();
			var (n4ok, n4err) = await Issue(expId, 5m, pcs, "Issue", "LOT-EXP");
			Chk("T4a: named expired batch ⇒ blocked", !n4ok && (n4err ?? "").Contains("منتهية"));
			var (f4ok, f4err) = await Issue(expId, 250m, pcs, "Issue");   // > valid 200, so 50 expired excluded
			Chk("T4b: FEFO short ⇒ excludes expired, clear message", !f4ok && (f4err ?? "").Contains("مستبعَد") && (f4err ?? "").Contains("منتهية"));
			log.Add($"  T4 named='{n4err}' · fefo='{f4err}'");

			// T5: input without a batch rejected in each user path (zero effect)
			await Reseed();
			var (o5ok, o5err, _, _) = await stock.PostOpeningStockAsync(company, T, new List<CrossBuy.BL.OpeningStockLineInput> { new() { ItemId = expId, WarehouseId = wh, Qty = 5m, UnitCost = 2m } }, "dev");
			var (r5ok, r5err, _) = await stock.PostMovementAsync(company, new CrossBuy.BL.MovementRequest { Date = T, ItemId = expId, WarehouseId = wh, Direction = 1, Qty = 5m, UoMId = pcs, SourceType = "Receipt", PostToGl = false }, "dev");
			var (a5ok, a5err, _) = await stock.PostMovementAsync(company, new CrossBuy.BL.MovementRequest { Date = T, ItemId = expId, WarehouseId = wh, Direction = 1, Qty = 5m, UoMId = pcs, SourceType = "Adjustment", PostToGl = false }, "dev");
			var (w5ok, w5err, _) = await stock.PostMovementAsync(company, new CrossBuy.BL.MovementRequest { Date = T, ItemId = expId, WarehouseId = wh, Direction = -1, Qty = 5m, UoMId = pcs, SourceType = "StockWriteOff", PostToGl = false }, "dev");
			Chk("T5: opening/receipt/adjustment/write-off WITHOUT batch ⇒ all rejected", !o5ok && !r5ok && !a5ok && !w5ok);
			log.Add($"  T5 opening='{o5err}' receipt='{r5err}' adj='{a5err}' writeoff='{w5err}'");

			// T6: unbatched physical stock ⇒ the NEW clear message (not 'available 0')
			var ub = await _db.Items.FirstOrDefaultAsync(i => i.CompanyID == company && i.ItemCode == "ZZ-UNBATCH");
			if (ub == null) { ub = new CrossBuy.Models.Context.Inventory.Item { CompanyID = company, ItemCode = "ZZ-UNBATCH", Barcode = "ZZBC-UNBATCH", Name = "ZZ unbatched", NameEn = "ZZ unbatched", ItemCategoryId = hcat, ItemType = "Stockable", BaseUoMId = pcs, TrackExpiry = true, IsActive = true, CostingMethod = "Average", CreatedAt = DateTime.UtcNow }; _db.Items.Add(ub); await _db.SaveChangesAsync(); }
			// craft unbatched physical stock directly (bypassing the guard) — legacy footprint
			if (await Batch(ub.ID, "") == 0m && !(await _db.StockMovements.AnyAsync(m => m.ItemId == ub.ID && m.BatchId == null && m.Direction == 1)))
			{
				_db.StockMovements.Add(new CrossBuy.Models.Context.Inventory.StockMovement { CompanyID = company, MovementNo = "ZZUB-1", MovementDate = T, ItemId = ub.ID, WarehouseId = wh, Direction = 1, QtyBase = 50m, QtyInUoM = 50m, UoMId = pcs, UnitCost = 2m, TotalCost = 100m, SourceType = "LegacyUnbatched", CreatedAt = DateTime.UtcNow });
				var sb = await _db.StockBalances.FirstOrDefaultAsync(b => b.CompanyID == company && b.ItemId == ub.ID && b.WarehouseId == wh);
				if (sb == null) _db.StockBalances.Add(new CrossBuy.Models.Context.Inventory.StockBalance { CompanyID = company, ItemId = ub.ID, WarehouseId = wh, QtyOnHand = 50m, TotalValue = 100m, AvgCost = 2m }); else { sb.QtyOnHand += 50m; sb.TotalValue += 100m; }
				await _db.SaveChangesAsync();
			}
			var (u6ok, u6err) = await Issue(ub.ID, 10m, pcs, "Issue");
			Chk("T6: unbatched physical stock ⇒ clear data-correction message (not 'available 0')", !u6ok && (u6err ?? "").Contains("غير مرتبط بدفعات"));
			log.Add($"  T6 '{u6err}'");
			// teardown the crafted ZZ-UNBATCH so this test leaves NO residue in the counted classification (our rule:
			// no test leaves an inv-test-integrity deviation). The issue above was blocked, so there is no out-movement.
			_db.StockMovements.RemoveRange(await _db.StockMovements.Where(m => m.ItemId == ub.ID).ToListAsync());
			_db.StockBalances.RemoveRange(await _db.StockBalances.Where(b => b.ItemId == ub.ID).ToListAsync());
			_db.ItemBarcodes.RemoveRange(await _db.ItemBarcodes.Where(z => z.ItemId == ub.ID).ToListAsync());
			await _db.SaveChangesAsync();
			var ubGone = await _db.Items.FindAsync(ub.ID); if (ubGone != null) { _db.Items.Remove(ubGone); await _db.SaveChangesAsync(); }

			// T7: write off an expired batch ⇒ posts to 510103, balance drops
			await Reseed();
			decimal expBefore = await Batch(expId, "LOT-EXP");
			var (wo7ok, wo7err, _, _, _) = await stock.WriteOffAsync(company, wh, T, "Expired", "hm6 expired write-off", new List<CrossBuy.BL.WriteOffLineInput> { new() { ItemId = expId, Qty = 10m, UoMId = pcs, BatchNo = "LOT-EXP", Reason = "Expired" } }, "dev");
			decimal expAfter = await Batch(expId, "LOT-EXP");
			int woAcc = await _db.Accounts.Where(a => a.CompanyID == company && a.Code == "510103").Select(a => a.ID).FirstOrDefaultAsync();
			bool wo510103 = await _db.JournalEntryLines.AnyAsync(l => l.AccountId == woAcc && l.Debit > 0 && _db.JournalEntries.Any(j => j.ID == l.JournalEntryId && j.SourceType == "StockWriteOff"));
			Chk("T7: expired write-off ⇒ ok, LOT-EXP 50→40, 510103 debited", wo7ok && expBefore == 50m && expAfter == 40m && wo510103);
			log.Add($"  T7 ok={wo7ok} before={expBefore} after={expAfter} 510103={wo510103} err={wo7err}");

			// T8: ExpiryAlerts data shows LOT-A (near) + LOT-EXP (expired)
			var alertRows = await _db.StockBatches.AsNoTracking().Where(b => b.CompanyID == company && b.ItemId == expId)
				.Select(b => new { b.BatchNo, b.ExpiryDate }).ToListAsync();
			bool hasNear = alertRows.Any(r => r.BatchNo == "LOT-A" && r.ExpiryDate != null && (r.ExpiryDate.Value.Date - T).TotalDays is > 0 and <= 30);
			bool hasExpired = alertRows.Any(r => r.BatchNo == "LOT-EXP" && r.ExpiryDate != null && r.ExpiryDate.Value.Date < T);
			Chk("T8: ExpiryAlerts shows LOT-A (near) + LOT-EXP (expired)", hasNear && hasExpired);

			// T9: TrackBatch decision — rejected without TrackExpiry, allowed with it
			async Task CleanTb()
			{
				_db.ItemBarcodes.RemoveRange(await _db.ItemBarcodes.Where(z => z.Barcode == "ZZBC-ZZ-TB-ONLY" || z.Barcode == "ZZBC-ZZ-TB-EXP").ToListAsync());
				_db.Items.RemoveRange(await _db.Items.Where(i => i.CompanyID == company && (i.ItemCode == "ZZ-TB-ONLY" || i.ItemCode == "ZZ-TB-EXP")).ToListAsync());
				await _db.SaveChangesAsync();
			}
			await CleanTb();   // idempotency: remove any leftover items AND their orphan ItemBarcodes rows
			CrossBuy.BL.ItemInput Mk(string code, bool batch, bool expiry) => new CrossBuy.BL.ItemInput { ItemCode = code, Barcode = "ZZBC-" + code, Name = "zz", NameEn = "zz", ItemCategoryId = hcat, ItemType = "Stockable", BaseUoMId = pcs, CostingMethod = "Average", TrackBatch = batch, TrackExpiry = expiry, IsActive = true };
			var (t9aok, t9aerr, _) = await items.CreateItemAsync(company, Mk("ZZ-TB-ONLY", true, false), null);
			var (t9bok, t9berr, _) = await items.CreateItemAsync(company, Mk("ZZ-TB-EXP", true, true), null);
			Chk("T9: TrackBatch without TrackExpiry ⇒ rejected", !t9aok); log.Add("  T9a " + t9aerr);
			Chk("T9: TrackBatch WITH TrackExpiry ⇒ allowed", t9bok); log.Add("  T9b " + t9berr);
			await CleanTb();

			// classification count
			var cls = (await integrity.RunAsync(company)).First(c => c.Key == "unbatched_inbound_tracked");
			log.Add($"  classification unbatched_inbound_tracked: Actual={cls.Actual} · {cls.Note}");
			return Ok(new { allPass, log });
		}

		// GET /api/dev/hm16-accept?key=seed123 — HM-16 purchase-model unification acceptance. Reads EVERY number FROM THE
		// DB (never from the entity that wrote it): GRN posts Dr 1103 / Cr 210203 (GRNI); the GRN-matched invoice clears
		// GRNI (Dr 210203 / Cr AP) with NO second stock movement; a GRN is invoiced at most once (set-once); a standalone
		// invoice still receives stock once; a value-mismatch match is refused; a TrackExpiry GRN forces a batch; the
		// 210203 rename reads back; a purchase return on a matched invoice posts correctly. Ends with the global integrity
		// run (failedCount must stay at the documented baseline) + the open-GRNI pre/post-cutoff counts.
		[HttpGet("hm16-accept")]
		public async Task<IActionResult> Hm16Accept(string key, [FromServices] CrossBuy.BL.IIntegrityCheckService integrity)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1; var log = new List<string>(); bool allPass = true;
			void Chk(string n, bool c) { log.Add((c ? "PASS " : "FAIL ") + n); if (!c) allPass = false; }
			decimal R(decimal v) => Math.Round(v, 2, MidpointRounding.AwayFromZero);
			var T = DateTime.Today;
			// BusinessContext is seeded centrally by OnActionExecutionAsync (HM-D58 dev-context filter); the chosen
			// employee is reported in the X-Dev-Context response header. No per-endpoint seeding here — one mechanism.

			int wh = await _db.Warehouses.Where(w => w.CompanyID == company).OrderBy(w => w.ID).Select(w => w.ID).FirstAsync();
			int pcs = await _db.UnitsOfMeasure.Where(u => u.CompanyID == company && u.Code == "PCS").Select(u => u.ID).FirstAsync();
			int acc1103 = await _db.Accounts.Where(a => a.CompanyID == company && a.Code == "1103").Select(a => a.ID).FirstAsync();
			int accGrni = await _db.Accounts.Where(a => a.CompanyID == company && a.Code == "210203").Select(a => a.ID).FirstAsync();

			async Task<decimal> NetId(int id) => await _db.JournalEntryLines.Where(l => l.AccountId == id).SumAsync(l => (decimal?)(l.Debit - l.Credit)) ?? 0m;
			async Task<decimal> Net(string code) { var id = await _db.Accounts.Where(a => a.CompanyID == company && a.Code == code).Select(a => (int?)a.ID).FirstOrDefaultAsync(); return id == null ? 0m : await NetId(id.Value); }
			async Task<decimal> Qty(int itemId) => (await _stock.GetBalanceAsync(company, itemId, wh)).qty;

			// ---- fixtures (idempotent; ZZ-* only) ----
			var ven = await _db.Vendors.FirstOrDefaultAsync(v => v.CompanyID == company && v.Name == "ZZ-HM16-VEN");
			if (ven == null) ven = await _ap.CreateVendorAsync(company, "ZZ-HM16-VEN", "ZZ HM16 vendor", null);
			int apId = ven.ControlAccountId;
			var cat = await _db.ItemCategories.FirstOrDefaultAsync(c => c.CompanyID == company && c.Code == "ZZ-HM16-CAT");
			if (cat == null) { cat = new CrossBuy.Models.Context.Inventory.ItemCategory { CompanyID = company, Code = "ZZ-HM16-CAT", Name = "ZZ HM16 cat", NameEn = "ZZ HM16 cat", InventoryAccountId = acc1103, GrniAccountId = accGrni, DefaultCostingMethod = "Average" }; _db.ItemCategories.Add(cat); await _db.SaveChangesAsync(); }
			async Task<CrossBuy.Models.Context.Inventory.Item> Item(string code, bool expiry)
			{
				var it = await _db.Items.FirstOrDefaultAsync(i => i.CompanyID == company && i.ItemCode == code);
				if (it == null) { it = new CrossBuy.Models.Context.Inventory.Item { CompanyID = company, ItemCode = code, Barcode = "ZZBC-" + code, Name = code, NameEn = code, ItemCategoryId = cat.ID, ItemType = "Stockable", BaseUoMId = pcs, TrackExpiry = expiry, IsActive = true, CostingMethod = "Average", CreatedAt = DateTime.UtcNow }; _db.Items.Add(it); await _db.SaveChangesAsync(); }
				return it;
			}
			var itm = await Item("ZZ-HM16-ITM", false);
			var exp = await Item("ZZ-HM16-EXP", true);

			async Task<(bool ok, string? err, CrossBuy.Models.Context.Inventory.GoodsReceipt? gr)> Grn(int itemId, decimal qty, decimal cost, string? batch = null, DateTime? expiry = null) =>
				await _proc.CreateReceiptAsync(company, ven.ID, wh, null, T, "hm16", new List<CrossBuy.BL.ReceiptLineInput> { new() { ItemId = itemId, Qty = qty, UnitCost = cost, BatchNo = batch, Expiry = expiry } }, "dev");

			// ===== T1: GRN receipt of a stockable ⇒ Dr 1103 / Cr 210203, stock +qty =====
			decimal b1 = await Net("1103"), bG1 = await NetId(accGrni), bQ1 = await Qty(itm.ID);
			var (g1ok, g1err, gr1) = await Grn(itm.ID, 10m, 5m);   // TotalCost 50
			decimal a1 = await Net("1103"), aG1 = await NetId(accGrni), aQ1 = await Qty(itm.ID);
			Chk("T1 GRN: Dr 1103 +50 / Cr 210203 -50 · stock +10", g1ok && R(a1 - b1) == 50m && R(aG1 - bG1) == -50m && R(aQ1 - bQ1) == 10m);
			log.Add($"  T1 d1103={R(a1 - b1)} dGRNI={R(aG1 - bG1)} dQty={R(aQ1 - bQ1)} grnTotal={gr1?.TotalCost}");

			// ===== T2: match that GRN ⇒ Dr 210203 / Cr AP · NO 2nd stock move · GRN stamped · GRNI pair nets to 0 =====
			decimal bG2 = await NetId(accGrni), bAP2 = await NetId(apId), bQ2 = await Qty(itm.ID);
			var (m2ok, m2err, inv2) = await _ap.MatchGoodsReceiptToInvoiceAsync(company, gr1!.ID, T, gr1.TotalCost, null);
			decimal aG2 = await NetId(accGrni), aAP2 = await NetId(apId), aQ2 = await Qty(itm.ID);
			int? stamp = await _db.GoodsReceipts.AsNoTracking().Where(g => g.ID == gr1.ID).Select(g => g.InvoiceId).FirstAsync();
			Chk("T2 match: Dr 210203 +50 / Cr AP -50 · NO new stock · GRN stamped Invoiced", m2ok && R(aG2 - bG2) == 50m && R(aAP2 - bAP2) == -50m && aQ2 == bQ2 && stamp != null);
			Chk("T2 GRNI for this GRN cleared to 0 (receive Cr50 then invoice Dr50 net out)", R(aG2 - bG1) == 0m);
			log.Add($"  T2 dGRNI={R(aG2 - bG2)} dAP={R(aAP2 - bAP2)} dQty={R(aQ2 - bQ2)} stamp={stamp} pairNet={R(aG2 - bG1)}");

			// ===== T3: invoice the SAME GRN again ⇒ rejected, zero effect =====
			decimal bAP3 = await NetId(apId);
			var (m3ok, m3err, _) = await _ap.MatchGoodsReceiptToInvoiceAsync(company, gr1.ID, T, gr1.TotalCost, null);
			Chk("T3 re-invoice same GRN ⇒ rejected (set-once) · AP unchanged", !m3ok && (m3err ?? "").Contains("مُفوتَر") && R(await NetId(apId) - bAP3) == 0m);
			log.Add($"  T3 ok={m3ok} err='{m3err}'");

			// ===== T4: standalone invoice (no GRN) ⇒ Dr 1103 / Cr AP + ONE stock movement (behaviour preserved) =====
			decimal b4 = await Net("1103"), bAP4 = await NetId(apId), bQ4 = await Qty(itm.ID);
			var (i4ok, i4err, inv4) = await _ap.CreatePurchaseInvoiceAsync(company, ven.ID, T, new List<CrossBuy.BL.PurchaseLineInput> { new() { ItemDescription = "ZZ standalone", Qty = 3m, UnitPrice = 20m, TaxRate = 0, ExpenseAccountId = acc1103, ItemId = itm.ID, WarehouseId = wh } }, "hm16 T4", null);
			decimal a4 = await Net("1103"), aAP4 = await NetId(apId), aQ4 = await Qty(itm.ID);
			Chk("T4 standalone (no GRN): Dr 1103 +60 / Cr AP -60 · stock +3 (one movement)", i4ok && R(a4 - b4) == 60m && R(aAP4 - bAP4) == -60m && R(aQ4 - bQ4) == 3m);
			log.Add($"  T4 d1103={R(a4 - b4)} dAP={R(aAP4 - bAP4)} dQty={R(aQ4 - bQ4)}");

			// ===== T5: match with an amount ≠ received value ⇒ refused (price variance deferred); correct amount succeeds =====
			var (g5ok, _, gr5) = await Grn(itm.ID, 4m, 7m);   // TotalCost 28
			decimal bAP5 = await NetId(apId);
			var (m5ok, m5err, _) = await _ap.MatchGoodsReceiptToInvoiceAsync(company, gr5!.ID, T, 30m, null);   // 30 ≠ 28
			int? open5 = await _db.GoodsReceipts.AsNoTracking().Where(g => g.ID == gr5.ID).Select(g => g.InvoiceId).FirstAsync();
			Chk("T5a mismatch amount ⇒ refused · GRN stays open · AP unchanged", !m5ok && (m5err ?? "").Contains("تختلف") && open5 == null && R(await NetId(apId) - bAP5) == 0m);
			var (m5bok, m5berr, _) = await _ap.MatchGoodsReceiptToInvoiceAsync(company, gr5.ID, T, gr5.TotalCost, null);
			Chk("T5b correct amount ⇒ match succeeds · GRN closed", m5bok && (await _db.GoodsReceipts.AsNoTracking().Where(g => g.ID == gr5.ID).Select(g => g.InvoiceId).FirstAsync()) != null);
			log.Add($"  T5 mismatchErr='{m5err}' correctOk={m5bok}");

			// ===== T6: GRN of a TrackExpiry item WITHOUT a batch ⇒ rejected; WITH a batch ⇒ succeeds, movement carries BatchId =====
			var (g6aok, g6aerr, _) = await Grn(exp.ID, 5m, 3m);   // no batch
			Chk("T6a GRN of TrackExpiry item WITHOUT batch ⇒ rejected (HM-6 guard covers the GRN path)", !g6aok && (g6aerr ?? "").Contains("الدفعة"));
			var (g6bok, g6berr, gr6) = await Grn(exp.ID, 5m, 3m, "ZZ-H16-LOT", T.AddDays(90));
			bool mvBatched = gr6 != null && await _db.StockMovements.AsNoTracking().AnyAsync(m => m.SourceType == "Receipt" && m.SourceId == gr6.ID && m.BatchId != null);
			Chk("T6b GRN WITH batch ⇒ succeeds · movement carries BatchId", g6bok && mvBatched);
			if (gr6 != null) await _ap.MatchGoodsReceiptToInvoiceAsync(company, gr6.ID, T, gr6.TotalCost, null);   // close it so no ZZ GRN is left open
			log.Add($"  T6 noBatchErr='{g6aerr}' batched={mvBatched}");

			// ===== T7: purchase return on the GRN-matched invoice ⇒ Dr AP / Cr GRNI + stock out, subledgers reconcile =====
			decimal bAP7 = await NetId(apId), bG7 = await NetId(accGrni), bQ7 = await Qty(itm.ID);
			var (r7ok, r7err, ret7) = await _ap.CreatePurchaseReturnAsync(company, ven.ID, inv2?.ID, T, new List<CrossBuy.BL.PurchaseLineInput> { new() { ItemId = itm.ID, WarehouseId = wh, Qty = 2m } }, "hm16 T7 return", null);
			decimal aAP7 = await NetId(apId), aG7 = await NetId(accGrni), aQ7 = await Qty(itm.ID);
			// three-way: the stock-out posts Dr GRNI / Cr Inventory AND the debit-note posts Dr AP / Cr GRNI ⇒ GRNI nets to 0.
			Chk("T7 return on matched invoice: AP debited (payable ↓) · stock -2 · GRNI nets to 0 (three-way)", r7ok && (aAP7 - bAP7) > 0m && R(aG7 - bG7) == 0m && R(aQ7 - bQ7) == -2m);
			log.Add($"  T7 ok={r7ok} dAP={R(aAP7 - bAP7)} dGRNI={R(aG7 - bG7)} dQty={R(aQ7 - bQ7)} err='{r7err}'");

			// ===== T8: 210203 reads under its new GRNI name · 210205 (payroll tax) empty · 210202 (WHT) present =====
			var a203 = await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.Code == "210203").Select(a => new { a.Name, a.NameEn }).FirstAsync();
			bool has205 = await _db.Accounts.AnyAsync(a => a.CompanyID == company && a.Code == "210205");
			decimal n205 = await Net("210205");
			Chk("T8 210203 renamed to GRNI (apply hm16_rename_grni.sql if this fails)", a203.NameEn == "Goods Received Not Invoiced (GRNI)");
			Chk("T8 210205 payroll-tax account still empty (no postings) · 210202 WHT untouched", n205 == 0m);
			log.Add($"  T8 210203='{a203.NameEn}' / '{a203.Name}' · 210205 exists={has205} net={n205}");

			// teardown: CLOSE (by matching, not deleting — reverse-never-delete) any ZZ open GRN this run or a prior
			// partial/failed run left behind, so the test adds nothing to the open-GRNI "new" bucket.
			foreach (var oid in await _db.GoodsReceipts.AsNoTracking().Where(g => g.CompanyID == company && g.VendorId == ven.ID && g.Status == "Posted" && g.InvoiceId == null).Select(g => g.ID).ToListAsync())
			{
				var gtot = await _db.GoodsReceipts.AsNoTracking().Where(g => g.ID == oid).Select(g => g.TotalCost).FirstAsync();
				await _ap.MatchGoodsReceiptToInvoiceAsync(company, oid, T, gtot, null);
			}

			// ===== T9 (regression) + T10 (invariants): global integrity — failedCount at baseline, subledgers reconcile =====
			var (run, checks) = await integrity.RunAndLogAsync(company, "hm16-accept");
			var open = checks.First(c => c.Key == "open_grni_receipts");
			var arSub = checks.First(c => c.Key == "ar_sub"); var apSub = checks.First(c => c.Key == "ap_sub");
			var stockGl = checks.First(c => c.Key == "stock_gl"); var tb = checks.First(c => c.Key == "tb_balanced");
			var batchNeg = checks.First(c => c.Key == "batch_no_negative"); var wc = checks.First(c => c.Key == "writer_coupling");
			var dbset = checks.First(c => c.Key == "dbset_tables_exist");
			Chk("T10 failedCount at documented baseline (0) — no NEW failing check above baseline", run.FailedCount == 0);
			Chk("T10 ar_sub OK · ap_sub OK (subledgers reconcile after all purchase activity)", arSub.Ok && apSub.Ok);
			Chk("T10 trial balance balanced · no negative batch", tb.Ok && batchNeg.Ok);
			Chk("T10 writer_coupling & dbset_tables_exist unchanged (our writers untouched by HM-16)", wc.Ok && dbset.Ok);
			// stock_gl is a Baseline[null] STRUCTURAL check (HM-D16; value fluctuates, never raises failedCount). Our
			// postings move stock value + GL 1103 together, so they add no NEW divergence — failedCount==0 proves it.
			log.Add($"  T10 failedCount={run.FailedCount} · ar_sub={arSub.Ok} ap_sub={apSub.Ok} stock_gl={stockGl.Ok}(structural,baseline-excluded) tb={tb.Ok} batch_neg={batchNeg.Ok} writer_coupling={wc.Ok} dbset={dbset.Ok}");
			log.Add($"  T5-cutoff open_grni_receipts: Actual={open.Actual} · {open.Note}");

			return Ok(new { allPass, cutoffUtc = CrossBuy.BL.IntegrityCheckService.PurchaseModelCutoffUtc.ToString("yyyy-MM-dd"), failedCount = run.FailedCount, log });
		}

		// GET /api/dev/hm8-accept?key=seed123 — HM-8 official A4 invoice acceptance. Every number is read FROM THE DB from a
		// NEW query (never the entity that wrote it). Fixtures are UNPOSTED draft invoices (HM-8 never touches posting — the
		// posting pipeline is already proven by HM-16), so the run is idempotent (prior ZZ-HM8 fixtures deleted first) and
		// moves NO ledger. Proves: document-currency dp (KWD=3 / EGP=2, never a fixed N2); the print read-model displays the
		// STORED values (no recompute); the walk-in stamp is set-once, audited, and ALLOWED ONLY when TaxTotal==0 (a taxed
		// invoice is rejected — the auditor's rule); the POS branch+company guard; and the OfficialInvoice capability gate.
		[HttpGet("hm8-accept")]
		public async Task<IActionResult> Hm8Accept(string key)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1; var log = new List<string>(); bool allPass = true;
			void Chk(string n, bool c) { log.Add((c ? "PASS " : "FAIL ") + n); if (!c) allPass = false; }
			var T = DateTime.Today;

			var kwd = await _db.Currencies.AsNoTracking().FirstOrDefaultAsync(c => c.Code == "KWD");
			var egp = await _db.Currencies.AsNoTracking().FirstOrDefaultAsync(c => c.Code == "EGP");
			if (kwd == null || egp == null) return BadRequest(new { message = "KWD/EGP currency missing — run the base seed" });
			int revenue = await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.Code == "4101").Select(a => a.ID).FirstAsync();
			int pcs = await _db.UnitsOfMeasure.Where(u => u.CompanyID == company && u.Code == "PCS").Select(u => u.ID).FirstAsync();
			int ctn = await _db.UnitsOfMeasure.Where(u => u.CompanyID == company && u.Code != "PCS").Select(u => u.ID).FirstOrDefaultAsync();
			if (ctn == 0) ctn = pcs;
			int branch17 = await _db.Branches.Where(b => b.Name == "HYPER-DEMO").Select(b => b.ID).FirstAsync();
			int otherBranch = await _db.Branches.Where(b => b.CompanyID == company && b.ID != branch17).Select(b => b.ID).FirstOrDefaultAsync();

			// walk-in + a real registered customer (with a tax reg no)
			var walkIn = await _db.Customers.FirstOrDefaultAsync(c => c.CompanyID == company && c.NameEn == "POS Walk-in")
						 ?? await _ar.CreateCustomerAsync(company, "عميل نقدي (كاشير)", "POS Walk-in", null, null);
			var real = await _db.Customers.FirstOrDefaultAsync(c => c.CompanyID == company && c.NameEn == "ZZ-HM8-REAL")
						 ?? await _ar.CreateCustomerAsync(company, "شركة مسجَّلة للاختبار", "ZZ-HM8-REAL", "TAX-REG-777", null);

			// capability ON for branch 17 (idempotent)
			if (!await _db.BranchCapabilities.AnyAsync(x => x.BranchId == branch17 && x.CapabilityKey == "OfficialInvoice"))
			{ _db.BranchCapabilities.Add(new CrossBuy.Models.Context.Pos.BranchCapability { BranchId = branch17, CapabilityKey = "OfficialInvoice", Enabled = true }); await _db.SaveChangesAsync(); }
			else { var cap = await _db.BranchCapabilities.FirstAsync(x => x.BranchId == branch17 && x.CapabilityKey == "OfficialInvoice"); if (!cap.Enabled) { cap.Enabled = true; await _db.SaveChangesAsync(); } }

			// ---- idempotent teardown: remove prior ZZ-HM8 fixtures (unposted drafts + their POS links; no JE, safe to delete) ----
			var oldPo = await _db.PosOrders.Where(o => o.CompanyId == company && o.Notes == "ZZ-HM8").ToListAsync();
			if (oldPo.Count > 0) { _db.PosOrders.RemoveRange(oldPo); await _db.SaveChangesAsync(); }
			var oldIds = await _db.SalesInvoices.Where(i => i.CompanyID == company && i.Notes != null && i.Notes.StartsWith("ZZ-HM8")).Select(i => i.ID).ToListAsync();
			if (oldIds.Count > 0)
			{
				_db.SalesInvoiceLines.RemoveRange(_db.SalesInvoiceLines.Where(l => oldIds.Contains(l.SalesInvoiceId)));
				_db.SalesInvoices.RemoveRange(_db.SalesInvoices.Where(i => oldIds.Contains(i.ID)));
				await _db.SaveChangesAsync();
			}

			int Dp(Models.Context.Accounting.Currency c) => c.DecimalPlaces;
			decimal Rd(decimal v, int dp) => Math.Round(v, dp, MidpointRounding.AwayFromZero);

			// fixture builder — an UNPOSTED draft invoice with computed stored totals at the DOCUMENT currency dp
			async Task<Models.Context.Accounting.SalesInvoice> Fix(int custId, Models.Context.Accounting.Currency cur, string tag,
				List<(string desc, string? descEn, decimal qty, decimal price, decimal disc, decimal rate, int? uom)> rows)
			{
				int dp = Dp(cur);
				var inv = new Models.Context.Accounting.SalesInvoice
				{ CompanyID = company, CustomerId = custId, InvoiceDate = T, CurrencyId = cur.ID, Status = "Draft", Notes = tag, CreatedAt = DateTime.UtcNow, ExchangeRate = 1m };
				int ln = 1; decimal sub = 0, tax = 0;
				foreach (var r in rows)
				{
					decimal lineTotal = Rd(r.qty * r.price - r.disc, dp);
					decimal lineTax = Rd(lineTotal * r.rate / 100m, dp);
					sub += lineTotal; tax += lineTax;
					inv.Lines.Add(new Models.Context.Accounting.SalesInvoiceLine
					{ LineNo = ln++, ItemDescription = r.desc, ItemDescriptionEn = r.descEn, Qty = r.qty, UnitPrice = r.price, DiscountAmount = r.disc, TaxRate = r.rate, RevenueAccountId = revenue, UoMId = r.uom, LineTotal = lineTotal });
				}
				inv.SubTotal = Rd(sub, dp); inv.TaxTotal = Rd(tax, dp); inv.GrandTotal = Rd(sub + tax, dp);
				_db.SalesInvoices.Add(inv); await _db.SaveChangesAsync();
				return inv;
			}

			// ===== fixtures =====
			var invKwd = await Fix(walkIn.ID, kwd, "ZZ-HM8-KWD", new() { ("ماء ٦٠٠مل", "Water 600ml", 2m, 0.750m, 0m, 0m, pcs) });                 // KWD, 0% (Kuwait VATEX)
			var invEgp = await Fix(real.ID, egp, "ZZ-HM8-EGP", new() { ("خدمة استشارية", "Consulting", 1m, 100m, 0m, 14m, pcs) });                    // EGP, 14%
			var invWt = await Fix(walkIn.ID, kwd, "ZZ-HM8-WT", new() { ("لحم مفروم/كجم", "Mince/kg", 1.234m, 3.500m, 0m, 0m, pcs) });                  // weighted qty (3dp)
			var invMu = await Fix(walkIn.ID, kwd, "ZZ-HM8-MU", new() { ("عبوة", "Carton", 3m, 5.000m, 0m, 0m, ctn) });                                 // multi-unit (non-PCS)
			var invDc = await Fix(walkIn.ID, kwd, "ZZ-HM8-DC", new() { ("عرض", "Promo", 5m, 1.000m, 0.500m, 0m, pcs) });                               // discount

			bool isAr = true;
			async Task<CrossBuy.BL.OfficialInvoiceHelper.PrintData> Read(Models.Context.Accounting.SalesInvoice inv)
			{
				var fresh = await _db.SalesInvoices.AsNoTracking().Include(i => i.Lines).FirstAsync(i => i.ID == inv.ID && i.CompanyID == company);
				return await CrossBuy.BL.OfficialInvoiceHelper.LoadPrintDataAsync(_db, fresh, isAr);
			}

			// ===== T1: KWD document currency = 3 dp · tax 0 is shown =====
			var pdK = await Read(invKwd);
			Chk("T1 KWD read-model dp=3 · code=KWD · GrandTotal 1.500 · TaxTotal 0.000", pdK.Dp == 3 && pdK.CurrencyCode == "KWD" && invKwd.GrandTotal == 1.500m && invKwd.TaxTotal == 0m);
			log.Add($"  T1 dp={pdK.Dp} code={pdK.CurrencyCode} grand={invKwd.GrandTotal} tax={invKwd.TaxTotal}");

			// ===== T2: EGP document currency = 2 dp · 14% breakdown =====
			var pdE = await Read(invEgp);
			Chk("T2 EGP read-model dp=2 · code=EGP · Sub 100.00 · Tax 14.00 · Grand 114.00", pdE.Dp == 2 && pdE.CurrencyCode == "EGP" && invEgp.SubTotal == 100.00m && invEgp.TaxTotal == 14.00m && invEgp.GrandTotal == 114.00m);
			log.Add($"  T2 dp={pdE.Dp} sub={invEgp.SubTotal} tax={invEgp.TaxTotal} grand={invEgp.GrandTotal}");

			// ===== T3: weighted qty preserved at 3 dp · line = qty×price =====
			var wl = (await _db.SalesInvoices.AsNoTracking().Include(i => i.Lines).FirstAsync(i => i.ID == invWt.ID)).Lines.First();
			Chk("T3 weighted qty 1.234 kept · LineTotal 4.319 (=1.234×3.500, AwayFromZero 3dp)", wl.Qty == 1.234m && wl.LineTotal == 4.319m);
			log.Add($"  T3 qty={wl.Qty} line={wl.LineTotal}");

			// ===== T4: multi-unit — the sold unit resolves to a name in the read-model =====
			var pdM = await Read(invMu);
			var ml = (await _db.SalesInvoices.AsNoTracking().Include(i => i.Lines).FirstAsync(i => i.ID == invMu.ID)).Lines.First();
			Chk("T4 multi-unit: line UoMId set · read-model resolves it to a unit name", ml.UoMId == ctn && ml.UoMId != null && pdM.Uoms.ContainsKey(ctn) && !string.IsNullOrWhiteSpace(pdM.Uoms[ctn]));
			log.Add($"  T4 uomId={ml.UoMId} unitName='{(pdM.Uoms.ContainsKey(ctn) ? pdM.Uoms[ctn] : "")}'");

			// ===== T5: discount reduces the line total =====
			var dl = (await _db.SalesInvoices.AsNoTracking().Include(i => i.Lines).FirstAsync(i => i.ID == invDc.ID)).Lines.First();
			Chk("T5 discount: 5×1.000 − 0.500 = 4.500 · DiscountAmount 0.500 stored", dl.DiscountAmount == 0.500m && dl.LineTotal == 4.500m);
			log.Add($"  T5 disc={dl.DiscountAmount} line={dl.LineTotal}");

			// ===== T8+T9 pre-snapshot (financials + rows must survive the stamp untouched) =====
			var s0 = await _db.SalesInvoices.AsNoTracking().Include(i => i.Lines).FirstAsync(i => i.ID == invKwd.ID);
			var f0 = (s0.SubTotal, s0.TaxTotal, s0.GrandTotal, s0.CustomerId, s0.JournalEntryId, rows: s0.Lines.Count, l0: s0.Lines.OrderBy(x => x.LineNo).Select(x => x.LineTotal).ToList());

			// ===== T13: KWD 0% → stamp ALLOWED · By/At set · doc shows the override name+tax =====
			var tk = await _db.SalesInvoices.FirstAsync(i => i.ID == invKwd.ID && i.CompanyID == company);
			var (ok13, err13) = CrossBuy.BL.OfficialInvoiceHelper.StampCustomer(tk, "أحمد المستهلك", "TAX-CUST-555", "9");
			if (ok13) await _db.SaveChangesAsync();
			var v13 = await _db.SalesInvoices.AsNoTracking().FirstAsync(i => i.ID == invKwd.ID);   // prove from a NEW read
			Chk("T13 KWD 0% stamp allowed · name+tax+By+At persisted", ok13 && v13.CustomerNameOverride == "أحمد المستهلك" && v13.CustomerTaxNoOverride == "TAX-CUST-555" && v13.CustomerOverrideBy == "9" && v13.CustomerOverrideAt != null);
			log.Add($"  T13 ok={ok13} name='{v13.CustomerNameOverride}' tax='{v13.CustomerTaxNoOverride}' by={v13.CustomerOverrideBy} at={v13.CustomerOverrideAt:o}");

			// ===== T8: displays-not-computes — the write left every FINANCIAL value unchanged =====
			var s1 = await _db.SalesInvoices.AsNoTracking().Include(i => i.Lines).FirstAsync(i => i.ID == invKwd.ID);
			Chk("T8 stamp/print never recomputes: Sub/Tax/Grand + CustomerId + JE unchanged", s1.SubTotal == f0.SubTotal && s1.TaxTotal == f0.TaxTotal && s1.GrandTotal == f0.GrandTotal && s1.CustomerId == f0.CustomerId && s1.JournalEntryId == f0.JournalEntryId);
			// ===== T9: rows before == after =====
			var l1 = s1.Lines.OrderBy(x => x.LineNo).Select(x => x.LineTotal).ToList();
			Chk("T9 lines unchanged by the stamp: same count · same LineTotals", s1.Lines.Count == f0.rows && l1.SequenceEqual(f0.l0));
			log.Add($"  T8/T9 sub {f0.SubTotal}→{s1.SubTotal} · grand {f0.GrandTotal}→{s1.GrandTotal} · rows {f0.rows}→{s1.Lines.Count}");

			// ===== T11: set-once — a 2nd stamp on the same invoice is rejected, first value intact =====
			var tk2 = await _db.SalesInvoices.FirstAsync(i => i.ID == invKwd.ID && i.CompanyID == company);
			var (ok11, err11) = CrossBuy.BL.OfficialInvoiceHelper.StampCustomer(tk2, "اسم آخر", "OTHER", "9");
			var v11 = await _db.SalesInvoices.AsNoTracking().FirstAsync(i => i.ID == invKwd.ID);
			Chk("T11 second stamp rejected (set-once) · first name unchanged", !ok11 && (err11 ?? "").Contains("مسبقًا") && v11.CustomerNameOverride == "أحمد المستهلك");
			log.Add($"  T11 ok={ok11} err='{err11}'");

			// ===== T12: taxed invoice (14%) → stamp REJECTED (the auditor's rule) · no override written =====
			var te = await _db.SalesInvoices.FirstAsync(i => i.ID == invEgp.ID && i.CompanyID == company);
			var (ok12, err12) = CrossBuy.BL.OfficialInvoiceHelper.StampCustomer(te, "اسم على فاتورة ضريبية", "X", "9");
			var v12 = await _db.SalesInvoices.AsNoTracking().FirstAsync(i => i.ID == invEgp.ID);
			Chk("T12 taxed invoice stamp REFUSED · reason=tax present · CustomerNameOverride stays null", !ok12 && (err12 ?? "").Contains("ضريبة") && v12.CustomerNameOverride == null);
			log.Add($"  T12 ok={ok12} err='{err12}'");

			// ===== T6: no tax number given → override tax stays null (the doc omits the line, not '0'/'null') =====
			var t6 = await Fix(walkIn.ID, kwd, "ZZ-HM8-NOTAX", new() { ("سلعة", "Item", 1m, 1.000m, 0m, 0m, pcs) });
			var tk6 = await _db.SalesInvoices.FirstAsync(i => i.ID == t6.ID && i.CompanyID == company);
			var (ok6, _) = CrossBuy.BL.OfficialInvoiceHelper.StampCustomer(tk6, "زبون بلا رقم ضريبي", "  ", "9");   // blank tax → null
			if (ok6) await _db.SaveChangesAsync();
			var v6 = await _db.SalesInvoices.AsNoTracking().FirstAsync(i => i.ID == t6.ID);
			Chk("T6 name-only stamp: CustomerTaxNoOverride null (doc omits the tax line)", ok6 && v6.CustomerNameOverride == "زبون بلا رقم ضريبي" && v6.CustomerTaxNoOverride == null);
			log.Add($"  T6 name='{v6.CustomerNameOverride}' tax={(v6.CustomerTaxNoOverride == null ? "null" : v6.CustomerTaxNoOverride)}");

			// ===== T7: logo absent — the read-model tolerates a null CompanyImage (the view guards with IsNullOrWhiteSpace) =====
			Chk("T7 read-model loads the company; a null/blank CompanyImage omits the logo (view-guarded)", pdK.Company != null);
			log.Add($"  T7 companyImage={(string.IsNullOrWhiteSpace(pdK.Company?.CompanyImage) ? "absent→no logo" : "present")}");

			// ===== T10: company guard — neither action can reach an invoice of another company =====
			bool crossCo = await _db.SalesInvoices.AsNoTracking().AnyAsync(i => i.ID == invKwd.ID && i.CompanyID == 999);
			Chk("T10 company guard: the invoice is unreachable under a wrong CompanyID (both actions filter it)", !crossCo);

			// ===== T14: POS branch guard — same predicate the cashier action uses =====
			_db.PosOrders.Add(new CrossBuy.Models.Context.Pos.PosOrder { CompanyId = company, BranchId = branch17, InvoiceId = invKwd.ID, Status = "Paid", OrderType = "Takeaway", OpenedAt = DateTime.UtcNow, Notes = "ZZ-HM8" });
			await _db.SaveChangesAsync();
			bool own = await _db.PosOrders.AsNoTracking().AnyAsync(o => o.InvoiceId == invKwd.ID && o.BranchId == branch17 && o.CompanyId == company);
			bool foreign = otherBranch == 0 || await _db.PosOrders.AsNoTracking().AnyAsync(o => o.InvoiceId == invKwd.ID && o.BranchId == otherBranch && o.CompanyId == company);
			Chk("T14 branch guard: own branch resolves the invoice · another branch does NOT", own && !(otherBranch != 0 && foreign));
			log.Add($"  T14 own(17)={own} other({otherBranch})={foreign}");

			// ===== T15: capability gate — ON for branch 17, OFF elsewhere =====
			bool cap17 = await _posSetup.IsCapabilityEnabledAsync(branch17, "OfficialInvoice");
			bool capOther = otherBranch != 0 && await _posSetup.IsCapabilityEnabledAsync(otherBranch, "OfficialInvoice");
			Chk("T15 OfficialInvoice capability ON (branch 17) · not enabled on an un-configured branch", cap17 && !capOther);
			log.Add($"  T15 branch17={cap17} otherBranch({otherBranch})={capOther}");

			return Ok(new { allPass, log });
		}

		// GET /api/dev/hm9-s1-accept?key=seed123 — HM-9 slice 1 (customer identity) acceptance. Requires hyper-hm0-seed + hm1-seed
		// (branch 17, HM-DEMO-001, KWD price). Reuses the REAL POS pay path (CreateOrder→AddLine→[link]→Pay) with fill-to-floor
		// stock so it is re-runnable. Every number is read FROM THE DB from a NEW query. Proves: no-link sale stays Walk-in with
		// identical numbers; search-by-phone → link → invoice issued to the REAL customer on the SAME 1102 AR line; quick-add →
		// link; the fail-closed control-account guard REFUSES the real anomaly customer 1025 (ControlAccountId=0); linking is
		// pre-pay only (SetOrderCustomerAsync refuses a paid order); capability gate; the official invoice reads the real
		// customer (not the HM-8 override); a taxed invoice on a real customer needs no override (resolves HM-8's workaround).
		[HttpGet("hm9-s1-accept")]
		public async Task<IActionResult> Hm9S1Accept(string key, [FromServices] CrossBuy.BL.IIntegrityCheckService integrity, [FromServices] CrossBuy.BL.IStockService stock)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1; var log = new List<string>(); bool allPass = true;
			void Chk(string n, bool c) { log.Add((c ? "PASS " : "FAIL ") + n); if (!c) allPass = false; }
			var T = DateTime.Today;

			int bid = await _db.Branches.Where(b => b.Name == "HYPER-DEMO").Select(b => b.ID).FirstOrDefaultAsync();
			var item = await _db.Items.FirstOrDefaultAsync(i => i.CompanyID == company && i.ItemCode == "HM-DEMO-001");
			if (bid == 0 || item == null) return BadRequest(new { message = "run hyper-hm0-seed + hm1-seed first" });
			int arId = await _db.Accounts.Where(a => a.CompanyID == company && a.Code == "1102").Select(a => a.ID).FirstAsync();
			int rev4101 = await _db.Accounts.Where(a => a.CompanyID == company && a.Code == "4101").Select(a => a.ID).FirstAsync();
			int otherBranch = await _db.Branches.Where(b => b.CompanyID == company && b.ID != bid).Select(b => b.ID).FirstOrDefaultAsync();
			var walkIn = await _db.Customers.FirstAsync(c => c.CompanyID == company && c.NameEn == "POS Walk-in");

			// capability "CustomerIdentity" ON for branch 17 (idempotent) — slice-1 identity gates on THIS key now (split from Loyalty)
			if (!await _db.BranchCapabilities.AnyAsync(x => x.BranchId == bid && x.CapabilityKey == "CustomerIdentity"))
			{ _db.BranchCapabilities.Add(new CrossBuy.Models.Context.Pos.BranchCapability { BranchId = bid, CapabilityKey = "CustomerIdentity", Enabled = true }); await _db.SaveChangesAsync(); }
			else { var cap = await _db.BranchCapabilities.FirstAsync(x => x.BranchId == bid && x.CapabilityKey == "CustomerIdentity"); if (!cap.Enabled) { cap.Enabled = true; await _db.SaveChangesAsync(); } }

			// real customer (phone = the lookup key) + a fresh quick-add customer, both idempotent by NameEn
			var real = await _db.Customers.FirstOrDefaultAsync(c => c.CompanyID == company && c.NameEn == "ZZ-HM9-REAL")
					   ?? await _ar.CreateCustomerAsync(company, "زبون ولاء للاختبار", "ZZ-HM9-REAL", "TAX-HM9-777", null);
			{ var tr = await _db.Customers.FirstAsync(c => c.ID == real.ID); if (tr.Phone != "0555070777") { tr.Phone = "0555070777"; await _db.SaveChangesAsync(); } }
			var fresh = await _db.Customers.FirstOrDefaultAsync(c => c.CompanyID == company && c.NameEn == "ZZ-HM9-NEW")
						?? await _ar.CreateCustomerAsync(company, "عميل مضاف سريعًا", "ZZ-HM9-NEW", null, null);

			// the REAL anomaly (do NOT fix): customer 1025 with ControlAccountId = 0
			var c1025 = await _db.Customers.AsNoTracking().FirstOrDefaultAsync(c => c.CompanyID == company && c.ID == 1025);

			// ---- shift + fill-to-floor stock (re-runnable) ----
			int drawer = await _db.Accounts.Where(a => a.CompanyID == company && a.Code == "110101").Select(a => a.ID).FirstOrDefaultAsync();
			var term = await _db.PosTerminals.FirstOrDefaultAsync(t => t.BranchId == bid && t.Code == "ZZ-HM9-T");
			if (term == null) { term = new CrossBuy.Models.Context.Pos.PosTerminal { BranchId = bid, Code = "ZZ-HM9-T", Name = "HM9 test", CashAccountId = drawer, ReceiptPrefix = "ZZHM9-", NextReceiptNo = 1, IsActive = true }; _db.PosTerminals.Add(term); await _db.SaveChangesAsync(); }
			foreach (var os in await _db.PosShifts.Where(s => s.TerminalId == term.ID && s.Status == "Open").ToListAsync()) { os.Status = "Closed"; os.ClosedAt = DateTime.UtcNow; }
			await _db.SaveChangesAsync();
			await _posSetup.OpenShiftAsync(term.ID, "Morning", null, 0m);
			var shift = await _posSetup.GetOpenShiftAsync(term.ID);
			int wh = await _db.BranchPosSettings.Where(s => s.BranchId == bid).Select(s => s.DefaultSalesWarehouseId ?? 0).FirstOrDefaultAsync();
			if (wh == 0) wh = await _db.Warehouses.Where(w => w.CompanyID == company).Select(w => w.ID).FirstAsync();
			var (bq, _b1, _b2) = await stock.GetBalanceAsync(company, item.ID, wh);
			if (bq < 50m) await stock.PostOpeningStockAsync(company, T, new List<CrossBuy.BL.OpeningStockLineInput> { new() { ItemId = item.ID, WarehouseId = wh, Qty = 50m - bq, UnitCost = 80m } }, null);

			// helpers (reuse the real service path)
			async Task<int> NewOrder(int? link)
			{
				var (_, _, oid) = await _posOrders.CreateOrderAsync(company, bid, "Takeaway", null, null, term!.ID, shift!.ID);
				await _posOrders.AddLineAsync(company, oid, item.ID, 1m);
				if (link != null) await _posOrders.SetOrderCustomerAsync(company, oid, link.Value);
				return oid;
			}
			async Task<int?> OrderCustomer(int oid) => await _db.PosOrders.AsNoTracking().Where(o => o.ID == oid).Select(o => (int?)o.CustomerId).FirstAsync();
			async Task<(decimal grand, int? cust, bool arHit, bool balanced)> Pay(int oid)
			{
				var (ok, err, invId) = await _posOrders.PayAsync(company, oid, "Cash", null);
				if (!ok || invId == null) { log.Add("  pay failed: " + err); return (0, null, false, false); }
				var inv = await _db.SalesInvoices.AsNoTracking().FirstAsync(i => i.ID == invId.Value);
				bool arHit = inv.JournalEntryId != null && await _db.JournalEntryLines.AnyAsync(l => l.JournalEntryId == inv.JournalEntryId!.Value && l.AccountId == arId);
				var jl = await _db.JournalEntryLines.AsNoTracking().Where(l => l.JournalEntryId == inv.JournalEntryId!.Value).ToListAsync();
				bool bal = Math.Round(jl.Sum(x => x.Debit) - jl.Sum(x => x.Credit), 2) == 0m;
				return (inv.GrandTotal, inv.CustomerId, arHit, bal);
			}
			// the controller's fail-closed guard, replicated (the action composes exactly this before SetOrderCustomerAsync)
			async Task<bool> CtrlValid(int custId)
			{
				var ctrl = await _db.Customers.AsNoTracking().Where(c => c.ID == custId && c.CompanyID == company).Select(c => (int?)c.ControlAccountId).FirstOrDefaultAsync();
				if (ctrl == null || ctrl.Value <= 0) return false;
				return await _db.Accounts.AsNoTracking().AnyAsync(a => a.ID == ctrl.Value && a.CompanyID == company && a.IsActive);
			}

			// ===== T1: sale with NO link ⇒ Walk-in, exact numbers (regression) =====
			var p1 = await Pay(await NewOrder(null));
			Chk("T1 no link ⇒ Walk-in customer · grand 0.750 · AR on 1102 · JE balanced", p1.cust == walkIn.ID && p1.grand == 0.750m && p1.arHit && p1.balanced);
			log.Add($"  T1 cust={p1.cust}(walkIn={walkIn.ID}) grand={p1.grand} arHit={p1.arHit} bal={p1.balanced}");

			// ===== T2: search by phone ⇒ found · link · invoice to REAL customer · same 1102 · same grand · balanced =====
			var (found, _tot) = await _ar.SearchCustomersAsync(company, "0555070777", true, 1, 15);
			bool byPhone = found.Any(x => x.ID == real.ID);
			var p2 = await Pay(await NewOrder(real.ID));
			Chk("T2 phone search finds the customer · invoice issued to the REAL customer · same 1102 · same 0.750 · balanced",
				byPhone && p2.cust == real.ID && p2.grand == 0.750m && p2.arHit && p2.balanced);
			log.Add($"  T2 foundByPhone={byPhone} cust={p2.cust}(real={real.ID}) grand={p2.grand} arHit={p2.arHit} bal={p2.balanced}");

			// ===== T3: quick-add then link ⇒ works · control account valid =====
			bool freshValid = await CtrlValid(fresh.ID);
			var p3 = await Pay(await NewOrder(fresh.ID));
			Chk("T3 quick-add customer has a valid control account · link works · invoice to that customer", freshValid && p3.cust == fresh.ID);
			log.Add($"  T3 freshCtrlValid={freshValid} cust={p3.cust}(new={fresh.ID})");

			// ===== T4: link a customer with an invalid/zero control account (the REAL 1025) ⇒ refused · order stays Walk-in =====
			bool guard1025 = c1025 != null && !await CtrlValid(1025);   // guard REFUSES 1025
			int o4 = await NewOrder(null);                              // controller: guard fails ⇒ SetOrderCustomerAsync NOT called
			int? o4cust = await OrderCustomer(o4);
			Chk("T4 guard refuses customer 1025 (ControlAccountId=0) · order stays Walk-in (zero effect)", guard1025 && o4cust == walkIn.ID);
			log.Add($"  T4 c1025.ctrl={c1025?.ControlAccountId} guardRefuses={guard1025} orderCust={o4cust}(walkIn={walkIn.ID})");
			await _posOrders.VoidOrderAsync(company, o4);               // teardown the open scratch order

			// ===== T5: link AFTER pay ⇒ refused by SetOrderCustomerAsync (pre-pay only) =====
			int o5 = await NewOrder(null);
			var p5 = await Pay(o5);
			var (l5ok, l5err) = await _posOrders.SetOrderCustomerAsync(company, o5, real.ID);
			int? o5cust = await OrderCustomer(o5);
			Chk("T5 link on a PAID order ⇒ refused (الطلب ليس مفتوحًا) · customer unchanged", !l5ok && (l5err ?? "").Contains("مفتوح") && o5cust == walkIn.ID);
			log.Add($"  T5 linkAfterPay ok={l5ok} err='{l5err}'");

			// ===== T6: capability disabled on a branch without config ⇒ not enabled =====
			bool capThis = await _posSetup.IsCapabilityEnabledAsync(bid, "CustomerIdentity");
			bool capOther = otherBranch != 0 && await _posSetup.IsCapabilityEnabledAsync(otherBranch, "CustomerIdentity");
			Chk("T6 CustomerIdentity capability ON (branch 17) · not enabled on an un-configured branch", capThis && !capOther);
			log.Add($"  T6 branch17={capThis} otherBranch({otherBranch})={capOther}");

			// ===== T7: official invoice on a real linked customer ⇒ name+tax from the CUSTOMER, no override =====
			var p7order = await NewOrder(real.ID);
			var (o7ok, _o7e, inv7Id) = await _posOrders.PayAsync(company, p7order, "Cash", null);
			var inv7 = await _db.SalesInvoices.AsNoTracking().Include(i => i.Lines).FirstAsync(i => i.ID == inv7Id!.Value);
			var pd7 = await CrossBuy.BL.OfficialInvoiceHelper.LoadPrintDataAsync(_db, inv7, true);
			bool showsRealName = inv7.CustomerNameOverride == null && pd7.Customer != null && pd7.Customer.ID == real.ID && pd7.Customer.TaxRegNo == "TAX-HM9-777";
			Chk("T7 official invoice reads the REAL customer (name+tax) · CustomerNameOverride null (no HM-8 workaround needed)", showsRealName);
			log.Add($"  T7 override={(inv7.CustomerNameOverride ?? "null")} custId={pd7.Customer?.ID}(real={real.ID}) tax={pd7.Customer?.TaxRegNo}");

			// ===== T8: a TAXED invoice on a real customer needs no override — and the HM-8 override is refused on tax>0 =====
			var taxed = await _db.SalesInvoices.FirstOrDefaultAsync(i => i.CompanyID == company && i.Notes == "ZZ-HM9-TAXED");
			if (taxed == null)
			{ var (_t8ok, _t8e, t8inv) = await _ar.CreateSalesInvoiceAsync(company, real.ID, T, new List<CrossBuy.BL.SalesLineInput> { new() { ItemDescription = "ZZ taxed", Qty = 1m, UnitPrice = 100m, TaxRate = 14m, RevenueAccountId = rev4101 } }, "ZZ-HM9-TAXED", null); taxed = t8inv; }
			var (stampOk, stampErr) = CrossBuy.BL.OfficialInvoiceHelper.StampCustomer(taxed!, "اسم على وثيقة ضريبية", "X", "9");
			Chk("T8 taxed invoice posts to the real customer · no override · HM-8 stamp refused on tax>0 (identity is the route)",
				taxed != null && taxed.TaxTotal > 0m && taxed.CustomerId == real.ID && taxed.CustomerNameOverride == null && !stampOk && (stampErr ?? "").Contains("ضريبة"));
			log.Add($"  T8 taxedCust={taxed?.CustomerId}(real={real.ID}) tax={taxed?.TaxTotal} override={(taxed?.CustomerNameOverride ?? "null")} stampRefused={!stampOk}");

			// ===== T10: link then CHANGE the customer before pay ⇒ last one gets the invoice =====
			int o10 = await NewOrder(real.ID);
			await _posOrders.SetOrderCustomerAsync(company, o10, fresh.ID);   // change before pay
			var p10 = await Pay(o10);
			Chk("T10 re-link before pay ⇒ the LAST customer is invoiced (fresh, not real)", p10.cust == fresh.ID);
			log.Add($"  T10 finalCust={p10.cust}(fresh={fresh.ID}, notReal={real.ID})");

			// ===== T11: link then void the order ⇒ no anomalous effect (no invoice, no JE) =====
			int o11 = await NewOrder(real.ID);
			var (v11ok, _v11e) = await _posOrders.VoidOrderAsync(company, o11);
			var o11row = await _db.PosOrders.AsNoTracking().FirstAsync(o => o.ID == o11);
			Chk("T11 link then void ⇒ order Void · no invoice · no anomalous posting", v11ok && o11row.Status != "Open" && o11row.InvoiceId == null);
			log.Add($"  T11 void ok={v11ok} status={o11row.Status} invoiceId={(o11row.InvoiceId?.ToString() ?? "null")}");

			// ===== T9: usual invariants + doc_je_status_mismatch = 0 (new) =====
			var (run, checks) = await integrity.RunAndLogAsync(company, "hm9-s1-accept");
			var arSub = checks.First(c => c.Key == "ar_sub"); var apSub = checks.First(c => c.Key == "ap_sub");
			var stockGl = checks.First(c => c.Key == "stock_gl"); var docJe = checks.First(c => c.Key == "doc_je_status_mismatch");
			var wc = checks.First(c => c.Key == "writer_coupling"); var dbset = checks.First(c => c.Key == "dbset_tables_exist");
			Chk("T9 failedCount at baseline 0 · ar_sub OK · ap_sub OK · doc_je_status_mismatch OK · writer_coupling OK · dbset OK",
				run.FailedCount == 0 && arSub.Ok && apSub.Ok && docJe.Ok && wc.Ok && dbset.Ok);
			log.Add($"  T9 failedCount={run.FailedCount} ar_sub={arSub.Ok} ap_sub={apSub.Ok} doc_je_status_mismatch={docJe.Ok} stock_gl={stockGl.Ok}(structural) writer_coupling={wc.Ok} dbset={dbset.Ok}");

			// close the test shift
			foreach (var s in await _db.PosShifts.Where(s => s.TerminalId == term!.ID && s.Status == "Open").ToListAsync()) { s.Status = "Closed"; s.ClosedAt = DateTime.UtcNow; }
			await _db.SaveChangesAsync();

			return Ok(new { allPass, failedCount = run.FailedCount, log });
		}

		// GET /api/dev/hm9-s2-accept?key=seed123 — HM-9 slice 2 (loyalty EARN) acceptance. Requires hyper-hm0/hm1-seed.
		// Reuses the REAL POS pay path; points are a MEMO ledger (no GL). Balances are asserted as DELTAS (re-runnable despite
		// accumulation). Proves: earn = floor(eligibleNet × rate) once per invoice, zero GL effect; capability gate; the
		// CustomerIdentity/Loyalty split; branch-over-company rate; category eligibility + item override; net (not gross);
		// explicit floor; reverse-on-return (full + partial, proportional) and on paid-cancel; derived balance = Σ movements.
		[HttpGet("hm9-s2-accept")]
		public async Task<IActionResult> Hm9S2Accept(string key, [FromServices] CrossBuy.BL.IIntegrityCheckService integrity, [FromServices] CrossBuy.BL.IStockService stock)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1; var log = new List<string>(); bool allPass = true;
			void Chk(string n, bool c) { log.Add((c ? "PASS " : "FAIL ") + n); if (!c) allPass = false; }
			var T = DateTime.Today;

			int bid = await _db.Branches.Where(b => b.Name == "HYPER-DEMO").Select(b => b.ID).FirstOrDefaultAsync();
			var demo = await _db.Items.FirstOrDefaultAsync(i => i.CompanyID == company && i.ItemCode == "HM-DEMO-001");
			if (bid == 0 || demo == null) return BadRequest(new { message = "run hyper-hm0-seed + hm1-seed first" });
			var bps = await _db.BranchPosSettings.FirstOrDefaultAsync(s => s.BranchId == bid);
			if (bps?.DefaultPriceListId == null) return BadRequest(new { message = "branch 17 has no price list (run hm1-seed)" });
			int plist = bps.DefaultPriceListId.Value;
			int pcs = await _db.UnitsOfMeasure.Where(u => u.CompanyID == company && u.Code == "PCS").Select(u => u.ID).FirstAsync();
			int wh = bps.DefaultSalesWarehouseId ?? await _db.Warehouses.Where(w => w.CompanyID == company).Select(w => w.ID).FirstAsync();
			int hcat = demo.ItemCategoryId;   // HM-DEMO-001's category (eligible by default)
			var walkIn = await _db.Customers.FirstAsync(c => c.CompanyID == company && c.NameEn == "POS Walk-in");
			var real = await _db.Customers.FirstOrDefaultAsync(c => c.CompanyID == company && c.NameEn == "ZZ-HM9-REAL")
					   ?? await _ar.CreateCustomerAsync(company, "زبون ولاء للاختبار", "ZZ-HM9-REAL", "TAX-HM9-777", null);

			// capabilities: CustomerIdentity + Loyalty ON for branch 17 (idempotent)
			async Task Cap(string k, bool on)
			{
				var c = await _db.BranchCapabilities.FirstOrDefaultAsync(x => x.BranchId == bid && x.CapabilityKey == k);
				if (c == null) _db.BranchCapabilities.Add(new CrossBuy.Models.Context.Pos.BranchCapability { BranchId = bid, CapabilityKey = k, Enabled = on });
				else c.Enabled = on;
				await _db.SaveChangesAsync();
			}
			await Cap("CustomerIdentity", true); await Cap("Loyalty", true);

			// rate: branch 17 override = 1 point/KWD; company default = 0.5 (for the override test)
			bps.LoyaltyPointsPerCurrencyUnit = 1.0m; await _db.SaveChangesAsync();
			var co = await _db.Companies.FirstAsync(x => x.CompanyID == company);
			co.LoyaltyPointsPerCurrencyUnit = 0.5m; await _db.SaveChangesAsync();

			// ineligible category + fixtures
			var noCat = await _db.ItemCategories.FirstOrDefaultAsync(c => c.CompanyID == company && c.Code == "ZZ-LOY-NO");
			if (noCat == null) { noCat = new CrossBuy.Models.Context.Inventory.ItemCategory { CompanyID = company, Code = "ZZ-LOY-NO", Name = "ZZ ineligible", NameEn = "ZZ ineligible", LoyaltyEligible = false, IsActive = true }; _db.ItemCategories.Add(noCat); await _db.SaveChangesAsync(); }
			else { noCat.LoyaltyEligible = false; await _db.SaveChangesAsync(); }
			// give the ineligible category the SAME GL mapping as the eligible one so its items can be opening-stocked + sold (COGS)
			{ var hc = await _db.ItemCategories.AsNoTracking().FirstAsync(c => c.ID == hcat); var noc = await _db.ItemCategories.FirstAsync(c => c.ID == noCat.ID);
			  noc.InventoryAccountId = hc.InventoryAccountId; noc.CogsAccountId = hc.CogsAccountId; noc.AdjustmentAccountId = hc.AdjustmentAccountId; noc.GrniAccountId = hc.GrniAccountId; noc.DefaultCostingMethod = hc.DefaultCostingMethod ?? "Average"; await _db.SaveChangesAsync(); }

			async Task<int> EnsureItem(string code, int catId, decimal price, bool? loy)
			{
				var it = await _db.Items.FirstOrDefaultAsync(i => i.CompanyID == company && i.ItemCode == code);
				if (it == null) { it = new CrossBuy.Models.Context.Inventory.Item { CompanyID = company, ItemCode = code, Barcode = "ZZBC-" + code, Name = code, NameEn = code, ItemCategoryId = catId, ItemType = "Stockable", BaseUoMId = pcs, IsActive = true, CostingMethod = "Average", LoyaltyEligible = loy, CreatedAt = DateTime.UtcNow }; _db.Items.Add(it); await _db.SaveChangesAsync(); }
				else { it.ItemCategoryId = catId; it.LoyaltyEligible = loy; it.IsActive = true; await _db.SaveChangesAsync(); }
				var pl = await _db.PriceListLines.FirstOrDefaultAsync(l => l.PriceListId == plist && l.ItemId == it.ID);
				if (pl == null) { _db.PriceListLines.Add(new CrossBuy.Models.Context.Inventory.PriceListLine { PriceListId = plist, ItemId = it.ID, MinQty = 1m, UnitPrice = price, DiscountPercent = 0m, PricingMode = "Fixed" }); await _db.SaveChangesAsync(); }
				else { pl.UnitPrice = price; pl.DiscountPercent = 0m; await _db.SaveChangesAsync(); }
				var (bq, _q1, _q2) = await stock.GetBalanceAsync(company, it.ID, wh);
				if (bq < 300m) await stock.PostOpeningStockAsync(company, T, new List<CrossBuy.BL.OpeningStockLineInput> { new() { ItemId = it.ID, WarehouseId = wh, Qty = 300m - bq, UnitCost = 0.5m } }, null);
				return it.ID;
			}
			int elig = await EnsureItem("ZZ-LOY-E", hcat, 2.000m, null);        // eligible (inherits eligible category)
			int inel = await EnsureItem("ZZ-LOY-X", noCat.ID, 2.000m, null);    // ineligible (inherits ineligible category)
			int ovr = await EnsureItem("ZZ-LOY-OVR", noCat.ID, 2.000m, true);   // ineligible category, item override = eligible
			int frac = await EnsureItem("ZZ-LOY-F", hcat, 1.290m, null);        // eligible, for the floor test
			// ensure HM-DEMO-001 stock
			var (dq, _d1, _d2) = await stock.GetBalanceAsync(company, demo.ID, wh);
			if (dq < 300m) await stock.PostOpeningStockAsync(company, T, new List<CrossBuy.BL.OpeningStockLineInput> { new() { ItemId = demo.ID, WarehouseId = wh, Qty = 300m - dq, UnitCost = 0.5m } }, null);

			// shift
			int drawer = await _db.Accounts.Where(a => a.CompanyID == company && a.Code == "110101").Select(a => a.ID).FirstOrDefaultAsync();
			var term = await _db.PosTerminals.FirstOrDefaultAsync(t => t.BranchId == bid && t.Code == "ZZ-HM9S2-T");
			if (term == null) { term = new CrossBuy.Models.Context.Pos.PosTerminal { BranchId = bid, Code = "ZZ-HM9S2-T", Name = "HM9s2", CashAccountId = drawer, ReceiptPrefix = "ZZS2-", NextReceiptNo = 1, IsActive = true }; _db.PosTerminals.Add(term); await _db.SaveChangesAsync(); }
			foreach (var os in await _db.PosShifts.Where(s => s.TerminalId == term.ID && s.Status == "Open").ToListAsync()) { os.Status = "Closed"; os.ClosedAt = DateTime.UtcNow; }
			await _db.SaveChangesAsync();
			await _posSetup.OpenShiftAsync(term.ID, "Morning", null, 0m);
			var shift = await _posSetup.GetOpenShiftAsync(term.ID);

			async Task<long> Bal() => await CrossBuy.BL.LoyaltyPointsHelper.GetBalanceAsync(_db, company, real.ID);
			async Task<(int invId, int orderId, decimal grand)> Sell(List<(int itemId, decimal qty)> items, int? link)
			{
				var (_o1, _o2, oid) = await _posOrders.CreateOrderAsync(company, bid, "Takeaway", null, null, term!.ID, shift!.ID);
				foreach (var it in items) await _posOrders.AddLineAsync(company, oid, it.itemId, it.qty);
				if (link != null) await _posOrders.SetOrderCustomerAsync(company, oid, link.Value);
				var (ok, err, invId) = await _posOrders.PayAsync(company, oid, "Cash", 1);
				if (!ok || invId == null) { log.Add("  sell failed: " + err); return (0, oid, 0m); }
				var g = await _db.SalesInvoices.AsNoTracking().Where(i => i.ID == invId.Value).Select(i => i.GrandTotal).FirstAsync();
				return (invId.Value, oid, g);
			}
			long Floor(decimal net, decimal rate) => (long)Math.Floor(net * rate);

			// ===== T1: eligible sale, Loyalty ON ⇒ points = floor(net × rate) · one movement linked to invoice · zero GL =====
			long b0 = await Bal();
			var s1 = await Sell(new() { (demo.ID, 20m) }, real.ID);   // 20 × 0.750 = 15.000 net · rate 1 ⇒ 15
			long d1 = await Bal() - b0;
			var mv1 = await _db.PointsMovements.AsNoTracking().Where(m => m.SourceInvoiceId == s1.invId).ToListAsync();
			bool jeBal = false; { var jid = await _db.SalesInvoices.AsNoTracking().Where(i => i.ID == s1.invId).Select(i => i.JournalEntryId).FirstAsync();
				if (jid != null) { var jl = await _db.JournalEntryLines.AsNoTracking().Where(l => l.JournalEntryId == jid.Value).ToListAsync(); jeBal = Math.Round(jl.Sum(x => x.Debit) - jl.Sum(x => x.Credit), 2) == 0m; } }
			Chk("T1 earn 15 = floor(15.000×1) · ONE Earn movement linked to the invoice · sale JE balanced (points are memo, no GL)",
				d1 == 15 && mv1.Count == 1 && mv1[0].Kind == "Earn" && mv1[0].Points == 15 && s1.grand == 15.000m && jeBal);
			log.Add($"  T1 delta={d1} movements={mv1.Count} pts={(mv1.Count > 0 ? mv1[0].Points : 0)} grand={s1.grand} jeBalanced={jeBal}");

			// ===== T2/T3: Loyalty OFF ⇒ identity still works, NO points (the split) =====
			await Cap("Loyalty", false);
			long b23 = await Bal();
			var s23 = await Sell(new() { (demo.ID, 20m) }, real.ID);
			long d23 = await Bal() - b23;
			int? s23cust = await _db.SalesInvoices.AsNoTracking().Where(i => i.ID == s23.invId).Select(i => (int?)i.CustomerId).FirstAsync();
			Chk("T2 Loyalty OFF ⇒ NO points movement · T3 identity STILL works (invoice to the real customer) — the split", d23 == 0 && s23cust == real.ID);
			log.Add($"  T2/T3 delta={d23} (expect 0) invoiceCustomer={s23cust}(real={real.ID})");
			await Cap("Loyalty", true);

			// ===== T4: rate resolution — branch OVERRIDE wins; without it ⇒ company DEFAULT (tested directly, no sale) =====
			bps.LoyaltyPointsPerCurrencyUnit = 1.0m; await _db.SaveChangesAsync();
			decimal rBranch = await CrossBuy.BL.LoyaltyPointsHelper.ResolveRateAsync(_db, company, bid);   // branch 1 wins over company 0.5
			bps.LoyaltyPointsPerCurrencyUnit = null; await _db.SaveChangesAsync();
			decimal rCompany = await CrossBuy.BL.LoyaltyPointsHelper.ResolveRateAsync(_db, company, bid);  // no override ⇒ company 0.5
			bps.LoyaltyPointsPerCurrencyUnit = 1.0m; await _db.SaveChangesAsync();                          // restore for the rest
			Chk("T4 branch override rate=1 wins over company · without override ⇒ company default 0.5", rBranch == 1.0m && rCompany == 0.5m);
			log.Add($"  T4 branchOverride={rBranch} companyDefault={rCompany}");

			// ===== T5: mixed basket ⇒ points on the ELIGIBLE line only =====
			long b5 = await Bal(); var s5 = await Sell(new() { (demo.ID, 4m), (inel, 2m) }, real.ID); long d5 = await Bal() - b5;
			// eligible net = 4×0.750 = 3.000 ⇒ 3 ; ineligible 2×2.000 = 4.000 earns nothing
			Chk("T5 mixed basket ⇒ 3 = floor(3.000×1) on the eligible line only (ineligible 4.000 earns nothing)", d5 == 3);
			log.Add($"  T5 delta={d5} (eligible 3.000×1=3 · ineligible 4.000 excluded) grand={s5.grand}");

			// ===== T6: item override eligible inside an ineligible category ⇒ earns =====
			long b6 = await Bal(); var s6 = await Sell(new() { (ovr, 5m) }, real.ID); long d6 = await Bal() - b6;   // 5×2.000=10.000 ⇒ 10
			Chk("T6 item override (LoyaltyEligible=true) in an ineligible category ⇒ earns 10", d6 == 10);
			log.Add($"  T6 delta={d6} (5×2.000=10.000×1=10)");

			// ===== T7: promo-discounted sale ⇒ points on NET, not gross =====
			await Cap("Promotions", true);
			var promo = await _db.Promotions.FirstOrDefaultAsync(p => p.CompanyID == company && p.Code == "ZZ-LOY-PROMO");
			// Percent (currency-agnostic; an Amount promo is in FUNCTIONAL currency and would convert to a KWD pittance)
			if (promo == null) { _db.Promotions.Add(new CrossBuy.Models.Context.Inventory.Promotion { CompanyID = company, Code = "ZZ-LOY-PROMO", Name = "ZZ promo", NameEn = "ZZ promo", DiscountType = "Percent", Value = 20m, ItemId = demo.ID, MinQty = 1m, Priority = 1, ValidFrom = T.AddDays(-1), ValidTo = T.AddDays(1), IsActive = true, CreatedAt = DateTime.UtcNow }); await _db.SaveChangesAsync(); }
			else { promo.DiscountType = "Percent"; promo.Value = 20m; promo.ItemId = demo.ID; promo.ValidFrom = T.AddDays(-1); promo.ValidTo = T.AddDays(1); promo.IsActive = true; await _db.SaveChangesAsync(); }
			long b7 = await Bal(); var s7 = await Sell(new() { (demo.ID, 10m) }, real.ID); long d7 = await Bal() - b7;
			// gross 10×0.750=7.500 (⇒7) ; net after 20% promo = 10×0.600 = 6.000 ⇒ 6
			Chk("T7 promo sale ⇒ points on NET 6.000 (=floor 6), NOT gross 7.500 (would be 7)", d7 == 6 && s7.grand == 6.000m);
			log.Add($"  T7 delta={d7} netGrand={s7.grand} (gross 7.500 → net 6.000 after 20%) grossPoints=7 netPoints=6");
			await Cap("Promotions", false);

			// ===== T8: fractional points ⇒ explicit floor (12.9 ⇒ 12, not 13) =====
			long b8 = await Bal(); var s8 = await Sell(new() { (frac, 10m) }, real.ID); long d8 = await Bal() - b8;   // 10×1.290=12.900 ⇒ floor 12
			Chk("T8 net 12.900 × 1 = 12.9 ⇒ floor 12 (NOT rounded to 13)", d8 == 12 && Floor(12.900m, 1m) == 12);
			log.Add($"  T8 delta={d8} (12.900 ⇒ floor 12)");

			// ===== T9: FULL return ⇒ negative movement reverses · derived per-invoice balance ⇒ 0 =====
			long b9 = await Bal(); var s9 = await Sell(new() { (demo.ID, 20m) }, real.ID); long earn9 = await Bal() - b9;   // 15
			var lines9 = await _db.PosOrderLines.AsNoTracking().Where(l => l.OrderId == s9.orderId).Select(l => new { l.ID, l.Qty }).ToListAsync();
			var (r9ok, r9err, r9id) = await _posOrders.ReturnOrderLinesAsync(company, s9.orderId, lines9.Select(l => new CrossBuy.BL.SplitAllocation { LineId = l.ID, Qty = l.Qty }).ToList(), 1);
			long net9 = await _db.PointsMovements.AsNoTracking().Where(m => m.SourceInvoiceId == s9.invId).SumAsync(m => (long?)m.Points) ?? 0;
			Chk("T9 full return ⇒ reversal of −15 · per-invoice net points = 0 (reverse-never-delete)", r9ok && earn9 == 15 && net9 == 0);
			log.Add($"  T9 earn={earn9} returnOk={r9ok} perInvoiceNet={net9} err='{r9err}'");

			// ===== T10: PARTIAL return ⇒ proportional reversal =====
			long b10 = await Bal(); var s10 = await Sell(new() { (demo.ID, 20m) }, real.ID); long earn10 = await Bal() - b10;   // 15
			var lines10 = await _db.PosOrderLines.AsNoTracking().Where(l => l.OrderId == s10.orderId).Select(l => new { l.ID, l.Qty }).ToListAsync();
			var half = lines10.Select(l => new CrossBuy.BL.SplitAllocation { LineId = l.ID, Qty = l.Qty / 2m }).ToList();   // return qty 10 of 20
			var (r10ok, _r10e, _r10id) = await _posOrders.ReturnOrderLinesAsync(company, s10.orderId, half, 1);
			long rev10 = -(await _db.PointsMovements.AsNoTracking().Where(m => m.SourceInvoiceId == s10.invId && m.Points < 0).SumAsync(m => (long?)m.Points) ?? 0);
			// returned net = 10×0.750 = 7.500 · saleNet 15.000 · reversal = floor(15 × 7.5/15) = floor(7.5) = 7
			Chk("T10 partial return (half) ⇒ proportional reversal 7 = floor(15 × 7.500/15.000)", r10ok && earn10 == 15 && rev10 == 7);
			log.Add($"  T10 earn={earn10} reversed={rev10} (returned 7.500/15.000 ⇒ floor(15×0.5)=7)");

			// ===== T11: cancel a PAID order ⇒ full reverse of the earn =====
			long b11 = await Bal(); var s11 = await Sell(new() { (demo.ID, 20m) }, real.ID); long earn11 = await Bal() - b11;   // 15
			var (v11ok, v11err) = await _posOrders.VoidPaidOrderAsync(company, s11.orderId, 1);
			long net11 = await _db.PointsMovements.AsNoTracking().Where(m => m.SourceInvoiceId == s11.invId).SumAsync(m => (long?)m.Points) ?? 0;
			Chk("T11 cancel paid order ⇒ earn fully reversed · per-invoice net points = 0", v11ok && earn11 == 15 && net11 == 0);
			log.Add($"  T11 earn={earn11} voidOk={v11ok} perInvoiceNet={net11} err='{v11err}'");

			// ===== T12: walk-in sale (no linked customer) ⇒ NO points =====
			long wb0 = await CrossBuy.BL.LoyaltyPointsHelper.GetBalanceAsync(_db, company, walkIn.ID);
			var s12 = await Sell(new() { (demo.ID, 20m) }, null);   // no link ⇒ walk-in
			long wd = await CrossBuy.BL.LoyaltyPointsHelper.GetBalanceAsync(_db, company, walkIn.ID) - wb0;
			int mv12 = await _db.PointsMovements.AsNoTracking().CountAsync(m => m.SourceInvoiceId == s12.invId);
			Chk("T12 walk-in sale (no identified customer) ⇒ no points at all", wd == 0 && mv12 == 0);
			log.Add($"  T12 walkInDelta={wd} movements={mv12}");

			// ===== T13: derived balance = Σ signed movements (prove by query, not by a stored column) =====
			long helperBal = await Bal();
			long rawSum = await _db.PointsMovements.AsNoTracking().Where(m => m.CompanyID == company && m.CustomerId == real.ID).SumAsync(m => (long?)m.Points) ?? 0;
			Chk("T13 derived balance == Σ signed movements (no stored balance column)", helperBal == rawSum);
			log.Add($"  T13 helperBalance={helperBal} Σmovements={rawSum}");

			// ===== T14: usual invariants + doc_je_status_mismatch = 0 (points add NO GL) =====
			var (run, checks) = await integrity.RunAndLogAsync(company, "hm9-s2-accept");
			var arSub = checks.First(c => c.Key == "ar_sub"); var apSub = checks.First(c => c.Key == "ap_sub");
			var stockGl = checks.First(c => c.Key == "stock_gl"); var docJe = checks.First(c => c.Key == "doc_je_status_mismatch");
			var wc = checks.First(c => c.Key == "writer_coupling"); var dbset = checks.First(c => c.Key == "dbset_tables_exist");
			Chk("T14 failedCount 0 · ar_sub · ap_sub · doc_je_status_mismatch · writer_coupling · dbset all OK (points are memo)",
				run.FailedCount == 0 && arSub.Ok && apSub.Ok && docJe.Ok && wc.Ok && dbset.Ok);
			log.Add($"  T14 failedCount={run.FailedCount} ar_sub={arSub.Ok} ap_sub={apSub.Ok} doc_je_status_mismatch={docJe.Ok} stock_gl={stockGl.Ok}(structural) writer_coupling={wc.Ok} dbset={dbset.Ok}");

			foreach (var s in await _db.PosShifts.Where(s => s.TerminalId == term!.ID && s.Status == "Open").ToListAsync()) { s.Status = "Closed"; s.ClosedAt = DateTime.UtcNow; }
			await _db.SaveChangesAsync();
			return Ok(new { allPass, failedCount = run.FailedCount, log });
		}

		// GET /api/dev/hm7-count-accept?key=seed123 — HM-7 batch-1 (batch-aware physical count) acceptance. Every number is
		// read FROM THE DB (per-batch on-hand = Σ Direction×QtyBase over movements, never from the tracked entity).
		[HttpGet("hm7-count-accept")]
		public async Task<IActionResult> Hm7CountAccept(string key, [FromServices] CrossBuy.BL.IIntegrityCheckService integrity)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1; var log = new List<string>(); bool allPass = true;
			void Chk(string n, bool c) { log.Add((c ? "PASS " : "FAIL ") + n); if (!c) allPass = false; }
			decimal R(decimal v) => Math.Round(v, 3, MidpointRounding.AwayFromZero);
			var T = DateTime.Today;
			int wh = await _db.Warehouses.Where(w => w.CompanyID == company).OrderBy(w => w.ID).Select(w => w.ID).FirstAsync();
			int pcs = await _db.UnitsOfMeasure.Where(u => u.CompanyID == company && u.Code == "PCS").Select(u => u.ID).FirstAsync();
			int kg = await _db.UnitsOfMeasure.Where(u => u.CompanyID == company && u.Code == "KG").Select(u => u.ID).FirstAsync();
			int accInv = await _db.Accounts.Where(a => a.CompanyID == company && a.Code == "1103").Select(a => a.ID).FirstAsync();
			int accAdj = await _db.Accounts.Where(a => a.CompanyID == company && a.Code == "520103").Select(a => a.ID).FirstOrDefaultAsync();
			if (accAdj == 0) accAdj = await _db.ItemCategories.Where(c => c.CompanyID == company && c.AdjustmentAccountId != null).Select(c => c.AdjustmentAccountId!.Value).FirstAsync();
			int accCogs = await _db.Accounts.Where(a => a.CompanyID == company && a.Code == "510101").Select(a => a.ID).FirstAsync();

			var cat = await _db.ItemCategories.FirstOrDefaultAsync(c => c.CompanyID == company && c.Code == "ZZ-CNT-CAT");
			if (cat == null) { cat = new CrossBuy.Models.Context.Inventory.ItemCategory { CompanyID = company, Code = "ZZ-CNT-CAT", Name = "ZZ count cat", NameEn = "ZZ count cat", DefaultCostingMethod = "Average" }; _db.ItemCategories.Add(cat); }
			cat.InventoryAccountId = accInv; cat.AdjustmentAccountId = accAdj; cat.CogsAccountId = accCogs; await _db.SaveChangesAsync();
			async Task<CrossBuy.Models.Context.Inventory.Item> Item(string code, bool expiry, bool weighted, int uom)
			{
				var it = await _db.Items.FirstOrDefaultAsync(i => i.CompanyID == company && i.ItemCode == code);
				if (it == null) { it = new CrossBuy.Models.Context.Inventory.Item { CompanyID = company, ItemCode = code, Barcode = "ZZBC-" + code, Name = code, NameEn = code, ItemCategoryId = cat.ID, ItemType = "Stockable", BaseUoMId = uom, TrackExpiry = expiry, IsWeighted = weighted, IsActive = true, CostingMethod = "Average", CreatedAt = DateTime.UtcNow }; _db.Items.Add(it); await _db.SaveChangesAsync(); }
				return it;
			}
			var plain = await Item("ZZ-CNT-PLAIN", false, false, pcs);
			var exp = await Item("ZZ-CNT-EXP", true, false, pcs);
			var wexp = await Item("ZZ-CNT-WEXP", true, true, kg);

			async Task<int?> BatchIdOf(int itemId, string bn) => await _db.StockBatches.AsNoTracking().Where(b => b.CompanyID == company && b.ItemId == itemId && b.BatchNo == bn).Select(b => (int?)b.ID).FirstOrDefaultAsync();
			async Task<decimal> BOH(int itemId, string bn) { var bid = await BatchIdOf(itemId, bn); return bid == null ? 0m : (await _db.StockMovements.AsNoTracking().Where(m => m.ItemId == itemId && m.WarehouseId == wh && m.BatchId == bid).SumAsync(m => (decimal?)(m.Direction * m.QtyBase)) ?? 0m); }
			async Task<decimal> Qty(int itemId) => (await _stock.GetBalanceAsync(company, itemId, wh)).qty;
			async Task Fill(int itemId, string bn, DateTime exd, decimal floor, decimal cost)
			{ var cur = await BOH(itemId, bn); if (cur < floor) await _stock.PostOpeningStockAsync(company, T, new List<CrossBuy.BL.OpeningStockLineInput> { new() { ItemId = itemId, WarehouseId = wh, Qty = floor - cur, UnitCost = cost, BatchNo = bn, Expiry = exd } }, "dev"); }
			async Task Reseed()
			{
				var q = await Qty(plain.ID); if (q < 100m) await _stock.PostMovementAsync(company, new CrossBuy.BL.MovementRequest { Date = T, ItemId = plain.ID, WarehouseId = wh, Direction = 1, Qty = 100m - q, UnitCostInBase = 10m, SourceType = "Opening", PostToGl = false }, "dev");
				await Fill(exp.ID, "ZC-LOT-A", T.AddDays(10), 50m, 4m); await Fill(exp.ID, "ZC-LOT-B", T.AddDays(60), 50m, 4m); await Fill(exp.ID, "ZC-LOT-C", T.AddDays(90), 30m, 4m);
				await Fill(wexp.ID, "ZC-WLOT", T.AddDays(45), 2.000m, 300m);
			}
			CrossBuy.BL.CountLineInput CL(int itemId, decimal counted, string? bn = null, DateTime? ex = null) => new() { ItemId = itemId, CountedQty = counted, BatchNo = bn, Expiry = ex };
			async Task<CrossBuy.Models.Context.Inventory.StockMovement?> AdjMv(int countId, int itemId) => await _db.StockMovements.AsNoTracking().Where(m => m.SourceType == "Adjustment" && m.SourceId == countId && m.ItemId == itemId).OrderByDescending(m => m.ID).FirstOrDefaultAsync();

			await Reseed();

			// ===== T1: non-tracked item ⇒ exact pre-HM-7 behaviour (regression) =====
			decimal p0 = await Qty(plain.ID);
			var (c1ok, c1err, cnt1) = await _stock.PostCountAsync(company, wh, T, "hm7 T1", new List<CrossBuy.BL.CountLineInput> { CL(plain.ID, p0 - 5m) }, "dev");
			var l1 = cnt1 != null ? await _db.StockCountLines.AsNoTracking().Where(l => l.StockCountId == cnt1.ID).FirstOrDefaultAsync() : null;
			Chk("T1 non-tracked: diff -5 posted, line has NO batch (unchanged path)", c1ok && R(await Qty(plain.ID) - p0) == -5m && l1 != null && l1.BatchNo == null);
			log.Add($"  T1 ok={c1ok} qtyDelta={R(await Qty(plain.ID) - p0)} lineBatch={l1?.BatchNo ?? "null"}");

			// ===== T2: tracked, 2 batches, positive diff on ONE ⇒ Adjustment to the RIGHT batch, other untouched =====
			decimal a0 = await BOH(exp.ID, "ZC-LOT-A"), b0 = await BOH(exp.ID, "ZC-LOT-B");
			var (c2ok, _, cnt2) = await _stock.PostCountAsync(company, wh, T, "hm7 T2", new List<CrossBuy.BL.CountLineInput> { CL(exp.ID, a0 + 10m, "ZC-LOT-A", T.AddDays(10)) }, "dev");
			var mv2 = cnt2 != null ? await AdjMv(cnt2.ID, exp.ID) : null; var lotAId = await BatchIdOf(exp.ID, "ZC-LOT-A");
			Chk("T2 +10 on LOT-A ⇒ LOT-A +10, LOT-B untouched, movement carries LOT-A batch", c2ok && R(await BOH(exp.ID, "ZC-LOT-A") - a0) == 10m && await BOH(exp.ID, "ZC-LOT-B") == b0 && mv2 != null && mv2.BatchId == lotAId);
			log.Add($"  T2 dA={R(await BOH(exp.ID, "ZC-LOT-A") - a0)} LOT-B={await BOH(exp.ID, "ZC-LOT-B")} mvBatch={mv2?.BatchId} lotA={lotAId}");

			// ===== T3: negative diff on a SPECIFIC batch ⇒ issued from THAT batch, not FEFO (LOT-A expires sooner) =====
			decimal a3 = await BOH(exp.ID, "ZC-LOT-A"), b3 = await BOH(exp.ID, "ZC-LOT-B");
			var (c3ok, _, cnt3) = await _stock.PostCountAsync(company, wh, T, "hm7 T3", new List<CrossBuy.BL.CountLineInput> { CL(exp.ID, b3 - 5m, "ZC-LOT-B", T.AddDays(60)) }, "dev");
			var mv3 = cnt3 != null ? await AdjMv(cnt3.ID, exp.ID) : null; var lotBId = await BatchIdOf(exp.ID, "ZC-LOT-B");
            Chk("T3 -5 on LOT-B ⇒ LOT-B -5, LOT-A untouched (NOT FEFO), movement carries LOT-B", c3ok && R(await BOH(exp.ID, "ZC-LOT-B") - b3) == -5m && await BOH(exp.ID, "ZC-LOT-A") == a3 && mv3 != null && mv3.BatchId == lotBId);
			log.Add($"  T3 dB={R(await BOH(exp.ID, "ZC-LOT-B") - b3)} LOT-A={await BOH(exp.ID, "ZC-LOT-A")}(was {a3}) mvBatch={mv3?.BatchId} lotB={lotBId}");

			// ===== T4: two OPPOSITE diffs on two batches in ONE count ⇒ each to its batch, no netting =====
			await Reseed(); decimal a4 = await BOH(exp.ID, "ZC-LOT-A"), b4 = await BOH(exp.ID, "ZC-LOT-B");
			var (c4ok, _, _) = await _stock.PostCountAsync(company, wh, T, "hm7 T4", new List<CrossBuy.BL.CountLineInput> { CL(exp.ID, a4 + 8m, "ZC-LOT-A", T.AddDays(10)), CL(exp.ID, b4 - 8m, "ZC-LOT-B", T.AddDays(60)) }, "dev");
			Chk("T4 +8/-8 on two batches ⇒ LOT-A +8 AND LOT-B -8 (not netted to 0)", c4ok && R(await BOH(exp.ID, "ZC-LOT-A") - a4) == 8m && R(await BOH(exp.ID, "ZC-LOT-B") - b4) == -8m);
			log.Add($"  T4 dA={R(await BOH(exp.ID, "ZC-LOT-A") - a4)} dB={R(await BOH(exp.ID, "ZC-LOT-B") - b4)}");

			// ===== T5/T9: an UNCOUNTED batch is left untouched AND surfaced as uncounted with its book qty =====
			await Reseed(); decimal cUncounted = await BOH(exp.ID, "ZC-LOT-C");
			var (c5ok, _, cnt5) = await _stock.PostCountAsync(company, wh, T, "hm7 T5", new List<CrossBuy.BL.CountLineInput> { CL(exp.ID, await BOH(exp.ID, "ZC-LOT-A"), "ZC-LOT-A", T.AddDays(10)) }, "dev");
			var counted5 = cnt5 != null ? await _db.StockCountLines.AsNoTracking().Where(l => l.StockCountId == cnt5.ID).Select(l => l.BatchNo).ToListAsync() : new();
			bool lotCUntouched = await BOH(exp.ID, "ZC-LOT-C") == cUncounted;
			bool lotCSurfaced = !counted5.Contains("ZC-LOT-C") && cUncounted > 0m;   // on-hand batch not in the count's lines ⇒ "uncounted"
			Chk("T5/T9 uncounted LOT-C ⇒ untouched AND surfaced as uncounted (book qty intact, not zeroed/hidden)", c5ok && lotCUntouched && lotCSurfaced);
			log.Add($"  T5 LOT-C book={cUncounted} stillThere={lotCUntouched} inCountedLines={counted5.Contains("ZC-LOT-C")}");

			// ===== T6/T10: counted batch NOT in the system ⇒ created + line flagged + classification rises =====
			// RE-RUNNABLE: a UNIQUE batch name per run (so "created" is always a genuinely fresh batch) + DELTA assertions
			// (classification +1, not an absolute), then the +20 is issued back out so ZZ-CNT-EXP nets zero (no residue).
			int classBefore = (int)((await integrity.RunAsync(company)).First(c => c.Key == "batches_created_in_count").Actual);
			string newBn = "ZC-NEW-" + DateTime.UtcNow.Ticks;
			var (c6ok, _, cnt6) = await _stock.PostCountAsync(company, wh, T, "hm7 T6", new List<CrossBuy.BL.CountLineInput> { CL(exp.ID, 20m, newBn, T.AddDays(120)) }, "dev");
			var l6 = cnt6 != null ? await _db.StockCountLines.AsNoTracking().Where(l => l.StockCountId == cnt6.ID && l.BatchNo == newBn).FirstOrDefaultAsync() : null;
			int classAfter = (int)((await integrity.RunAsync(company)).First(c => c.Key == "batches_created_in_count").Actual);
			Chk("T6/T10 unregistered batch ⇒ created (BOH=20), line flagged, classification +1 (delta)", c6ok && await BOH(exp.ID, newBn) == 20m && l6 != null && l6.BatchCreatedInCount && classAfter == classBefore + 1);
			log.Add($"  T6 batch={newBn} BOH={await BOH(exp.ID, newBn)} flagged={l6?.BatchCreatedInCount} classif {classBefore}→{classAfter}");
			await _stock.PostCountAsync(company, wh, T, "hm7 T6 reset", new List<CrossBuy.BL.CountLineInput> { CL(exp.ID, 0m, newBn, T.AddDays(120)) }, "dev");   // issue the +20 back ⇒ net zero, no residue

			// ===== T7/T11: same, WITHOUT expiry ⇒ rejected, ZERO effect (atomic) =====
			decimal qExpBefore = await Qty(exp.ID);
			var (c7ok, c7err, _) = await _stock.PostCountAsync(company, wh, T, "hm7 T7", new List<CrossBuy.BL.CountLineInput> { CL(exp.ID, 5m, "ZC-NOEXP", null) }, "dev");
			Chk("T7/T11 unregistered batch WITHOUT expiry ⇒ rejected, zero effect", !c7ok && (c7err ?? "").Contains("صلاحية") && await Qty(exp.ID) == qExpBefore);
			log.Add($"  T7 ok={c7ok} err='{c7err}' qtyUnchanged={await Qty(exp.ID) == qExpBefore}");

			// ===== T8: WEIGHTED tracked, KG per batch ⇒ fractions preserved =====
			await Reseed();
			var (c8ok, _, _) = await _stock.PostCountAsync(company, wh, T, "hm7 T8", new List<CrossBuy.BL.CountLineInput> { CL(wexp.ID, 1.755m, "ZC-WLOT", T.AddDays(45)) }, "dev");
			decimal wboh = await BOH(wexp.ID, "ZC-WLOT");
			Chk("T8 weighted KG per batch ⇒ WLOT counted to 1.755 exactly (fractions kept)", c8ok && wboh == 1.755m);
			log.Add($"  T8 WLOT boh={wboh}");

			// ===== T12: three batches, TWO counted ⇒ adjust only those two, third untouched + surfaced =====
			await Reseed(); decimal cBook = await BOH(exp.ID, "ZC-LOT-C");
			var (c12ok, _, cnt12) = await _stock.PostCountAsync(company, wh, T, "hm7 T12", new List<CrossBuy.BL.CountLineInput> { CL(exp.ID, await BOH(exp.ID, "ZC-LOT-A") + 1m, "ZC-LOT-A", T.AddDays(10)), CL(exp.ID, await BOH(exp.ID, "ZC-LOT-B") - 1m, "ZC-LOT-B", T.AddDays(60)) }, "dev");
			var counted12 = cnt12 != null ? await _db.StockCountLines.AsNoTracking().Where(l => l.StockCountId == cnt12.ID).Select(l => l.BatchNo).ToListAsync() : new();
			Chk("T12 3 batches, 2 counted ⇒ LOT-C untouched + surfaced (not in counted lines)", c12ok && await BOH(exp.ID, "ZC-LOT-C") == cBook && !counted12.Contains("ZC-LOT-C") && cBook > 0m);
			log.Add($"  T12 LOT-C={cBook} counted=[{string.Join(",", counted12)}]");

			// ===== constants =====
			var (run, checks) = await integrity.RunAndLogAsync(company, "hm7-count");
			IntegrityCheck G(string k) => checks.First(c => c.Key == k);
			Chk("CONST failedCount 0", run.FailedCount == 0);
			Chk("CONST ar_sub/ap_sub OK · bal_qty_vs_moves OK · batch_no_negative OK", G("ar_sub").Ok && G("ap_sub").Ok && G("bal_qty_vs_moves").Ok && G("batch_no_negative").Ok);
			Chk("CONST doc_je_status_mismatch 0 new · dbset_tables_exist 0 · writer_coupling counted", G("doc_je_status_mismatch").Ok && G("dbset_tables_exist").Ok && G("writer_coupling").Ok);
			log.Add($"  CONST failedCount={run.FailedCount} · unbatched_inbound_tracked={G("unbatched_inbound_tracked").Actual} · batches_created_in_count={G("batches_created_in_count").Actual} · bal_value_diff:{G("bal_value_diff").Note}");

			return Ok(new { allPass, failedCount = run.FailedCount, log });
		}

		// GET /api/dev/hm7-landed-accept?key=seed123 — HM-D7: the landed-cost lost-update. Mirrors hm1-d6-race-test's
		// DETERMINISTIC technique: an EXTERNAL write via raw SQL (the identity map can't observe it) makes the tracked
		// StockBalance stale, then landed cost runs. Pre-fix (seam ON = old unlocked read) overwrites with V+share, LOSING
		// the concurrent Δ; fixed (seam OFF = locked read + Reload) sees V+Δ and yields V+Δ+share. Everything in one tx,
		// rolled back ⇒ zero persistence. A test that does not FAIL before the fix proves nothing — so it asserts both.
		[HttpGet("hm7-landed-accept")]
		public async Task<IActionResult> Hm7LandedAccept(string key, [FromServices] CrossBuy.BL.IProcurementService proc)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1; var log = new List<string>(); bool allPass = true;
			void Chk(string n, bool c) { log.Add((c ? "PASS " : "FAIL ") + n); if (!c) allPass = false; }
			var T = DateTime.Today;
			int wh = await _db.Warehouses.Where(w => w.CompanyID == company).OrderBy(w => w.ID).Select(w => w.ID).FirstAsync();
			int pcs = await _db.UnitsOfMeasure.Where(u => u.CompanyID == company && u.Code == "PCS").Select(u => u.ID).FirstAsync();
			int accInv = await _db.Accounts.Where(a => a.CompanyID == company && a.Code == "1103").Select(a => a.ID).FirstAsync();
			int accGrni = await _db.Accounts.Where(a => a.CompanyID == company && a.Code == "210203").Select(a => a.ID).FirstAsync();
			int accFreight = await _db.Accounts.Where(a => a.CompanyID == company && a.Code == "520103").Select(a => a.ID).FirstAsync();
			var ven = await _db.Vendors.FirstOrDefaultAsync(v => v.CompanyID == company && v.Name == "ZZ-LC-VEN");
			if (ven == null) ven = await _ap.CreateVendorAsync(company, "ZZ-LC-VEN", "ZZ LC vendor", null);
			var cat = await _db.ItemCategories.FirstOrDefaultAsync(c => c.CompanyID == company && c.Code == "ZZ-LC-CAT");
			if (cat == null) { cat = new CrossBuy.Models.Context.Inventory.ItemCategory { CompanyID = company, Code = "ZZ-LC-CAT", Name = "ZZ LC cat", NameEn = "ZZ LC cat", DefaultCostingMethod = "Average" }; _db.ItemCategories.Add(cat); }
			cat.InventoryAccountId = accInv; cat.GrniAccountId = accGrni; await _db.SaveChangesAsync();
			var itm = await _db.Items.FirstOrDefaultAsync(i => i.CompanyID == company && i.ItemCode == "ZZ-LC-ITM");
			if (itm == null) { itm = new CrossBuy.Models.Context.Inventory.Item { CompanyID = company, ItemCode = "ZZ-LC-ITM", Barcode = "ZZBC-LC", Name = "ZZ LC", NameEn = "ZZ LC", ItemCategoryId = cat.ID, ItemType = "Stockable", BaseUoMId = pcs, IsActive = true, CostingMethod = "Average", CreatedAt = DateTime.UtcNow }; _db.Items.Add(itm); await _db.SaveChangesAsync(); }
			int itemId = itm.ID;

			const decimal V = 200m, DELTA = 50m, SHARE = 30m;   // GRN 10@20 ⇒ V=200 · external concurrent +50 · freight share 30
			async Task<(decimal finalTV, bool lok)> Run(bool bypass)
			{
				CrossBuy.BL.StockService._testBypassLandedLockRead = bypass;
				await using var tx = await CrossBuy.BL.ScopedTx.BeginOrJoinAsync(_db);   // OWNER — rolled back (zero persistence)
				var (gok, gerr, gr) = await proc.CreateReceiptAsync(company, ven!.ID, wh, null, T, "ZZ lc grn", new List<CrossBuy.BL.ReceiptLineInput> { new() { ItemId = itemId, Qty = 10m, UnitCost = 20m } }, null);   // bal V=200, tracked
				// EXTERNAL write the identity map can't see (a concurrent receipt/sale on the same item): +DELTA on TotalValue
				await _db.Database.ExecuteSqlRawAsync("UPDATE StockBalances SET TotalValue = TotalValue + {0} WHERE CompanyID = {1} AND ItemId = {2} AND WarehouseId = {3}", DELTA, company, itemId, wh);
				var (lok, lerr, _) = await _stock.PostLandedCostAsync(company, gr!.ID, T, "Value", new List<CrossBuy.BL.LandedChargeInput> { new() { Description = "freight", Amount = SHARE, AccountId = accFreight } }, "ZZ lc", null);
				decimal finalTV = await _db.StockBalances.AsNoTracking().Where(b => b.ItemId == itemId && b.WarehouseId == wh).Select(b => b.TotalValue).FirstAsync();
				await tx.RollbackAsync();
				CrossBuy.BL.StockService._testBypassLandedLockRead = false;
				return (finalTV, lok);
			}

			var (preTV, preOk) = await Run(true);    // pre-fix (unlocked stale read) ⇒ overwrites ⇒ V+share, Δ lost
			var (postTV, postOk) = await Run(false); // fixed (locked read + Reload) ⇒ V+Δ+share
			Chk($"pre-fix REPRODUCES the lost update: TotalValue={preTV} == V+share={V + SHARE} (concurrent Δ={DELTA} LOST)", preOk && preTV == V + SHARE);
			Chk($"fixed PRESERVES the concurrent Δ: TotalValue={postTV} == V+Δ+share={V + DELTA + SHARE}", postOk && postTV == V + DELTA + SHARE);
			log.Add($"  numbers: V={V} Δ={DELTA} share={SHARE} · pre-fix={preTV} (expect {V + SHARE}) · fixed={postTV} (expect {V + DELTA + SHARE})");
			log.Add($"  zero persistence — both scenarios rolled back; ZZ-LC-ITM ends with no stock.");
			return Ok(new { allPass, log });
		}

		// GET /api/dev/apply-preset-guard-test?key=seed123 — HM-1-أ صفر-تكميلي-3. Tests the ApplyPreset activity guard
		// STRICTLY on throwaway branches it creates (ZZ-GUARD-*), then removes them. Touches NO existing branch.
		[HttpGet("apply-preset-guard-test")]
		public async Task<IActionResult> ApplyPresetGuardTest(string key)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			var results = new List<object>();
			int fails = 0;

			var A = new CrossBuy.Models.Context.Admin.Branch { Name = "ZZ-GUARD-A", NameAr = "اختبار أ", Location = "t", CountryID = 32, CompanyID = 79, PhoneNumber = "", Email = "", Description = "guard test", ActivityPresetCode = null };
			var B = new CrossBuy.Models.Context.Admin.Branch { Name = "ZZ-GUARD-B", NameAr = "اختبار ب", Location = "t", CountryID = 32, CompanyID = 79, PhoneNumber = "", Email = "", Description = "guard test", ActivityPresetCode = null };
			_db.Branches.Add(A); _db.Branches.Add(B); await _db.SaveChangesAsync();
			await _posSetup.SaveTerminalAsync(A.ID, 0, "ZZ-TA", "TA", "ZZ-TA-", null, false, true);   // gives A operational history (a terminal), no cash account

			async Task Run(string label, int bid, string code, bool conscious, bool expectOk)
			{
				var (ok, err) = await _posSetup.ApplyPresetAsync(bid, code, conscious);
				bool pass = ok == expectOk; if (!pass) fails++;
				results.Add(new { test = label, expectOk, actualOk = ok, pass, error = err });
			}
			await Run("A(has terminal)+Hyper, casual → REFUSE", A.ID, "Hyper", false, false);
			await Run("A(has terminal)+Restaurant, casual → ALLOW", A.ID, "Restaurant", false, true);
			await Run("B(clean)+Hyper, casual → ALLOW", B.ID, "Hyper", false, true);
			await Run("A(now Restaurant)+Cafe, casual → REFUSE (set-change)", A.ID, "Cafe", false, false);
			await Run("A+Cafe, CONSCIOUS path → ALLOW", A.ID, "Cafe", true, true);

			// cleanup — remove ONLY the throwaway entities this test created
			var bids = new[] { A.ID, B.ID };
			_db.BranchCapabilities.RemoveRange(_db.BranchCapabilities.Where(c => bids.Contains(c.BranchId)));
			_db.PosTerminals.RemoveRange(_db.PosTerminals.Where(t => bids.Contains(t.BranchId)));
			await _db.SaveChangesAsync();
			_db.Branches.RemoveRange(_db.Branches.Where(b => bids.Contains(b.ID)));
			await _db.SaveChangesAsync();

			return Ok(new { allPass = fails == 0, failCount = fails, results, note = "throwaway branches ZZ-GUARD-* created and removed; no existing branch touched." });
		}

		// GET /api/dev/numbering-concurrency-test?key=seed123 — HM-1-أ ب-1-4. 10 PARALLEL allocations (separate DI
		// scopes = separate DbContexts = real concurrency) of a receipt number AND of a JE sequence number, on
		// THROWAWAY entities only. Proves: distinct numbers, counter advanced by exactly 10, no unique-violation.
		[HttpGet("numbering-concurrency-test")]
		public async Task<IActionResult> NumberingConcurrencyTest(string key)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int N = 10;

			// ---- Part A: receipt number on a throwaway branch+terminal ----
			var br = new CrossBuy.Models.Context.Admin.Branch { Name = "ZZ-CONC-BR", NameAr = "تزامن", Location = "t", CountryID = 32, CompanyID = 79, PhoneNumber = "", Email = "", Description = "conc test", ActivityPresetCode = null };
			_db.Branches.Add(br); await _db.SaveChangesAsync();
			var (_, _, termId) = await _posSetup.SaveTerminalAsync(br.ID, 0, "ZZ-CT", "ct", "ZZ-CT-", null, false, true);

			var recTasks = Enumerable.Range(0, N).Select(_ => Task.Run(async () =>
			{
				try { using var sc = _scopes.CreateScope(); var svc = sc.ServiceProvider.GetRequiredService<CrossBuy.BL.IPosOrderService>(); return await svc.AllocateReceiptNoAsync(termId); }
				catch (Exception ex) { return "ERR:" + ex.Message; }
			}));
			var recRes = (await Task.WhenAll(recTasks)).ToList();
			int recErrs = recRes.Count(x => x.StartsWith("ERR:"));
			int recDistinct = recRes.Where(x => !x.StartsWith("ERR:")).Distinct().Count();
			int termAfter = await _db.PosTerminals.AsNoTracking().Where(t => t.ID == termId).Select(t => t.NextReceiptNo).FirstAsync();
			bool recPass = recErrs == 0 && recDistinct == N && termAfter == N + 1;

			// ---- Part B: JE sequence on a throwaway NumberSequences key (same atomic SQL as ReserveEntryNoAsync) ----
			const string seqKey = "ZZ-CONC";
			_db.NumberSequences.Add(new CrossBuy.Models.Context.Accounting.NumberSequence { CompanyID = 1, SequenceKey = seqKey, FiscalYearId = 1, Prefix = "ZZ", NextNumber = 1, PadLength = 6 });
			await _db.SaveChangesAsync();
			var jeTasks = Enumerable.Range(0, N).Select(_ => Task.Run<object>(async () =>
			{
				try { using var sc = _scopes.CreateScope(); var db2 = sc.ServiceProvider.GetRequiredService<CrossDbContext>();
					return (await db2.Database.SqlQueryRaw<int>("UPDATE dbo.NumberSequences SET NextNumber = NextNumber + 1 OUTPUT deleted.NextNumber AS [Value] WHERE SequenceKey = {0}", seqKey).ToListAsync()).Single(); }
				catch (Exception ex) { return "ERR:" + ex.Message; }
			}));
			var jeRes = (await Task.WhenAll(jeTasks)).ToList();
			int jeErrs = jeRes.Count(x => x is string s && s.StartsWith("ERR:"));
			var jeNums = jeRes.OfType<int>().OrderBy(x => x).ToList();
			int jeDistinct = jeNums.Distinct().Count();
			int seqAfter = await _db.NumberSequences.AsNoTracking().Where(s => s.SequenceKey == seqKey).Select(s => s.NextNumber).FirstAsync();
			bool jePass = jeErrs == 0 && jeDistinct == N && seqAfter == N + 1 && jeNums.SequenceEqual(Enumerable.Range(1, N));

			// ---- Part C (ب-2-3.1): CREATION race — 10 parallel run the exact ensure-then-allocate batch on a key that
			// does NOT exist yet. Proves exactly ONE row is created (no duplicates) and numbers stay 1..N. ----
			const string newKey = "ZZ-NEWKEY";
			_db.NumberSequences.RemoveRange(_db.NumberSequences.Where(s => s.SequenceKey == newKey)); await _db.SaveChangesAsync();   // ensure absent
			var crTasks = Enumerable.Range(0, N).Select(_ => Task.Run<object>(async () =>
			{
				try { using var sc = _scopes.CreateScope(); var db3 = sc.ServiceProvider.GetRequiredService<CrossDbContext>();
					return (await db3.Database.SqlQueryRaw<int>(
						@"SET NOCOUNT ON;
IF NOT EXISTS (SELECT 1 FROM dbo.NumberSequences WITH (UPDLOCK, HOLDLOCK) WHERE CompanyID={0} AND SequenceKey={1} AND FiscalYearId={2})
    INSERT INTO dbo.NumberSequences (CompanyID,SequenceKey,FiscalYearId,Prefix,NextNumber,PadLength) VALUES ({0},{1},{2},'ZZ',1,6);
UPDATE dbo.NumberSequences SET NextNumber=NextNumber+1 OUTPUT deleted.NextNumber AS [Value] WHERE CompanyID={0} AND SequenceKey={1} AND FiscalYearId={2};",
						1, newKey, 1).ToListAsync()).Single(); }
				catch (Exception ex) { return "ERR:" + ex.Message; }
			}));
			var crRes = (await Task.WhenAll(crTasks)).ToList();
			int crErrs = crRes.Count(x => x is string s && s.StartsWith("ERR:"));
			var crNums = crRes.OfType<int>().OrderBy(x => x).ToList();
			int crRows = await _db.NumberSequences.CountAsync(s => s.SequenceKey == newKey);   // MUST be exactly 1
			bool crPass = crErrs == 0 && crRows == 1 && crNums.Distinct().Count() == N && crNums.SequenceEqual(Enumerable.Range(1, N));

			// cleanup throwaway entities only
			_db.NumberSequences.RemoveRange(_db.NumberSequences.Where(s => s.SequenceKey == seqKey || s.SequenceKey == newKey));
			_db.PosTerminals.RemoveRange(_db.PosTerminals.Where(t => t.BranchId == br.ID));
			await _db.SaveChangesAsync();
			_db.Branches.RemoveRange(_db.Branches.Where(b => b.ID == br.ID));
			await _db.SaveChangesAsync();

			return Ok(new
			{
				allPass = recPass && jePass && crPass,
				receipt = new { pass = recPass, errors = recErrs, distinct = recDistinct, counterAfter = termAfter, numbers = recRes.OrderBy(x => x) },
				jeSeq = new { pass = jePass, errors = jeErrs, distinct = jeDistinct, counterAfter = seqAfter, numbers = jeNums },
				creationRace = new { pass = crPass, errors = crErrs, rowsCreated = crRows, distinct = crNums.Distinct().Count(), numbers = crNums }
			});
		}

		// GET /api/dev/hm1-b3-test?key=seed123 — HM-1-أ ب-3 smoke test of the ambient "own-or-join" transaction on the sale path.
		// Part A: a normal sale COMMITS revenue + COGS + stock movement together (ambient tx commits).
		// Part B: an insufficient-stock sale rolls back the WHOLE sale — no orphan invoice / JE / movement (no revenue without cost) —
		//         and returns the StockService error verbatim. Runs on throwaway ZZ entities; teardown REVERSES the ZZ JEs (never deletes) and removes ZZ scaffolding.
		[HttpGet("hm1-b3-test")]
		public async Task<IActionResult> Hm1B3Test(string key)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1;
			var log = new List<string>();

			var cat = await _db.ItemCategories.AsNoTracking().FirstOrDefaultAsync(c => c.CompanyID == company && c.InventoryAccountId != null);
			int? revenue = await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.Code == "4101").Select(a => (int?)a.ID).FirstOrDefaultAsync();
			int baseUom = await _db.UnitsOfMeasure.AsNoTracking().Where(u => u.CompanyID == company).Select(u => u.ID).FirstOrDefaultAsync();
			if (cat == null || revenue == null || baseUom == 0) return BadRequest(new { message = "need a GL-wired category, account 4101, and a unit" });

			// ZZ warehouse (negative stock OFF so an over-sell fails)
			await _whSvc.CreateWarehouseAsync(company, new CrossBuy.Models.Context.Inventory.Warehouse { Code = "ZZB3WH", Name = "اختبار ب-3", NameEn = "B3 test" }, null);
			var wh = await _db.Warehouses.FirstAsync(w => w.CompanyID == company && w.Code == "ZZB3WH");
			if (wh.AllowNegativeStock) { wh.AllowNegativeStock = false; await _db.SaveChangesAsync(); }

			// ZZ stockable item
			var (iok, ierr, item) = await _itemSvc.CreateItemAsync(company, new CrossBuy.BL.ItemInput
			{
				ItemCode = "ZZ-B3-ITEM", Barcode = "ZZB3BARCODE", Name = "صنف اختبار ب-3", NameEn = "B3 test item",
				ItemCategoryId = cat.ID, ItemType = CrossBuy.Models.Context.Inventory.ItemTypes.Stockable,
				BaseUoMId = baseUom, SalesPrice = 100m, OpeningCost = 60m, IsActive = true
			}, null);
			if (!iok || item == null) return BadRequest(new { message = "ZZ item create failed: " + ierr });

			// ZZ customer (SaveCustomerAsync assigns the AR control account)
			await _ar.SaveCustomerAsync(company, new CrossBuy.Models.Context.Accounting.Customer { Name = "عميل اختبار ب-3", Phone = "0", IsActive = true });
			var cust = await _db.Customers.OrderByDescending(c => c.ID).FirstAsync(c => c.CompanyID == company && c.Name == "عميل اختبار ب-3");

			// receive 10 @ 60 (GL on) so stock + inventory value exist
			var (rok, rerr, rmv) = await _stock.PostMovementAsync(company, new CrossBuy.BL.MovementRequest
			{ ItemId = item.ID, WarehouseId = wh.ID, Direction = 1, Qty = 10, UnitCostInBase = 60m, SourceType = "Opening", PostToGl = true }, null);
			log.Add($"receive ok={rok} err={rerr}");

			CrossBuy.BL.SalesLineInput Line(decimal qty) => new() { ItemDescription = item.Name, Qty = qty, UnitPrice = 100m, TaxRate = 0, RevenueAccountId = revenue.Value, ItemId = item.ID, WarehouseId = wh.ID };

			// ---- Part A: SUCCESS — sell 3, expect commit of revenue + COGS + movement + stock 10→7 ----
			var (aok, aerr, ainv) = await _ar.CreateSalesInvoiceAsync(company, cust.ID, DateTime.Today, new List<CrossBuy.BL.SalesLineInput> { Line(3) }, "ZZ-B3 success", null);
			var (aQty, aVal, _) = await _stock.GetBalanceAsync(company, item.ID, wh.ID);
			var aMove = await _db.StockMovements.AsNoTracking().Where(m => m.ItemId == item.ID && m.SourceType == "SalesInvoice").OrderByDescending(m => m.ID).FirstOrDefaultAsync();
			bool successPass = aok && ainv != null && ainv.JournalEntryId != null && aMove != null && aMove.JournalEntryId != null && aQty == 7m;
			log.Add($"success ok={aok} err={aerr} inv={ainv?.InvoiceNo} salesJe={ainv?.JournalEntryId} cogsJe={aMove?.JournalEntryId} qtyAfter={aQty}");

			// ---- Part B: FAILURE — sell 100 (only 7 on hand, negative OFF) → whole sale must roll back ----
			int invBefore = await _db.SalesInvoices.CountAsync(i => i.CustomerId == cust.ID);
			int jeBefore = await _db.JournalEntries.CountAsync();
			int mvBefore = await _db.StockMovements.CountAsync(m => m.ItemId == item.ID);
			var (bok, berr, binv) = await _ar.CreateSalesInvoiceAsync(company, cust.ID, DateTime.Today, new List<CrossBuy.BL.SalesLineInput> { Line(100) }, "ZZ-B3 forced-fail", null);
			int invAfter = await _db.SalesInvoices.CountAsync(i => i.CustomerId == cust.ID);
			int jeAfter = await _db.JournalEntries.CountAsync();
			int mvAfter = await _db.StockMovements.CountAsync(m => m.ItemId == item.ID);
			var (bQty, _, _) = await _stock.GetBalanceAsync(company, item.ID, wh.ID);
			bool failPass = !bok && !string.IsNullOrEmpty(berr) && binv == null
							&& invAfter == invBefore && jeAfter == jeBefore && mvAfter == mvBefore && bQty == 7m;
			log.Add($"forcedFail ok={bok} err={berr} invΔ={invAfter - invBefore} jeΔ={jeAfter - jeBefore} mvΔ={mvAfter - mvBefore} qty={bQty}");

			// ---- teardown: reverse ZZ JEs (never delete a JE), then hard-remove ZZ scaffolding ----
			var teardown = new List<string>();
			var zzJeIds = new List<int>();
			if (rmv?.JournalEntryId != null) zzJeIds.Add(rmv.JournalEntryId.Value);
			if (ainv?.JournalEntryId != null) zzJeIds.Add(ainv.JournalEntryId.Value);
			if (aMove?.JournalEntryId != null) zzJeIds.Add(aMove.JournalEntryId.Value);
			foreach (var jeId in zzJeIds.Distinct()) { var (rvok, rverr, _) = await _je.ReverseAsync(jeId, null, "ZZ-B3 teardown"); teardown.Add($"reverse {jeId}: {(rvok ? "ok" : rverr)}"); }
			await _db.StockMovements.Where(m => m.CompanyID == company && m.ItemId == item.ID).ExecuteDeleteAsync();
			await _db.StockCostLayers.Where(l => l.CompanyID == company && l.ItemId == item.ID).ExecuteDeleteAsync();
			await _db.StockBalances.Where(b => b.CompanyID == company && b.ItemId == item.ID).ExecuteDeleteAsync();
			var invIds = await _db.SalesInvoices.Where(i => i.CustomerId == cust.ID).Select(i => i.ID).ToListAsync();
			await _db.SalesInvoiceLines.Where(l => invIds.Contains(l.SalesInvoiceId)).ExecuteDeleteAsync();
			await _db.SalesInvoices.Where(i => i.CustomerId == cust.ID).ExecuteDeleteAsync();
			await _db.ItemBarcodes.Where(b => b.ItemId == item.ID).ExecuteDeleteAsync();
			await _db.Items.Where(i => i.ID == item.ID).ExecuteDeleteAsync();
			await _db.Customers.Where(c => c.ID == cust.ID).ExecuteDeleteAsync();
			await _db.Warehouses.Where(w => w.ID == wh.ID).ExecuteDeleteAsync();

			// HM-D9 precondition: FAIL if ANY ZZ stock row survived OR integrity is not green after teardown
			int zzResidue = await _db.StockMovements.CountAsync(m => m.ItemId == item.ID) + await _db.StockBalances.CountAsync(b => b.ItemId == item.ID) + await _db.StockCostLayers.CountAsync(l => l.ItemId == item.ID) + await _db.StockBatches.CountAsync(b => b.ItemId == item.ID);
			var _integ9 = HttpContext.RequestServices.GetRequiredService<CrossBuy.BL.IIntegrityCheckService>();
			var (_run9, _) = await _integ9.RunAndLogAsync(company, "hm1-b3-td");   // ≤20: IntegrityCheckRuns.Source is nvarchar(20)
			bool teardownClean = zzResidue == 0 && _run9.FailedCount == 0;

			return Ok(new
			{
				allPass = successPass && failPass && teardownClean,
				teardownClean, zzResidue, teardownFailedCount = _run9.FailedCount,
				partA_success = new { pass = successPass, proves = "ambient tx commits revenue + COGS + movement + stock together", detail = log.Count > 1 ? log[1] : "" },
				partB_forcedFail = new { pass = failPass, proves = "insufficient stock → whole sale rolled back (no revenue without cost); StockService error returned verbatim", stockServiceError = berr, detail = log.Count > 2 ? log[2] : "" },
				teardown,
				note = "ZZ throwaway; the two success JEs were reversed (net-zero, balanced) and all ZZ scaffolding removed. The reversal advanced the JV counter, so a few new-period gaps (>1162) are expected — the entryno_dup check counts them (warning only, never a failure)."
			});
		}

		// GET /api/dev/hm1-b3-tracker-test?key=seed123 — HM-1-أ ب-3 CORRECTION proof: a DB rollback does NOT reset EF's
		// ChangeTracker, and the DbContext is request-Scoped. This fails a sale on purpose, then does further writes on the
		// SAME context in the SAME request and proves there is NO phantom: tracker is empty after the failed sale, a plain
		// SaveChanges writes 0 rows (no Added entity re-inserted), no DbUpdateConcurrencyException, and a following real sale
		// commits correctly and is the ONLY invoice. Runs on throwaway ZZ entities.
		[HttpGet("hm1-b3-tracker-test")]
		public async Task<IActionResult> Hm1B3TrackerTest(string key)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1;

			var cat = await _db.ItemCategories.AsNoTracking().FirstOrDefaultAsync(c => c.CompanyID == company && c.InventoryAccountId != null);
			int? revenue = await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.Code == "4101").Select(a => (int?)a.ID).FirstOrDefaultAsync();
			int baseUom = await _db.UnitsOfMeasure.AsNoTracking().Where(u => u.CompanyID == company).Select(u => u.ID).FirstOrDefaultAsync();
			if (cat == null || revenue == null || baseUom == 0) return BadRequest(new { message = "need a GL-wired category, account 4101, and a unit" });

			await _whSvc.CreateWarehouseAsync(company, new CrossBuy.Models.Context.Inventory.Warehouse { Code = "ZZB3TWH", Name = "اختبار متتبّع ب-3", NameEn = "B3 tracker WH" }, null);
			var wh = await _db.Warehouses.FirstAsync(w => w.CompanyID == company && w.Code == "ZZB3TWH");
			if (wh.AllowNegativeStock) { wh.AllowNegativeStock = false; await _db.SaveChangesAsync(); }

			var (iok, ierr, item) = await _itemSvc.CreateItemAsync(company, new CrossBuy.BL.ItemInput
			{
				ItemCode = "ZZ-B3-TRK", Barcode = "ZZB3TRKBC", Name = "صنف متتبّع ب-3", NameEn = "B3 tracker item",
				ItemCategoryId = cat.ID, ItemType = CrossBuy.Models.Context.Inventory.ItemTypes.Stockable,
				BaseUoMId = baseUom, SalesPrice = 100m, OpeningCost = 60m, IsActive = true
			}, null);
			if (!iok || item == null) return BadRequest(new { message = "ZZ item create failed: " + ierr });
			await _ar.SaveCustomerAsync(company, new CrossBuy.Models.Context.Accounting.Customer { Name = "عميل متتبّع ب-3", Phone = "0", IsActive = true });
			var cust = await _db.Customers.OrderByDescending(c => c.ID).FirstAsync(c => c.CompanyID == company && c.Name == "عميل متتبّع ب-3");
			var (rok, rerr, rmv) = await _stock.PostMovementAsync(company, new CrossBuy.BL.MovementRequest
			{ ItemId = item.ID, WarehouseId = wh.ID, Direction = 1, Qty = 5, UnitCostInBase = 60m, SourceType = "Opening", PostToGl = true }, null);

			CrossBuy.BL.SalesLineInput Line(decimal qty) => new() { ItemDescription = item.Name, Qty = qty, UnitPrice = 100m, TaxRate = 0, RevenueAccountId = revenue.Value, ItemId = item.ID, WarehouseId = wh.ID };

			// PROOF-0: this action is ONE HTTP request ⇒ ONE request-Scoped CrossDbContext. Prove _db IS that scoped
			// instance; _ar (IReceivableService) is resolved from the SAME scope with CrossDbContext injected, so _ar's
			// context is the SAME object as _db (AddDbContext<CrossDbContext> is Scoped). ⇒ the tracker checks below are
			// on the very context the failed sale used — not a fresh one.
			bool sameContext = ReferenceEquals(_db, HttpContext.RequestServices.GetService(typeof(CrossDbContext)) as CrossDbContext);

			// baselines (committed DB rows) BEFORE the failed sale
			int invBefore = await _db.SalesInvoices.CountAsync();
			int jeBefore = await _db.JournalEntries.CountAsync();
			int jelBefore = await _db.JournalEntryLines.CountAsync();
			int mvBefore = await _db.StockMovements.CountAsync();
			var (qtyBefore, _, _) = await _stock.GetBalanceAsync(company, item.ID, wh.ID);   // expect 5

			// (1) FAIL a sale on purpose (100 > 5 on hand, negative OFF) — this is where phantom entities would linger.
			var (fok, ferr, finv) = await _ar.CreateSalesInvoiceAsync(company, cust.ID, DateTime.Today, new List<CrossBuy.BL.SalesLineInput> { Line(100) }, "ZZ-B3 tracker fail", null);

			// (2) IMMEDIATELY inspect the tracker + force a plain SaveChanges on the SAME context (this is exactly what a
			// later write in the same request would trigger — the moment a lingering Added phantom would be re-inserted).
			int trackedAfterFail = _db.ChangeTracker.Entries().Count();     // expect 0 — owner rollback cleared it
			int phantomWrites = -99; string? concurrencyErr = null;
			try { phantomWrites = await _db.SaveChangesAsync(); }            // expect 0 — no Added phantom re-inserted
			catch (Microsoft.EntityFrameworkCore.DbUpdateConcurrencyException ex) { concurrencyErr = "DbUpdateConcurrencyException: " + ex.Message; }
			catch (Exception ex) { concurrencyErr = ex.GetType().Name + ": " + ex.Message; }

			// committed DB rows AFTER the fail+SaveChanges — must equal the baselines (the failed sale persisted NOTHING)
			int invAfterFail = await _db.SalesInvoices.CountAsync();
			int jeAfterFail = await _db.JournalEntries.CountAsync();
			int jelAfterFail = await _db.JournalEntryLines.CountAsync();
			int mvAfterFail = await _db.StockMovements.CountAsync();
			var (qtyAfterFail, _, _) = await _stock.GetBalanceAsync(company, item.ID, wh.ID);
			bool noPhantomRows = invAfterFail == invBefore && jeAfterFail == jeBefore && jelAfterFail == jelBefore && mvAfterFail == mvBefore && qtyAfterFail == qtyBefore;

			// (2b) CONTROL — prove ScopedTx.RollbackAsync() actually EMPTIES a KNOWN-nonempty tracker (so the checks above
			// aren't vacuous): add a throwaway row inside an OWNED ScopedTx, confirm it IS tracked as Added, roll back,
			// then confirm the tracker is empty, a plain SaveChanges writes 0, and nothing persisted.
			int ctrlAddedInside, ctrlTrackedAfter, ctrlPlainWrite, ctrlRows;
			await using (var ctrlTx = await CrossBuy.BL.ScopedTx.BeginOrJoinAsync(_db))
			{
				_db.NumberSequences.Add(new CrossBuy.Models.Context.Accounting.NumberSequence { CompanyID = 1, SequenceKey = "ZZ-CTRL", FiscalYearId = 1, Prefix = "ZZ", NextNumber = 1, PadLength = 6 });
				ctrlAddedInside = _db.ChangeTracker.Entries().Count(e => e.State == Microsoft.EntityFrameworkCore.EntityState.Added);   // >= 1
				await ctrlTx.RollbackAsync();   // OWNER ⇒ DB rollback + ChangeTracker.Clear()
			}
			ctrlTrackedAfter = _db.ChangeTracker.Entries().Count();          // 0
			ctrlPlainWrite = await _db.SaveChangesAsync();                    // 0 — the Added ZZ-CTRL was NOT re-inserted
			ctrlRows = await _db.NumberSequences.CountAsync(s => s.SequenceKey == "ZZ-CTRL");   // 0 — nothing persisted

			// (3) a SUBSEQUENT real sale on the SAME context must commit correctly and be the ONLY invoice.
			var (sok, serr, sinv) = await _ar.CreateSalesInvoiceAsync(company, cust.ID, DateTime.Today, new List<CrossBuy.BL.SalesLineInput> { Line(2) }, "ZZ-B3 tracker ok", null);
			int invCount = await _db.SalesInvoices.CountAsync(i => i.CustomerId == cust.ID);
			int mvCount = await _db.StockMovements.CountAsync(m => m.ItemId == item.ID && m.SourceType == "SalesInvoice");
			var (qtyAfter, _, _) = await _stock.GetBalanceAsync(company, item.ID, wh.ID);
			var sMove = await _db.StockMovements.AsNoTracking().Where(m => m.ItemId == item.ID && m.SourceType == "SalesInvoice").OrderByDescending(m => m.ID).FirstOrDefaultAsync();

			bool pass = sameContext                                              // the checks are on the request-scoped context
						&& !fok && !string.IsNullOrEmpty(ferr) && finv == null      // the fail rolled back
						&& trackedAfterFail == 0 && noPhantomRows                   // tracker cleared AND no committed phantom row
						&& phantomWrites == 0 && concurrencyErr == null             // plain SaveChanges wrote nothing, no concurrency crash
						&& ctrlAddedInside >= 1 && ctrlTrackedAfter == 0 && ctrlPlainWrite == 0 && ctrlRows == 0   // control: clear works on a known-nonempty tracker
						&& sok && sinv != null && invCount == 1 && mvCount == 1     // exactly ONE invoice + ONE COGS movement (the success only)
						&& qtyAfter == 3m;                                          // 5 received − 2 sold; the 100 never happened

			// teardown: reverse ZZ JEs (never delete), remove ZZ scaffolding
			var teardown = new List<string>();
			foreach (var jeId in new[] { rmv?.JournalEntryId, sinv?.JournalEntryId, sMove?.JournalEntryId }.Where(x => x != null).Select(x => x!.Value).Distinct())
			{ var (rvok, rverr, _) = await _je.ReverseAsync(jeId, null, "ZZ-B3 tracker teardown"); teardown.Add($"reverse {jeId}: {(rvok ? "ok" : rverr)}"); }
			await _db.StockMovements.Where(m => m.CompanyID == company && m.ItemId == item.ID).ExecuteDeleteAsync();
			await _db.StockCostLayers.Where(l => l.CompanyID == company && l.ItemId == item.ID).ExecuteDeleteAsync();
			await _db.StockBalances.Where(b => b.CompanyID == company && b.ItemId == item.ID).ExecuteDeleteAsync();
			var invIds = await _db.SalesInvoices.Where(i => i.CustomerId == cust.ID).Select(i => i.ID).ToListAsync();
			await _db.SalesInvoiceLines.Where(l => invIds.Contains(l.SalesInvoiceId)).ExecuteDeleteAsync();
			await _db.SalesInvoices.Where(i => i.CustomerId == cust.ID).ExecuteDeleteAsync();
			await _db.ItemBarcodes.Where(b => b.ItemId == item.ID).ExecuteDeleteAsync();
			await _db.Items.Where(i => i.ID == item.ID).ExecuteDeleteAsync();
			await _db.Customers.Where(c => c.ID == cust.ID).ExecuteDeleteAsync();
			await _db.Warehouses.Where(w => w.ID == wh.ID).ExecuteDeleteAsync();

			// HM-D9 precondition: FAIL (not merely report) if ANY ZZ stock row survived OR integrity is not green after teardown
			int zzResidue = await _db.StockMovements.CountAsync(m => m.ItemId == item.ID) + await _db.StockBalances.CountAsync(b => b.ItemId == item.ID) + await _db.StockCostLayers.CountAsync(l => l.ItemId == item.ID) + await _db.StockBatches.CountAsync(b => b.ItemId == item.ID);
			var _integ9 = HttpContext.RequestServices.GetRequiredService<CrossBuy.BL.IIntegrityCheckService>();
			var (_run9, _) = await _integ9.RunAndLogAsync(company, "hm1-b3-trk-td");   // ≤20: IntegrityCheckRuns.Source is nvarchar(20)
			bool teardownClean = zzResidue == 0 && _run9.FailedCount == 0;
			pass = pass && teardownClean;

			return Ok(new
			{
				pass, teardownClean, zzResidue, teardownFailedCount = _run9.FailedCount,
				sameRequestContext = sameContext,
				failedSale = new { ok = fok, err = ferr, invoiceReturned = finv != null },
				afterFail = new { trackedEntities = trackedAfterFail, plainSaveChangesWrote = phantomWrites, concurrencyException = concurrencyErr ?? "none" },
				rowsBeforeVsAfterFail = new {
					invoices = $"{invBefore}→{invAfterFail}", journalEntries = $"{jeBefore}→{jeAfterFail}",
					journalEntryLines = $"{jelBefore}→{jelAfterFail}", stockMovements = $"{mvBefore}→{mvAfterFail}",
					itemQty = $"{qtyBefore}→{qtyAfterFail}", noPhantomRows
				},
				controlClear = new { addedInsideTx = ctrlAddedInside, trackedAfterRollback = ctrlTrackedAfter, plainSaveChangesWrote = ctrlPlainWrite, persistedRows = ctrlRows },
				subsequentRealSale = new { ok = sok, err = serr, invoiceCountForCustomer = invCount, cogsMovements = mvCount, stockQtyAfter = qtyAfter, expected = "1 invoice, 1 movement, qty 3" },
				teardown,
				proves = "SAME request/context (ReferenceEquals=true). A failed sale persisted ZERO rows and left an EMPTY tracker; a forced plain SaveChanges wrote 0 with no DbUpdateConcurrencyException; the control proves the clear empties a known-nonempty tracker; and the next real write on the same context committed correctly."
			});
		}

		// GET /api/dev/hm1-d5a-test?key=seed123 — HM-D5-أ: the receipt-counter advance now parses ONLY the numeric SUFFIX
		// after the terminal's prefix. On a ZZ terminal whose prefix CONTAINS a digit (ZZ6-), prove an in-series 6-digit
		// receipt advances the counter by exactly 1 (not to 6 million), a prefix mismatch freezes the counter + records an
		// anomaly, and regression still advances. Runs the REAL PosOrderService method on a throwaway ZZ terminal.
		[HttpGet("hm1-d5a-test")]
		public async Task<IActionResult> Hm1D5aTest(string key)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			async Task<int> Ctr(int tid) => await _db.PosTerminals.AsNoTracking().Where(t => t.ID == tid).Select(t => t.NextReceiptNo).FirstAsync();

			// ZZ branch + terminal with a DIGIT in the prefix (ZZ6-) — the worst case for the old all-digits scrape
			var br = new CrossBuy.Models.Context.Admin.Branch { Name = "ZZ-D5A-BR", NameAr = "اختبار كشط", Location = "t", CountryID = 32, CompanyID = 79, PhoneNumber = "", Email = "", Description = "d5a", ActivityPresetCode = null };
			_db.Branches.Add(br); await _db.SaveChangesAsync();
			var (_, _, termId) = await _posSetup.SaveTerminalAsync(br.ID, 0, "ZZ6-T", "d5a", "ZZ6-", null, false, true);
			await _db.Database.ExecuteSqlRawAsync("UPDATE PosTerminals SET NextReceiptNo = 5 WHERE ID = {0}", termId);

			int oldScrape = int.Parse(new string("ZZ6-000012".Where(char.IsDigit).ToArray()), System.Globalization.NumberStyles.None, System.Globalization.CultureInfo.InvariantCulture);   // OLD bug = 6000012

			// 1) normal 6-digit IN-SERIES → counter 5 → 13 (n=12,+1), NOT 6000013
			var t1 = await _db.PosTerminals.FirstAsync(t => t.ID == termId);
			var r1 = await _posOrders.AdvanceCounterPastOfflineReceiptAsync(t1, "ZZ6-000012");
			int c1 = await Ctr(termId);
			// 1b) IDEMPOTENCY (corr. 6): SAME receipt again → conditional (NextReceiptNo <= n) keeps the counter — advances once only
			var t1b = await _db.PosTerminals.FirstAsync(t => t.ID == termId);
			var r1b = await _posOrders.AdvanceCounterPastOfflineReceiptAsync(t1b, "ZZ6-000012");
			int c1b = await Ctr(termId);
			// 2) prefix MISMATCH → counter frozen + anomaly returned (NOT advanced)
			var t2 = await _db.PosTerminals.FirstAsync(t => t.ID == termId);
			var r2 = await _posOrders.AdvanceCounterPastOfflineReceiptAsync(t2, "XYZ-000099");
			int c2 = await Ctr(termId);
			// 3) regression: a higher in-series number still advances (13 → 51)
			var t3 = await _db.PosTerminals.FirstAsync(t => t.ID == termId);
			var r3 = await _posOrders.AdvanceCounterPastOfflineReceiptAsync(t3, "ZZ6-000050");
			int c3 = await Ctr(termId);
			// 3b) int-OVERFLOW suffix (corr. 5a): a 12-digit suffix exceeds Int32 → TryParse fails → anomaly, counter FROZEN (intended)
			var t3b = await _db.PosTerminals.FirstAsync(t => t.ID == termId);
			var r3b = await _posOrders.AdvanceCounterPastOfflineReceiptAsync(t3b, "ZZ6-999999999999");
			int c3b = await Ctr(termId);

			// 4) prefix-change guard (corr. 3): give the terminal an OPEN (zero-footprint) order → a prefix CHANGE must be rejected; SAME prefix stays allowed
			_db.PosOrders.Add(new CrossBuy.Models.Context.Pos.PosOrder { CompanyId = 1, BranchId = br.ID, TerminalId = termId, Status = "Open", OrderType = "Takeaway", OpenedAt = DateTime.UtcNow });
			await _db.SaveChangesAsync();
			var (gChangeOk, gChangeErr, _) = await _posSetup.SaveTerminalAsync(br.ID, termId, "ZZ6-T", "d5a", "ZZ9-", null, false, true);   // change ZZ6- → ZZ9- (has orders) → REJECT
			var (gSameOk, _, _) = await _posSetup.SaveTerminalAsync(br.ID, termId, "ZZ6-T", "d5a", "ZZ6-", null, false, true);              // same prefix → allowed
			// 4b) CODE backdoor (corr. 2): change CODE with an EMPTY prefix → derived prefix (code+"-") changes → must be REJECTED too
			var (gCodeOk, gCodeErr, _) = await _posSetup.SaveTerminalAsync(br.ID, termId, "ZZ9-T", "d5a", null, null, false, true);
			var prefixAfter = await _db.PosTerminals.AsNoTracking().Where(t => t.ID == termId).Select(t => t.ReceiptPrefix).FirstAsync();
			var codeAfter = await _db.PosTerminals.AsNoTracking().Where(t => t.ID == termId).Select(t => t.Code).FirstAsync();

			bool pass = r1.advanced && r1.anomaly == null && c1 == 13 && c1.ToString("D6").Length == 6   // in-series: +1, 6 digits
						&& c1b == 13                                                                       // idempotent: same receipt keeps 13
						&& !r2.advanced && r2.anomaly != null && c2 == 13                                   // mismatch: frozen + anomaly
						&& r3.advanced && r3.anomaly == null && c3 == 51                                    // regression
						&& !r3b.advanced && r3b.anomaly != null && c3b == 51                                // int-overflow: frozen + anomaly
						&& oldScrape == 6000012 && c1 != oldScrape + 1                                      // old scrape would have jumped to 6000013
						&& !gChangeOk && gSameOk && prefixAfter == "ZZ6-"                                   // explicit-prefix change blocked, same allowed
						&& !gCodeOk && codeAfter == "ZZ6-T";                                                 // CODE backdoor blocked (code + prefix both unchanged)

			// teardown: the OPEN order + terminal + branch are ZERO-footprint (no invoice/JE/movement) → direct delete allowed (rule 5)
			await _db.PosOrders.Where(o => o.TerminalId == termId).ExecuteDeleteAsync();
			await _db.PosTerminals.Where(t => t.BranchId == br.ID).ExecuteDeleteAsync();
			await _db.Branches.Where(b => b.ID == br.ID).ExecuteDeleteAsync();

			return Ok(new
			{
				pass,
				prefixWithDigit = "ZZ6-",
				inSeries = new { input = "ZZ6-000012", advanced = r1.advanced, anomaly = r1.anomaly ?? "none", counter = $"5=>{c1}", expected = 13, nextNumberDigits = c1.ToString("D6").Length },
				idempotent = new { input = "ZZ6-000012 (again)", counterStaysAt = c1b, expected = 13 },
				prefixMismatch = new { input = "XYZ-000099", advanced = r2.advanced, anomaly = r2.anomaly ?? "none", counterFrozenAt = c2 },
				regression = new { input = "ZZ6-000050", advanced = r3.advanced, anomaly = r3.anomaly ?? "none", counter = $"13=>{c3}", expected = 51 },
				intOverflow = new { input = "ZZ6-999999999999 (12 digits)", advanced = r3b.advanced, anomaly = r3b.anomaly ?? "none", counterFrozenAt = c3b },
				prefixChangeGuard = new { changeRejected = !gChangeOk, error = gChangeErr, sameAllowed = gSameOk, prefixAfter },
				codeBackdoorGuard = new { changeViaCodeRejected = !gCodeOk, error = gCodeErr, codeAfter, prefixAfter },
				oldBugWouldHaveJumpedTo = oldScrape + 1,
				proves = "suffix-only parse; in-series +1 (6 digits); idempotent; mismatch & int-overflow frozen+recorded; regression intact; prefix change blocked via explicit prefix AND via Code backdoor once orders exist; old scrape would have hit 6000013."
			});
		}

		// HM-1-أ (البند ٦): teardown guard — a direct delete is allowed ONLY for a ZERO-FOOTPRINT entity. Returns (safe, why).
		// Financial effect (a JE line) or stock effect (a movement / balance row) ⇒ NOT safe (must be reversed via services first).
		private async Task<(bool safe, string why)> ItemDeletableAsync(int companyId, int itemId)
		{
			int mv = await _db.StockMovements.CountAsync(m => m.CompanyID == companyId && m.ItemId == itemId);
			int bl = await _db.StockBalances.CountAsync(b => b.CompanyID == companyId && b.ItemId == itemId);
			if (mv > 0 || bl > 0) return (false, $"has stock footprint: {mv} movement(s), {bl} balance row(s) — reverse via StockService, do NOT delete");
			return (true, "no stock footprint");
		}

		// GET /api/dev/hm1-closeshift-test?key=seed123 — HM-1-أ (هـ): CloseShiftAsync now posts the drawer-variance JE AND the
		// close fields in ONE own-or-join transaction. Proves: (a) close WITH a variance ⇒ shift Closed + VarianceJournalEntryId
		// set + JE exists (atomic); (b) close with variance 0 ⇒ NO JE (existing behaviour). Fixed ZZ terminal; variance JE reversed.
		[HttpGet("hm1-closeshift-test")]
		public async Task<IActionResult> Hm1CloseShiftTest(string key, [FromServices] CrossBuy.BL.IPosSetupService posSetup)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1;
			int drawer = await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.Code == "110101").Select(a => a.ID).FirstOrDefaultAsync();
			var br = await _db.Branches.FirstOrDefaultAsync(b => b.Name == "ZZ-SHIFT-BR" && b.CompanyID == company);
			if (br == null) { br = new CrossBuy.Models.Context.Admin.Branch { Name = "ZZ-SHIFT-BR", NameAr = "وردية", Location = "t", CountryID = 32, CompanyID = company, PhoneNumber = "", Email = "", Description = "shift", ActivityPresetCode = null }; _db.Branches.Add(br); await _db.SaveChangesAsync(); }
			var term = await _db.PosTerminals.FirstOrDefaultAsync(t => t.BranchId == br.ID && t.Code == "ZZSH-T");
			if (term == null) { term = new CrossBuy.Models.Context.Pos.PosTerminal { BranchId = br.ID, Code = "ZZSH-T", Name = "sh", CashAccountId = drawer, ReceiptPrefix = "ZZSH-", NextReceiptNo = 1, IsActive = true }; _db.PosTerminals.Add(term); await _db.SaveChangesAsync(); }
			foreach (var os in await _db.PosShifts.Where(s => s.TerminalId == term.ID && s.Status == "Open").ToListAsync()) { os.Status = "Closed"; os.ClosedAt = DateTime.UtcNow; }
			await _db.SaveChangesAsync();

			// (a) variance close: expected cash = 0 (no sales), close with float 10 ⇒ variance +10 ⇒ JE + fields atomic
			await posSetup.OpenShiftAsync(term.ID, "Morning", null, 0m);
			var sh1 = await posSetup.GetOpenShiftAsync(term.ID);
			var (c1ok, c1err) = await posSetup.CloseShiftAsync(company, term.ID, sh1!.ID, 10m, null, DateTime.Today, null);
			var sh1After = await _db.PosShifts.AsNoTracking().FirstAsync(s => s.ID == sh1.ID);
			bool jeExists = sh1After.VarianceJournalEntryId != null && await _db.JournalEntries.AnyAsync(e => e.ID == sh1After.VarianceJournalEntryId);
			bool aOk = c1ok && sh1After.Status == "Closed" && sh1After.VarianceJournalEntryId != null && jeExists;

			// (b) zero-variance close: NO JE
			await posSetup.OpenShiftAsync(term.ID, "Morning", null, 0m);
			var sh2 = await posSetup.GetOpenShiftAsync(term.ID);
			var (c2ok, _) = await posSetup.CloseShiftAsync(company, term.ID, sh2!.ID, 0m, null, DateTime.Today, null);
			var sh2After = await _db.PosShifts.AsNoTracking().FirstAsync(s => s.ID == sh2.ID);
			bool bOk = c2ok && sh2After.Status == "Closed" && sh2After.VarianceJournalEntryId == null;

			// teardown: reverse the variance JE via services (never delete a posted JE)
			var teardown = new List<string>();
			if (sh1After.VarianceJournalEntryId != null) { var (rv, rverr, _) = await _je.ReverseAsync(sh1After.VarianceJournalEntryId.Value, null, "ZZ shift-test teardown"); teardown.Add($"reverse {sh1After.VarianceJournalEntryId}: {(rv ? "ok" : rverr)}"); }

			return Ok(new
			{
				pass = aOk && bOk,
				varianceClose = new { ok = c1ok, err = c1err, status = sh1After.Status, varianceJe = sh1After.VarianceJournalEntryId, jeExists, atomic = aOk },
				zeroVarianceClose = new { ok = c2ok, status = sh2After.Status, varianceJe = sh2After.VarianceJournalEntryId, noJe = bOk },
				teardown,
				note = "fixed ZZ terminal (ZZSH-T) reused; variance JE reversed via ReverseAsync (never deleted)."
			});
		}

		// GET /api/dev/hm1-d6-concurrency-test?key=seed123 — HM-D6 correction 3: REAL concurrency through the fixed path.
		// Sale ‖ invoice-edit (reverse+repost) and Sale ‖ sales-return on the SAME item. Proves the final balance == net
		// movements (no lost update), no InvalidOperationException/deadlock, and the loser serialized on the UPDLOCK.
		// Fixed ZZ entities; transactions are legitimate + consistent (balanced GL, balance==movements) and left in place.
		[HttpGet("hm1-d6-concurrency-test")]
		public async Task<IActionResult> Hm1D6ConcurrencyTest(string key)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1; var log = new List<string>();
			var cat = await _db.ItemCategories.AsNoTracking().FirstOrDefaultAsync(c => c.CompanyID == company && c.InventoryAccountId != null);
			int revenue = await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.Code == "4101").Select(a => a.ID).FirstOrDefaultAsync();
			int baseUom = await _db.UnitsOfMeasure.AsNoTracking().Where(u => u.CompanyID == company).Select(u => u.ID).FirstOrDefaultAsync();
			int wh = await _db.Warehouses.AsNoTracking().Where(w => w.CompanyID == company).OrderBy(w => w.ID).Select(w => w.ID).FirstOrDefaultAsync();
			if (cat == null || revenue == 0 || baseUom == 0 || wh == 0) return BadRequest(new { message = "need category/4101/uom/warehouse" });
			var itm = await _db.Items.FirstOrDefaultAsync(i => i.CompanyID == company && i.ItemCode == "ZZ-CONC-ITM");
			if (itm == null) { var (iok, _, it2) = await _itemSvc.CreateItemAsync(company, new CrossBuy.BL.ItemInput { ItemCode = "ZZ-CONC-ITM", Barcode = "ZZCONCITM", Name = "تزامن D6", NameEn = "D6 conc", ItemCategoryId = cat.ID, ItemType = CrossBuy.Models.Context.Inventory.ItemTypes.Stockable, BaseUoMId = baseUom, SalesPrice = 100m, OpeningCost = 30m, IsActive = true }, null); if (!iok) return BadRequest(new { message = "ZZ item" }); itm = it2; }
			int itemId = itm!.ID;
			await _ar.SaveCustomerAsync(company, new CrossBuy.Models.Context.Accounting.Customer { Name = "عميل تزامن D6", Phone = "0", IsActive = true });
			int custId = await _db.Customers.Where(c => c.CompanyID == company && c.Name == "عميل تزامن D6").OrderByDescending(c => c.ID).Select(c => c.ID).FirstAsync();
			var (qtyNow, _, _) = await _stock.GetBalanceAsync(company, itemId, wh);
			if (qtyNow < 50) await _stock.PostMovementAsync(company, new CrossBuy.BL.MovementRequest { ItemId = itemId, WarehouseId = wh, Direction = 1, Qty = 300, UnitCostInBase = 30m, SourceType = "Opening", PostToGl = true }, null);

			CrossBuy.BL.SalesLineInput Line(decimal q) => new() { ItemDescription = itm.Name, Qty = q, UnitPrice = 100m, TaxRate = 0, RevenueAccountId = revenue, ItemId = itemId, WarehouseId = wh };
			async Task<decimal> BalMinusMoves() { var (b, _, _) = await _stock.GetBalanceAsync(company, itemId, wh); var m = await _db.StockMovements.AsNoTracking().Where(x => x.ItemId == itemId && x.WarehouseId == wh).SumAsync(x => (decimal?)(x.Direction * x.QtyBase)) ?? 0m; return b - m; }

			// pre-create an invoice to EDIT and one to RETURN against
			var (eok, _, einv) = await _ar.CreateSalesInvoiceAsync(company, custId, DateTime.Today, new List<CrossBuy.BL.SalesLineInput> { Line(2) }, "ZZ-conc edit-target", null);
			var (rok, _, rinv) = await _ar.CreateSalesInvoiceAsync(company, custId, DateTime.Today, new List<CrossBuy.BL.SalesLineInput> { Line(3) }, "ZZ-conc return-target", null);

			async Task<(string label, bool ok, string? err, long ms)> Op(string label, Func<CrossBuy.BL.IReceivableService, Task<(bool, string?)>> body)
			{
				var sw = System.Diagnostics.Stopwatch.StartNew();
				using var sc = _scopes.CreateScope(); var ar = sc.ServiceProvider.GetRequiredService<CrossBuy.BL.IReceivableService>();
				try { var (ok, err) = await body(ar); sw.Stop(); return (label, ok, err, sw.ElapsedMilliseconds); }
				catch (Exception ex) { sw.Stop(); return (label, false, ex.GetType().Name + ": " + ex.Message, sw.ElapsedMilliseconds); }
			}

			// ===== Case A: SALE ‖ EDIT (reverse+repost) on the same item =====
			decimal driftA0 = await BalMinusMoves();
			var aRes = await Task.WhenAll(
				Op("sale", async ar => { var (ok, err, _) = await ar.CreateSalesInvoiceAsync(company, custId, DateTime.Today, new List<CrossBuy.BL.SalesLineInput> { Line(1) }, "ZZ-conc A sale", null); return (ok, err); }),
				Op("edit", async ar => { var (ok, err, _) = await ar.EditSalesInvoiceAsync(company, einv!.ID, custId, DateTime.Today, new List<CrossBuy.BL.SalesLineInput> { Line(4) }, "ZZ-conc A edit", null); return (ok, err); }));
			decimal driftA1 = await BalMinusMoves();
			bool aNoExc = aRes.All(r => r.err == null || !r.err.Contains("Exception"));
			log.Add($"A sale‖edit: {string.Join(" | ", aRes.Select(r => $"{r.label} ok={r.ok} {r.ms}ms {(r.err ?? "")}"))} · balance−movements {driftA0}→{driftA1}");

			// ===== Case B: SALE ‖ RETURN on the same item =====
			decimal driftB0 = await BalMinusMoves();
			var bRes = await Task.WhenAll(
				Op("sale", async ar => { var (ok, err, _) = await ar.CreateSalesInvoiceAsync(company, custId, DateTime.Today, new List<CrossBuy.BL.SalesLineInput> { Line(1) }, "ZZ-conc B sale", null); return (ok, err); }),
				Op("return", async ar => { var (ok, err, _) = await ar.CreateSalesReturnAsync(company, custId, rinv!.ID, DateTime.Today, new List<CrossBuy.BL.SalesLineInput> { Line(1) }, "ZZ-conc B return", null); return (ok, err); }));
			decimal driftB1 = await BalMinusMoves();
			bool bNoExc = bRes.All(r => r.err == null || !r.err.Contains("Exception"));
			log.Add($"B sale‖return: {string.Join(" | ", bRes.Select(r => $"{r.label} ok={r.ok} {r.ms}ms {(r.err ?? "")}"))} · balance−movements {driftB0}→{driftB1}");

			bool pass = driftA1 == 0m && driftB1 == 0m && aNoExc && bNoExc;
			return Ok(new
			{
				pass,
				caseA_sale_edit = new { balanceMinusMovements = driftA1, consistent = driftA1 == 0m, noException = aNoExc, ops = aRes.Select(r => new { r.label, r.ok, r.err, r.ms }) },
				caseB_sale_return = new { balanceMinusMovements = driftB1, consistent = driftB1 == 0m, noException = bNoExc, ops = bRes.Select(r => new { r.label, r.ok, r.err, r.ms }) },
				loserWait = "the higher ms of each pair ≈ the wait on the UPDLOCK (loser serialized then succeeded); full timing → Phase د",
				note = "fixed ZZ entities; sales/edit/return are legitimate balanced transactions left in place (balance==movements, GL balanced). Reversal-based teardown formalized in item 6."
			});
		}

