		[HttpGet("hm1-close-batch-test")]
		public async Task<IActionResult> Hm1CloseBatchTest(string key, [FromServices] CrossBuy.BL.IPayableService ap, [FromServices] CrossBuy.BL.IJournalEntryService jes)
