		// GET /api/dev/hm2-3c0-proofs?key=seed123 — HM-2 3-ج-0 remaining numeric proofs: (هـ) return with NO original invoice (today rate, no FX);
		// vendor payment KWD @ a different rate (FX on 4902/5902, ap_sub=0). Rolled-back tx. ((د) partial is proven in hm2-cashier-return-fx-test.)
		[HttpGet("hm2-3c0-proofs")]
		public async Task<IActionResult> Hm23c0Proofs(string key, [FromServices] CrossBuy.BL.IReceivableService ar, [FromServices] CrossBuy.BL.IPayableService ap)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1;
			int ctrl = await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.Code == "1102").Select(a => a.ID).FirstOrDefaultAsync();
			int rev = await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.Code == "4101").Select(a => a.ID).FirstOrDefaultAsync();
			int apCtrl = await _db.Vendors.AsNoTracking().Select(v => v.ControlAccountId).FirstOrDefaultAsync();
			int cash = await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.Code == "110101").Select(a => a.ID).FirstOrDefaultAsync();
			int exp = await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.Code == "520101").Select(a => a.ID).FirstOrDefaultAsync();
			int g4902 = await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.Code == "4902").Select(a => a.ID).FirstOrDefaultAsync();
			int g5902 = await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.Code == "5902").Select(a => a.ID).FirstOrDefaultAsync();

			// (هـ) sales return with NO original invoice → today rate, no FX
			var cust = await _db.Customers.FirstOrDefaultAsync(c => c.CompanyID == company && c.Name == "ZZ-KWD-CUST3") ?? new CrossBuy.Models.Context.Accounting.Customer { CompanyID = company, Name = "ZZ-KWD-CUST3", ControlAccountId = ctrl, IsActive = true, CreatedAt = DateTime.UtcNow };
			if (cust.ID == 0) { _db.Customers.Add(cust); await _db.SaveChangesAsync(); }
			object eCase;
			{
				await using var tx = await CrossBuy.BL.ScopedTx.BeginOrJoinAsync(_db);
				var line = new List<CrossBuy.BL.SalesLineInput> { new CrossBuy.BL.SalesLineInput { ItemDescription = "ZZ", Qty = 3, UnitPrice = 0.755m, DiscountAmount = 0, TaxRate = 0, RevenueAccountId = rev, ItemId = null, WarehouseId = null } };
				decimal outBefore = await ar.CustomerOutstandingAsync(company, cust.ID);
				var (rok, rerr, ret) = await ar.CreateSalesReturnAsync(company, cust.ID, null, DateTime.Today, line, "no-orig", null, 5, 163m);   // null invoice → return-day rate
				if (!rok || ret == null) eCase = new { ok = rok, err = rerr };
				else { var jl = await _db.JournalEntryLines.AsNoTracking().Where(l => l.JournalEntryId == ret.JournalEntryId).ToListAsync(); bool anyFx = jl.Any(l => l.AccountId == g4902 || l.AccountId == g5902); eCase = new { ok = rok, err = rerr, exchangeRate = ret.ExchangeRate, grandBase = ret.GrandTotalBase, jeBalanced = jl.Sum(l => l.Debit) == jl.Sum(l => l.Credit), noFxLine = !anyFx, arDeltaBase = await ar.CustomerOutstandingAsync(company, cust.ID) - outBefore }; }
				await tx.RollbackAsync();
			}

			// vendor payment KWD @165 for a KWD purchase invoice @163 → FX
			var ven = await _db.Vendors.FirstOrDefaultAsync(v => v.CompanyID == company && v.Name == "ZZ-KWD-VEN") ?? new CrossBuy.Models.Context.Accounting.Vendor { CompanyID = company, Name = "ZZ-KWD-VEN", ControlAccountId = apCtrl, IsActive = true, CreatedAt = DateTime.UtcNow };
			if (ven.ID == 0) { _db.Vendors.Add(ven); await _db.SaveChangesAsync(); }
			object payCase;
			{
				await using var tx = await CrossBuy.BL.ScopedTx.BeginOrJoinAsync(_db);
				int vid = ven.ID;
				async Task<decimal> ApOut() => (await _db.PurchaseInvoices.AsNoTracking().Where(i => i.VendorId == vid && i.Status == "Posted").SumAsync(i => (decimal?)(i.GrandTotalBase ?? i.GrandTotal)) ?? 0m) - (await _db.Payments.AsNoTracking().Where(p => p.VendorId == vid && p.Status == "Posted").SumAsync(p => (decimal?)(p.AmountBase ?? p.Amount)) ?? 0m) - (await _db.PurchaseReturns.AsNoTracking().Where(r => r.VendorId == vid && r.Status == "Posted").SumAsync(r => (decimal?)(r.GrandTotalBase ?? r.GrandTotal)) ?? 0m);
				int cc = await _db.CostCenters.AsNoTracking().Where(x => x.CompanyID == company).OrderBy(x => x.ID).Select(x => (int?)x.ID).FirstOrDefaultAsync() ?? 0;
				var (piok, pierr, pi) = await ap.CreatePurchaseInvoiceAsync(company, ven.ID, DateTime.Today, new List<CrossBuy.BL.PurchaseLineInput> { new CrossBuy.BL.PurchaseLineInput { ItemDescription = "svc", Qty = 10, UnitPrice = 1.000m, DiscountAmount = 0, TaxRate = 0, ExpenseAccountId = exp, CostCenterId = cc, ItemId = null, WarehouseId = null } }, "kwd pi", null, 5, 163m);
				if (!piok || pi == null) payCase = new { piError = pierr };
				else {
				decimal apBefore = await ApOut();
				var (pyok, pyerr) = await ap.CreatePaymentAsync(company, ven.ID, DateTime.Today, pi.GrandTotal, "Cash", cash, "pay@165", null, 0m, 5, 165m);
				decimal apAfter = await ApOut();
				var payJe = await _db.JournalEntries.AsNoTracking().Where(e => e.SourceType == "Payment").OrderByDescending(e => e.ID).Select(e => e.ID).FirstOrDefaultAsync();
				var pjl = await _db.JournalEntryLines.AsNoTracking().Where(l => l.JournalEntryId == payJe).ToListAsync();
				payCase = new { invoiceGrandBase = pi.GrandTotalBase, apBefore, paymentOk = pyok, err = pyerr, apOutstandingAfter = apAfter, apNetsToZero = apAfter == 0m, apLineDr = pjl.Where(l => l.AccountId == apCtrl).Sum(l => l.Debit), fxGain4902 = pjl.Where(l => l.AccountId == g4902).Sum(l => l.Credit - l.Debit), fxLoss5902 = pjl.Where(l => l.AccountId == g5902).Sum(l => l.Debit - l.Credit), jeBalanced = pjl.Sum(l => l.Debit) == pjl.Sum(l => l.Credit) }; }
				await tx.RollbackAsync();
			}
			return Ok(new { note = "rolled-back", e_noOriginalInvoice = eCase, vendorPaymentKwdFx = payCase });
		}

		// GET /api/dev/hm2-cashier-return-fx-test?key=seed123 — HM-2 3-ج-0: the AUTHORIZED refund-FX path, exercised at a DIFFERENT rate.
		// Invoice @163, then cashier return today @165 (and @161, and a credit no-FX case). Rolled-back tx.
		[HttpGet("hm2-cashier-return-fx-test")]
		public async Task<IActionResult> Hm2CashierReturnFxTest(string key, [FromServices] CrossBuy.BL.IReceivableService ar)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1;
			int ctrl = await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.Code == "1102").Select(a => a.ID).FirstOrDefaultAsync();
			int rev = await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.Code == "4101").Select(a => a.ID).FirstOrDefaultAsync();
			int drawer = await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.Code == "110101").Select(a => a.ID).FirstOrDefaultAsync();
			int wh = await _db.Warehouses.AsNoTracking().Where(w => w.CompanyID == company).OrderBy(w => w.ID).Select(w => w.ID).FirstOrDefaultAsync();
			int uom = await _db.UnitsOfMeasure.AsNoTracking().Select(u => u.ID).FirstOrDefaultAsync();
			int cat = await _db.ItemCategories.AsNoTracking().Where(c => c.CompanyID == company && c.InventoryAccountId != null).Select(c => c.ID).FirstOrDefaultAsync();
			int f4902 = await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.Code == "4902").Select(a => a.ID).FirstOrDefaultAsync();
			int f5902 = await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.Code == "5902").Select(a => a.ID).FirstOrDefaultAsync();

			var br = await _db.Branches.FirstOrDefaultAsync(b => b.Name == "ZZ-CASHIER-BR" && b.CompanyID == company);
			if (br == null) { br = new CrossBuy.Models.Context.Admin.Branch { Name = "ZZ-CASHIER-BR", NameAr = "كاشير ZZ", Location = "t", CountryID = 32, CompanyID = company, PhoneNumber = "", Email = "", Description = "" }; _db.Branches.Add(br); await _db.SaveChangesAsync(); }
			var setting = await _db.BranchPosSettings.FirstOrDefaultAsync(s => s.BranchId == br.ID);
			if (setting == null) { setting = new CrossBuy.Models.Context.Pos.BranchPosSetting { BranchId = br.ID }; _db.BranchPosSettings.Add(setting); }
			setting.DefaultSalesWarehouseId = wh; setting.DefaultCurrencyId = 5; await _db.SaveChangesAsync();
			var term = await _db.PosTerminals.FirstOrDefaultAsync(t => t.BranchId == br.ID && t.Code == "ZZCASH-T");
			if (term == null) { term = new CrossBuy.Models.Context.Pos.PosTerminal { BranchId = br.ID, Code = "ZZCASH-T", Name = "cash", CashAccountId = drawer, ReceiptPrefix = "ZZC-", NextReceiptNo = 1, IsActive = true }; _db.PosTerminals.Add(term); await _db.SaveChangesAsync(); }
			var svc = await _db.Items.FirstOrDefaultAsync(i => i.CompanyID == company && i.ItemCode == "ZZ-CASH-SVC");
			if (svc == null) { var (iok, ierr, it) = await _itemSvc.CreateItemAsync(company, new CrossBuy.BL.ItemInput { ItemCode = "ZZ-CASH-SVC", Barcode = "ZZCASHSVC", Name = "خدمة", NameEn = "svc", ItemCategoryId = cat, ItemType = "Service", BaseUoMId = uom, SalesPrice = 1m, IsActive = true }, null); if (!iok) return BadRequest(new { message = "svc item: " + ierr }); svc = await _db.Items.FirstAsync(i => i.ID == it!.ID); }
			var cust = await _db.Customers.FirstOrDefaultAsync(c => c.CompanyID == company && c.Name == "ZZ-CASH-CUST");
			if (cust == null) { cust = new CrossBuy.Models.Context.Accounting.Customer { CompanyID = company, Name = "ZZ-CASH-CUST", ControlAccountId = ctrl, IsActive = true, CreatedAt = DateTime.UtcNow }; _db.Customers.Add(cust); await _db.SaveChangesAsync(); }

			async Task<decimal> Out() => await ar.CustomerOutstandingAsync(company, cust.ID);
			async Task<object> OneCase(string tag, decimal todayRateVal, decimal returnQty = 10m)
			{
				await using var tx = await CrossBuy.BL.ScopedTx.BeginOrJoinAsync(_db);
				// today's KWD rate (rolled back) — drives the refund's return-day rate
				await _db.Database.ExecuteSqlRawAsync("INSERT INTO ExchangeRates (CurrencyId, RateDate, Rate, RateType) VALUES (5, {0}, {1}, 'Sell')", DateTime.Today, todayRateVal);
				// invoice @163 (explicit) for a 10-KWD service line
				var line = new List<CrossBuy.BL.SalesLineInput> { new CrossBuy.BL.SalesLineInput { ItemDescription = "svc", Qty = 10, UnitPrice = 1.000m, DiscountAmount = 0, TaxRate = 0, RevenueAccountId = rev, ItemId = svc!.ID, WarehouseId = wh } };
				var (iok, ierr, inv) = await ar.CreateSalesInvoiceAsync(company, cust.ID, DateTime.Today, line, "cash inv", null, 5, 163m);
				if (!iok) { await tx.RollbackAsync(); return new { tag, error = "inv: " + ierr }; }
				var ord = new CrossBuy.Models.Context.Pos.PosOrder { CompanyId = company, BranchId = br.ID, TerminalId = term.ID, CustomerId = cust.ID, Status = "Paid", InvoiceId = inv!.ID, CurrencyId = 5, OrderType = "Takeaway", OpenedAt = DateTime.UtcNow };
				_db.PosOrders.Add(ord); await _db.SaveChangesAsync();
				var ol = new CrossBuy.Models.Context.Pos.PosOrderLine { OrderId = ord.ID, ItemId = svc.ID, ItemName = "svc", Qty = 10, UnitPrice = 1.000m, DiscountAmount = 0, TaxRate = 0, LineTotal = 10.000m, Sort = 1 };
				_db.PosOrderLines.Add(ol); await _db.SaveChangesAsync();
				// the ORIGINAL cash payment (@invoice rate 163) that settled the invoice to zero — a real Paid order has this
				await ar.CreateReceiptAsync(company, cust.ID, DateTime.Today, inv.GrandTotal, "Cash", drawer, "orig pay", null, 5, 163m);
				decimal outBefore = await Out();
				var (rok, rerr, retId) = await _posOrders.ReturnOrderLinesAsync(company, ord.ID, new List<CrossBuy.BL.SplitAllocation> { new CrossBuy.BL.SplitAllocation { LineId = ol.ID, Qty = returnQty } }, null);
				object res;
				if (!rok) res = new { tag, error = "return: " + rerr };
				else
				{
					decimal outAfter = await Out();
					var rr = await _db.Receipts.AsNoTracking().Where(r => r.CustomerId == cust.ID && r.Amount < 0).OrderByDescending(r => r.ID).FirstOrDefaultAsync();
					var refundJe = await _db.JournalEntries.AsNoTracking().Where(e => e.SourceType == "PosRefund").OrderByDescending(e => e.ID).Select(e => e.ID).FirstOrDefaultAsync();
					var jl = await _db.JournalEntryLines.AsNoTracking().Where(l => l.JournalEntryId == refundJe).ToListAsync();
					decimal fx4902 = jl.Where(l => l.AccountId == f4902).Sum(l => l.Credit - l.Debit);
					decimal fx5902 = jl.Where(l => l.AccountId == f5902).Sum(l => l.Debit - l.Credit);
					decimal arRefund = jl.Where(l => l.AccountId == ctrl).Sum(l => l.Debit);
					res = new { tag, todayRate = todayRateVal, arClosedAtInvoiceRate = arRefund, fxGain4902 = fx4902, fxLoss5902 = fx5902, refundReceiptRate = rr?.ExchangeRate, refundReceiptAmountBase = rr?.AmountBase, refundJeBalanced = jl.Sum(l => l.Debit) == jl.Sum(l => l.Credit), arNetsToZero = outAfter == 0m, outBefore, outAfter };
				}
				await tx.RollbackAsync();
				return res;
			}
			var results = new List<object> { await OneCase("a: return @165 (gain)", 165m), await OneCase("b: return @161 (loss)", 161m), await OneCase("d: PARTIAL return 5/10 @165", 165m, 5m) };
			return Ok(new { note = "each case rolled back; invoice @163, cashier return today at the shown rate", results });
		}

		// GET /api/dev/hm2-4-proofs?key=seed123 — HM-2 Batch 4: POS payment + shift currency-awareness on ZZ KWD (3dp) entities.
		//  (1) Z report + expected drawer cash carry the 3rd decimal (fils); Z total == Σ paid orders exactly (no 2dp loss); a
		//      counted == expected close yields variance 0 ⇒ NO variance JE.
		//  (2) a real drawer variance posts ONE balanced JE on 520111 with BOTH lines from a SINGLE conversion (Rf), VarianceJournalEntryId set.
		//  (3) multi-tender: the LARGEST tender absorbs the change so Σ receipts == grand; AR nets to 0; each receipt JE balanced.
		//  (4) split-by-item: Σ invoices == the order grand (residual on the LARGEST bill); AR nets to 0.
		// Every proof runs in its own rolled-back tx (zero persistence). Scaffolding (ZZ branch/terminal/item) is idempotent.
		[HttpGet("hm2-4-proofs")]
		public async Task<IActionResult> Hm24Proofs(string key, [FromServices] CrossBuy.BL.IReceivableService ar, [FromServices] CrossBuy.BL.ICurrencyRounding _rounding, [FromServices] CrossBuy.BL.ICurrencyService _currency)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1;
			int drawer = await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.Code == "110101").Select(a => a.ID).FirstOrDefaultAsync();
			int over511 = await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.Code == "520111").Select(a => a.ID).FirstOrDefaultAsync();
			int wh = await _db.Warehouses.AsNoTracking().Where(w => w.CompanyID == company).OrderBy(w => w.ID).Select(w => w.ID).FirstOrDefaultAsync();
			int uom = await _db.UnitsOfMeasure.AsNoTracking().Select(u => u.ID).FirstOrDefaultAsync();
			int cat = await _db.ItemCategories.AsNoTracking().Where(c => c.CompanyID == company && c.InventoryAccountId != null).Select(c => c.ID).FirstOrDefaultAsync();
			if (drawer == 0 || over511 == 0) return BadRequest(new { message = "need 110101 + 520111 (run SQL)" });

			// --- idempotent ZZ KWD scaffolding (persisted, reused across runs) ---
			var br = await _db.Branches.FirstOrDefaultAsync(b => b.Name == "ZZ-CASHIER-BR" && b.CompanyID == company);
			if (br == null) { br = new CrossBuy.Models.Context.Admin.Branch { Name = "ZZ-CASHIER-BR", NameAr = "كاشير ZZ", Location = "t", CountryID = 32, CompanyID = company, PhoneNumber = "", Email = "", Description = "" }; _db.Branches.Add(br); await _db.SaveChangesAsync(); }
			var setting = await _db.BranchPosSettings.FirstOrDefaultAsync(s => s.BranchId == br.ID);
			if (setting == null) { setting = new CrossBuy.Models.Context.Pos.BranchPosSetting { BranchId = br.ID }; _db.BranchPosSettings.Add(setting); }
			setting.DefaultSalesWarehouseId = wh; setting.DefaultCurrencyId = 5; setting.ServiceChargePct = 0m; await _db.SaveChangesAsync();
			var term = await _db.PosTerminals.FirstOrDefaultAsync(t => t.BranchId == br.ID && t.Code == "ZZCASH-T");
			if (term == null) { term = new CrossBuy.Models.Context.Pos.PosTerminal { BranchId = br.ID, Code = "ZZCASH-T", Name = "cash", CashAccountId = drawer, ReceiptPrefix = "ZZC-", NextReceiptNo = 1, IsActive = true }; _db.PosTerminals.Add(term); await _db.SaveChangesAsync(); }
			if (!await _db.BranchPaymentMethods.AnyAsync(p => p.BranchId == br.ID && p.PaymentMethod == "Card"))
			{ _db.BranchPaymentMethods.Add(new CrossBuy.Models.Context.Pos.BranchPaymentMethod { BranchId = br.ID, PaymentMethod = "Card", TargetAccountId = drawer, IsActive = true }); await _db.SaveChangesAsync(); }
			var item = await _db.Items.FirstOrDefaultAsync(i => i.CompanyID == company && i.ItemCode == "ZZ-CASH-KWD3");
			if (item == null) { var (iok, ierr, it) = await _itemSvc.CreateItemAsync(company, new CrossBuy.BL.ItemInput { ItemCode = "ZZ-CASH-KWD3", Barcode = "ZZCASHKWD3", Name = "بند 3 خانات", NameEn = "kwd3", ItemCategoryId = cat, ItemType = "Service", BaseUoMId = uom, SalesPrice = 0.755m, IsActive = true }, null); if (!iok) return BadRequest(new { message = "item: " + ierr }); item = await _db.Items.FirstAsync(i => i.ID == it!.ID); }

			// diagnostics: what currency/precision does the shift path resolve for this terminal?
			int ddpKwd = await _rounding.DecimalsAsync(company, 5);
			int ddpFunc = await _rounding.DecimalsAsync(company, null);
			int funcCur = await _currency.GetFunctionalCurrencyIdAsync(company, null);
			int? termBranch = await _db.PosTerminals.AsNoTracking().Where(t => t.ID == term.ID).Select(t => (int?)t.BranchId).FirstOrDefaultAsync();
			int? branchDefCur = termBranch == null ? null : await _db.BranchPosSettings.AsNoTracking().Where(s => s.BranchId == termBranch.Value).Select(s => s.DefaultCurrencyId).FirstOrDefaultAsync();
			var diag = new { ddpForKwd5 = ddpKwd, ddpFunctional = ddpFunc, functionalCurrency = funcCur, terminalBranch = termBranch, branchDefaultCurrency = branchDefCur };

			async Task<int> OrderLineId(int orderId) => await _db.PosOrderLines.AsNoTracking().Where(l => l.OrderId == orderId).OrderBy(l => l.Sort).Select(l => l.ID).FirstAsync();
			async Task<decimal> OrderGrand(int orderId) => await _db.PosOrders.AsNoTracking().Where(o => o.ID == orderId).Select(o => o.GrandTotal).FirstAsync();
			async Task<int> WalkInOf(int orderId) => await _db.PosOrders.AsNoTracking().Where(o => o.ID == orderId).Select(o => o.CustomerId ?? 0).FirstAsync();

			// ---------- Proof 1: Z report + expected cash at 3dp; systematic diff 0; variance 0 ⇒ no JE ----------
			async Task<object> Proof1()
			{
				await using var tx = await CrossBuy.BL.ScopedTx.BeginOrJoinAsync(_db);
				await _posSetup.OpenShiftAsync(term.ID, "Morning", null, 0m);
				var sh = await _posSetup.GetOpenShiftAsync(term.ID);
				var (_a, _ae, oa) = await _posOrders.CreateOrderAsync(company, br.ID, "Takeaway", null, null, term.ID, sh!.ID);
				await _posOrders.AddLineAsync(company, oa, item!.ID, 3);   // 3 × 0.755 = 2.265
				var (pa, paErr, _pi) = await _posOrders.PayAsync(company, oa, "Cash", null);
				var (_b, _be, ob) = await _posOrders.CreateOrderAsync(company, br.ID, "Takeaway", null, null, term.ID, sh.ID);
				await _posOrders.AddLineAsync(company, ob, item.ID, 2);    // 2 × 0.755 = 1.510
				await _posOrders.PayAsync(company, ob, "Cash", null);
				decimal sumOrders = await _db.PosOrders.AsNoTracking().Where(o => o.ShiftId == sh.ID && o.Status == "Paid").SumAsync(o => o.GrandTotal);
				var oaRow = await _db.PosOrders.AsNoTracking().Where(o => o.ID == oa).Select(o => new { o.SubTotal, o.TaxTotal, o.GrandTotal, o.CurrencyId }).FirstAsync();
				var z = await _posSetup.GetShiftZReportAsync(company, term.ID, sh.ID);
				decimal expected = await _posSetup.ExpectedCashAsync(company, sh);
				var (cok, cerr) = await _posSetup.CloseShiftAsync(company, term.ID, sh.ID, expected, null, DateTime.Today, null);   // counted == expected → variance 0
				var shAfter = await _db.PosShifts.AsNoTracking().FirstAsync(x => x.ID == sh.ID);
				var res = new
				{
					orderCurrencyId = oaRow.CurrencyId, orderASubTotal = oaRow.SubTotal, orderATaxTotal = oaRow.TaxTotal, orderAGrandTotal = oaRow.GrandTotal,
					payOrderA = pa ? "ok" : paErr, zGrandTotal = z!.GrandTotal, sumPaidOrders = sumOrders,
					systematicDiff = z.GrandTotal - sumOrders, zEqualsOrders = z.GrandTotal == sumOrders,
					expectedCash = expected, expectedEqualsCash = expected == sumOrders,
					closeOk = cok, closeErr = cerr, variance = shAfter.CashVariance, noVarianceJe = shAfter.VarianceJournalEntryId == null
				};
				await tx.RollbackAsync();
				return res;
			}

			// ---------- Proof 2: real drawer variance → ONE balanced JE on 520111, single conversion, VarianceJournalEntryId set ----------
			async Task<object> Proof2()
			{
				await using var tx = await CrossBuy.BL.ScopedTx.BeginOrJoinAsync(_db);
				await _posSetup.OpenShiftAsync(term.ID, "Morning", null, 0m);
				var sh = await _posSetup.GetOpenShiftAsync(term.ID);
				var (_o, _oe, oid) = await _posOrders.CreateOrderAsync(company, br.ID, "Takeaway", null, null, term.ID, sh!.ID);
				await _posOrders.AddLineAsync(company, oid, item!.ID, 3);
				await _posOrders.PayAsync(company, oid, "Cash", null);
				decimal expected = await _posSetup.ExpectedCashAsync(company, sh);
				decimal counted = expected + 0.005m;   // 5-fils overage (a 3rd-decimal variance a 2dp path would lose)
				var (cok, cerr) = await _posSetup.CloseShiftAsync(company, term.ID, sh.ID, counted, null, DateTime.Today, null);
				var shAfter = await _db.PosShifts.AsNoTracking().FirstAsync(x => x.ID == sh.ID);
				var je = await _db.JournalEntries.AsNoTracking().Where(e => e.SourceType == "PosShiftClose" && e.SourceId == sh.ID).OrderByDescending(e => e.ID).Select(e => (int?)e.ID).FirstOrDefaultAsync();
				var jl = je == null ? new List<CrossBuy.Models.Context.Accounting.JournalEntryLine>() : await _db.JournalEntryLines.AsNoTracking().Where(l => l.JournalEntryId == je).ToListAsync();
				decimal drawerDr = jl.Where(l => l.AccountId == drawer).Sum(l => l.Debit - l.Credit);
				decimal over511Cr = jl.Where(l => l.AccountId == over511).Sum(l => l.Credit - l.Debit);
				var res = new
				{
					closeOk = cok, closeErr = cerr, expectedCash = expected, countedFloat = counted,
					variance = shAfter.CashVariance, variance3dp = shAfter.CashVariance == 0.005m,
					varianceJeSet = shAfter.VarianceJournalEntryId != null,
					drawerDebitBase = drawerDr, over520111CreditBase = over511Cr,
					bothLinesEqual = drawerDr == over511Cr && drawerDr > 0,   // single conversion ⇒ identical magnitude
					jeBalanced = jl.Sum(l => l.Debit) == jl.Sum(l => l.Credit)
				};
				await tx.RollbackAsync();
				return res;
			}

			// ---------- Proof 3: multi-tender — largest tender absorbs change, Σ receipts == grand, AR nets to 0 ----------
			async Task<object> Proof3()
			{
				await using var tx = await CrossBuy.BL.ScopedTx.BeginOrJoinAsync(_db);
				var (_o, _oe, oid) = await _posOrders.CreateOrderAsync(company, br.ID, "Takeaway", null, null, term.ID, null);
				await _posOrders.AddLineAsync(company, oid, item!.ID, 3);   // grand 2.265
				decimal grand = await OrderGrand(oid);
				int walkIn = await WalkInOf(oid);
				decimal outBefore = await ar.CustomerOutstandingAsync(company, walkIn);
				// Cash 1.000 + Card = grand (Σ = grand + 1 > grand) → the LARGEST tender (Card) absorbs the change to grand − 1.000
				var tenders = new List<CrossBuy.BL.PosTenderInput> { new() { Method = "Cash", Amount = 1.000m }, new() { Method = "Card", Amount = grand } };
				var (pok, perr, invId) = await _posOrders.PayTendersAsync(company, oid, tenders, null);
				var pays = await _db.PosPayments.AsNoTracking().Where(p => p.OrderId == oid).ToListAsync();
				decimal outAfter = await ar.CustomerOutstandingAsync(company, walkIn);
				decimal cardAmt = pays.Where(p => p.PaymentMethod == "Card").Sum(p => p.Amount);
				var res = new
				{
					payOk = pok, payErr = perr, grand,
					cashReceipt = pays.Where(p => p.PaymentMethod == "Cash").Sum(p => p.Amount),
					cardReceipt = cardAmt, cardIsLargestAndAbsorbedChange = cardAmt == grand - 1.000m,
					sumReceipts = pays.Sum(p => p.Amount), receiptsEqualGrand = pays.Sum(p => p.Amount) == grand,
					arNetsToZero = outAfter == outBefore, outBefore, outAfter
				};
				await tx.RollbackAsync();
				return res;
			}

			// ---------- Proof 4: split-by-item — Σ invoices == order grand, AR nets to 0 ----------
			async Task<object> Proof4()
			{
				await using var tx = await CrossBuy.BL.ScopedTx.BeginOrJoinAsync(_db);
				var (_o, _oe, oid) = await _posOrders.CreateOrderAsync(company, br.ID, "Takeaway", null, null, term.ID, null);
				await _posOrders.AddLineAsync(company, oid, item!.ID, 3);   // 3 units → split 2 + 1
				decimal grand = await OrderGrand(oid);
				int lineId = await OrderLineId(oid);
				int walkIn = await WalkInOf(oid);
				decimal outBefore = await ar.CustomerOutstandingAsync(company, walkIn);
				var bills = new List<List<CrossBuy.BL.SplitAllocation>>
				{
					new() { new CrossBuy.BL.SplitAllocation { LineId = lineId, Qty = 2m } },
					new() { new CrossBuy.BL.SplitAllocation { LineId = lineId, Qty = 1m } },
				};
				var (pok, perr, invIds) = await _posOrders.PaySplitByItemAsync(company, oid, bills, "Cash", null);
				decimal sumInv = invIds == null || invIds.Count == 0 ? 0m : await _db.SalesInvoices.AsNoTracking().Where(i => invIds.Contains(i.ID)).SumAsync(i => i.GrandTotal);
				decimal outAfter = await ar.CustomerOutstandingAsync(company, walkIn);
				var res = new { payOk = pok, payErr = perr, grand, invoiceCount = invIds?.Count ?? 0, sumInvoices = sumInv, invoicesEqualGrand = sumInv == grand, arNetsToZero = outAfter == outBefore, outBefore, outAfter };
				await tx.RollbackAsync();
				return res;
			}

			// ---------- Proof 0: EF persistence precision — does a 3dp money value survive a DB round-trip? ----------
			async Task<object> Proof0()
			{
				await using var tx = await CrossBuy.BL.ScopedTx.BeginOrJoinAsync(_db);
				await _posSetup.OpenShiftAsync(term.ID, "Morning", null, 1.733m);   // OpeningFloat carries a 3rd decimal (fils)
				var sh = await _posSetup.GetOpenShiftAsync(term.ID);
				// force a fresh DB read (round-trip) via a new no-tracking query — EF materializes through the model's decimal precision
				decimal efRead = await _db.PosShifts.AsNoTracking().Where(x => x.ID == sh!.ID).Select(x => x.OpeningFloat).FirstAsync();
				// raw column value straight from SQL Server (bypassing EF), via EF's own raw-SQL channel (joins the ambient tx)
				var rawRows = await _db.Database.SqlQueryRaw<decimal>("SELECT OpeningFloat AS Value FROM PosShifts WHERE ID = {0}", sh!.ID).ToListAsync();
				decimal rawRead = rawRows.Count > 0 ? rawRows[0] : -1m;
				// an 8-decimal FX rate must ALSO survive (rate columns are decimal(19,8) and were raised past the (19,4) default)
				var er = new CrossBuy.Models.Context.Accounting.ExchangeRate { CurrencyId = 5, RateDate = DateTime.Today, Rate = 0.00612345m, RateType = "ZZ-D27" };
				_db.ExchangeRates.Add(er); await _db.SaveChangesAsync();
				decimal rateRead = await _db.ExchangeRates.AsNoTracking().Where(x => x.ID == er.ID).Select(x => x.Rate).FirstAsync();
				var res = new { wroteViaEf = 1.733m, efReadBack = efRead, rawSqlColumn = rawRead, filsSurvivedEfPersistence = efRead == 1.733m, columnItselfHoldsFils = rawRead == 1.733m,
					wroteRate = 0.00612345m, rateReadBack = rateRead, rate8dpSurvives = rateRead == 0.00612345m };
				await tx.RollbackAsync();
				return res;
			}

			var proof0 = await Proof0();
			var proof1 = await Proof1();
			var proof2 = await Proof2();
			var proof3 = await Proof3();
			var proof4 = await Proof4();
			return Ok(new
			{
				note = "HM-2 Batch 4 — KWD (3dp) POS payment/shift proofs; each proof rolled back (zero persistence)",
				diagnostics = diag,
				proof0_efPersistencePrecision = proof0,
				proof1_zReportAndVarianceZero = proof1,
				proof2_realVarianceJe = proof2,
				proof3_multiTenderLargestAbsorbs = proof3,
				proof4_splitByItem = proof4
			});
		}

		// GET /api/dev/hm2-precision-audit?key=seed123 — HM-2 Batch 5 item 1: for EVERY decimal property in the EF model, compare
		// what the HavePrecision(19,4) convention (+ rate/factor overrides) gave it against the ACTUAL DB column type. Flags:
		//  efScaleLtDb = EF scale < column scale ⇒ EF still TRUNCATES on save (the HM-D27 bug pattern — should be ZERO after 4.5);
		//  efScaleGtDb = EF scale > column scale ⇒ EF sends more decimals than the column holds (SQL rounds to the column — harmless).
		// Read-only. Also surveys existing FRACTIONAL quantities (weighed/partial units) as a Qty-truncation footprint check.
		[HttpGet("hm2-precision-audit")]
		public async Task<IActionResult> Hm2PrecisionAudit(string key)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			var db = await _db.Database.SqlQueryRaw<DecColRow>(
				"SELECT t.name AS TableName, c.name AS ColumnName, CAST(c.precision AS int) AS Prec, CAST(c.scale AS int) AS Scale " +
				"FROM sys.columns c JOIN sys.tables t ON t.object_id=c.object_id JOIN sys.types ty ON ty.user_type_id=c.user_type_id " +
				"WHERE ty.name IN ('decimal','numeric')").ToListAsync();
			var dbMap = new Dictionary<string, (int P, int S)>(StringComparer.OrdinalIgnoreCase);
			foreach (var r in db) dbMap[r.TableName + "." + r.ColumnName] = (r.Prec, r.Scale);

			var rows = new List<Dictionary<string, object?>>();
			foreach (var et in _db.Model.GetEntityTypes())
			{
				var table = et.GetTableName();
				if (table == null) continue;
				var soi = Microsoft.EntityFrameworkCore.Metadata.StoreObjectIdentifier.Table(table, et.GetSchema());
				foreach (var p in et.GetProperties())
				{
					if (p.ClrType != typeof(decimal) && p.ClrType != typeof(decimal?)) continue;
					var col = p.GetColumnName(soi) ?? p.Name;
					int? efP = p.GetPrecision(); int? efS = p.GetScale();
					bool inDb = dbMap.TryGetValue(table + "." + col, out var dbv);
					bool fullMatch = inDb && (efP ?? 0) == dbv.P && (efS ?? 0) == dbv.S;   // model type == DB column type EXACTLY
					bool scaleMatch = inDb && (efS ?? 0) == dbv.S;
					bool efScaleLtDb = inDb && (efS ?? 0) < dbv.S;   // EF truncates below the column ⇒ silent precision loss
					bool efScaleGtDb = inDb && (efS ?? 0) > dbv.S;   // column is authoritative ⇒ harmless
					rows.Add(new Dictionary<string, object?> {
						["table"] = table, ["column"] = col, ["prop"] = p.Name,
						["efPrec"] = efP, ["efScale"] = efS, ["dbPrec"] = inDb ? (int?)dbv.P : null, ["dbScale"] = inDb ? (int?)dbv.S : null,
						["inDb"] = inDb, ["fullMatch"] = fullMatch, ["scaleMatch"] = scaleMatch, ["efScaleLtDb"] = efScaleLtDb, ["efScaleGtDb"] = efScaleGtDb
					});
				}
			}
			bool RiskLt(Dictionary<string, object?> r) => (bool)r["efScaleLtDb"]!;
			bool RiskGt(Dictionary<string, object?> r) => (bool)r["efScaleGtDb"]!;
			// distinct (efScale -> dbScale) signatures for a compact overview
			var sigs = rows.Where(r => (bool)r["inDb"]!).GroupBy(r => $"ef{r["efScale"]}->db{r["dbScale"]}")
				.Select(g => new { signature = g.Key, count = g.Count(), sample = g.Take(6).Select(r => $"{r["table"]}.{r["column"]}").ToList() })
				.OrderByDescending(x => x.count).ToList();

			// FRACTIONAL-quantity footprint (read-only): before 4.5 EF (18,2) truncated Qty to 2dp on save
			var qty = new List<object>();
			foreach (var tc in new[] { ("StockMovements", "QtyBase"), ("PosOrderLines", "Qty"), ("SalesInvoiceLines", "Qty"), ("PurchaseInvoiceLines", "Qty"), ("GoodsReceiptLines", "Qty"), ("StockCountLines", "CountedQty") })
			{
				try
				{
					int frac = await _db.Database.SqlQueryRaw<int>($"SELECT COUNT(*) AS Value FROM {tc.Item1} WHERE {tc.Item2} <> ROUND({tc.Item2},0)").FirstAsync();
					int items = await _db.Database.SqlQueryRaw<int>($"SELECT COUNT(DISTINCT ItemId) AS Value FROM {tc.Item1} WHERE {tc.Item2} <> ROUND({tc.Item2},0)").FirstAsync();
					qty.Add(new { table = tc.Item1, col = tc.Item2, fractionalRows = frac, distinctItems = items });
				}
				catch (Exception ex) { qty.Add(new { table = tc.Item1, col = tc.Item2, error = ex.Message.Split('\n')[0] }); }
			}

			var divergent = rows.Where(r => !(bool)r["fullMatch"]!).ToList();
			return Ok(new
			{
				totalDecimalProps = rows.Count,
				fullyMatched = rows.Count(r => (bool)r["fullMatch"]!),
				divergenceCount = divergent.Count,   // model (P,S) != DB (P,S) — MUST be 0 after Batch 5 item 1
				efScaleLtDbCount = rows.Count(RiskLt),   // EF scale < DB scale ⇒ still truncating (MUST be 0)
				efScaleGtDbCount = rows.Count(RiskGt),   // EF scale > DB scale ⇒ SQL rounds to column
				notInDb = rows.Count(r => !(bool)r["inDb"]!),
				scaleSignatures = sigs,
				divergences = divergent,
				fractionalQtyFootprint = qty
			});
		}

		// GET /api/dev/hm2-kwd-return-test?key=seed123 — HM-2 Batch 3-ج-0: a KWD sales return of a KWD invoice must reverse AR at the
		// INVOICE rate ⇒ GrandTotalBase (at invoice rate) == the 1102 JE line, fils preserved, JE balanced, ar_sub nets to 0. Rolled-back tx.
		[HttpGet("hm2-kwd-return-test")]
		public async Task<IActionResult> Hm2KwdReturnTest(string key, [FromServices] CrossBuy.BL.IReceivableService ar)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1;
			int ctrl = await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.Code == "1102").Select(a => a.ID).FirstOrDefaultAsync();
			int rev = await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.Code == "4101").Select(a => a.ID).FirstOrDefaultAsync();
			if (ctrl == 0 || rev == 0) return BadRequest(new { message = "need 1102/4101" });
			var cust = await _db.Customers.FirstOrDefaultAsync(c => c.CompanyID == company && c.Name == "ZZ-KWD-CUST3");
			if (cust == null) { cust = new CrossBuy.Models.Context.Accounting.Customer { CompanyID = company, Name = "ZZ-KWD-CUST3", ControlAccountId = ctrl, IsActive = true, CreatedAt = DateTime.UtcNow }; _db.Customers.Add(cust); await _db.SaveChangesAsync(); }
			async Task<decimal> Out() => await ar.CustomerOutstandingAsync(company, cust.ID);
			await using var tx = await CrossBuy.BL.ScopedTx.BeginOrJoinAsync(_db);
			var line = new List<CrossBuy.BL.SalesLineInput> { new CrossBuy.BL.SalesLineInput { ItemDescription = "ZZ KWD", Qty = 3, UnitPrice = 0.755m, DiscountAmount = 0, TaxRate = 0, RevenueAccountId = rev, ItemId = null, WarehouseId = null } };
			var (iok, ierr, inv) = await ar.CreateSalesInvoiceAsync(company, cust.ID, DateTime.Today, line, "ZZ inv", null, 5);
			decimal outAfterInv = await Out();
			var (rok, rerr, ret) = await ar.CreateSalesReturnAsync(company, cust.ID, inv!.ID, DateTime.Today, line, "ZZ ret", null, 5);   // full return, settle at invoice rate
			decimal outAfterRet = await Out();
			var jl = await _db.JournalEntryLines.AsNoTracking().Where(l => l.JournalEntryId == ret!.JournalEntryId).ToListAsync();
			decimal arLine = jl.Where(l => l.AccountId == ctrl).Sum(l => l.Credit);
				var retRow = await _db.SalesReturns.AsNoTracking().Where(x => x.ID == ret!.ID).Select(x => new { x.GrandTotal, x.GrandTotalBase, x.ExchangeRate }).FirstAsync();   // HM-2 rule: fresh persisted read
				var invR = await _db.SalesInvoices.AsNoTracking().Where(x => x.ID == inv.ID).Select(x => (decimal?)x.ExchangeRate).FirstAsync();
			return Ok(new
			{
				note = "rolled-back tx",
				returnDocGrand = retRow.GrandTotal, filsPreserved = retRow.GrandTotal == 2.265m,
				returnGrandBase = retRow.GrandTotalBase, returnExchangeRate = retRow.ExchangeRate, invoiceRate = invR,
				settledAtInvoiceRate = retRow.ExchangeRate == invR, columnEqualsJeLine = retRow.GrandTotalBase == arLine,
				jeBalanced = jl.Sum(l => l.Debit) == jl.Sum(l => l.Credit),
				outstandingAfterInvoice = outAfterInv, outstandingAfterFullReturn = outAfterRet, arNetsToZero = outAfterRet == 0m,
			});
			await tx.RollbackAsync();
		}

		// GET /api/dev/hm2-kwd-receipt-test?key=seed123 — HM-2 Batch 3-ب: (1) collect a KWD invoice at a DIFFERENT rate ⇒ AR base settles
		// to 0, realized FX on 4902/5902, ar_sub=0; (2) three partial collections ⇒ outstanding base 0, no penny hung. Rolled-back tx.
		[HttpGet("hm2-kwd-receipt-test")]
		public async Task<IActionResult> Hm2KwdReceiptTest(string key, [FromServices] CrossBuy.BL.IReceivableService ar)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1;
			int ctrl = await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.Code == "1102").Select(a => a.ID).FirstOrDefaultAsync();
			int rev = await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.Code == "4101").Select(a => a.ID).FirstOrDefaultAsync();
			int cash = await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.Code == "110101").Select(a => a.ID).FirstOrDefaultAsync();
			int g4902 = await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.Code == "4902").Select(a => a.ID).FirstOrDefaultAsync();
			if (ctrl == 0 || rev == 0 || cash == 0) return BadRequest(new { message = "need 1102/4101/110101" });
			var cust = await _db.Customers.FirstOrDefaultAsync(c => c.CompanyID == company && c.Name == "ZZ-KWD-CUST2");
			if (cust == null) { cust = new CrossBuy.Models.Context.Accounting.Customer { CompanyID = company, Name = "ZZ-KWD-CUST2", ControlAccountId = ctrl, IsActive = true, CreatedAt = DateTime.UtcNow }; _db.Customers.Add(cust); await _db.SaveChangesAsync(); }
			async Task<decimal> Outstanding() => await ar.CustomerOutstandingAsync(company, cust.ID);

			await using var tx = await CrossBuy.BL.ScopedTx.BeginOrJoinAsync(_db);
			// (1) FX: invoice 10 KWD @163 (default), collect fully @165 (explicit) ⇒ FX gain
			var (iok, ierr, inv) = await ar.CreateSalesInvoiceAsync(company, cust.ID, DateTime.Today, new List<CrossBuy.BL.SalesLineInput> {
				new CrossBuy.BL.SalesLineInput { ItemDescription = "ZZ KWD", Qty = 10, UnitPrice = 1.000m, DiscountAmount = 0, TaxRate = 0, RevenueAccountId = rev, ItemId = null, WarehouseId = null } }, "ZZ", null, 5);
			decimal outAfterInv = await Outstanding();
			var (r1ok, r1err) = await ar.CreateReceiptAsync(company, cust.ID, DateTime.Today, inv!.GrandTotal, "Cash", cash, "full @165", null, 5, 165m);
			decimal outAfterPay = await Outstanding();
			var recJe = await _db.Receipts.AsNoTracking().Where(r => r.CustomerId == cust.ID).OrderByDescending(r => r.ID).Select(r => r.JournalEntryId).FirstOrDefaultAsync();
			var jl = await _db.JournalEntryLines.AsNoTracking().Where(l => l.JournalEntryId == recJe).ToListAsync();
			var fxLine = jl.Where(l => l.AccountId == g4902).Sum(l => l.Credit - l.Debit);
			bool jeBal = jl.Sum(l => l.Debit) == jl.Sum(l => l.Credit);
			var invRow = await _db.SalesInvoices.AsNoTracking().Where(x => x.ID == inv.ID).Select(x => new { x.GrandTotalBase, x.ExchangeRate }).FirstAsync();   // HM-2 rule: persisted value via fresh read
			var fx = new { invoiceGrandBase = invRow.GrandTotalBase, invRate = invRow.ExchangeRate, outAfterInvoice = outAfterInv, receiptOk = r1ok, receiptErr = r1err, outstandingBaseAfterFullPay = outAfterPay, settledToZero = outAfterPay == 0m, realizedFxOn4902 = fxLine, receiptJeBalanced = jeBal };

			// (2) three partial collections of a fresh KWD invoice priced to force fractions
			var (i2ok, _, inv2) = await ar.CreateSalesInvoiceAsync(company, cust.ID, DateTime.Today, new List<CrossBuy.BL.SalesLineInput> {
				new CrossBuy.BL.SalesLineInput { ItemDescription = "ZZ KWD2", Qty = 1, UnitPrice = 10.000m, DiscountAmount = 0, TaxRate = 0, RevenueAccountId = rev, ItemId = null, WarehouseId = null } }, "ZZ2", null, 5);
			decimal before2 = await Outstanding();
			var steps = new List<object>();
			foreach (var part in new[] { 3.333m, 3.333m, 3.334m })   // Σ = 10.000
			{ var (pok, perr) = await ar.CreateReceiptAsync(company, cust.ID, DateTime.Today, part, "Cash", cash, "partial", null, 5, 163m); steps.Add(new { part, ok = pok, err = perr, outstandingBase = await Outstanding() }); }
			var partial = new { invoice2GrandBase = inv2!.GrandTotalBase, outstandingBaseBefore = before2, steps, outstandingBaseAfterAll = await Outstanding(), settledToZero = await Outstanding() == 0m };

			await tx.RollbackAsync();
			return Ok(new { note = "rolled-back tx (zero persistence)", fxCollection = fx, partialCollection = partial });
		}

		// GET /api/dev/hm2-kwd-invoice-test?key=seed123 — HM-2 Batch 3-أ: a KWD sales invoice (3-decimal price) must preserve fils in the
		// document, store GrandTotalBase == the 1102 JE line (single-source constraint), and post a balanced JE. Rolled-back tx (zero persistence).
		[HttpGet("hm2-kwd-invoice-test")]
		public async Task<IActionResult> Hm2KwdInvoiceTest(string key, [FromServices] CrossBuy.BL.IReceivableService ar)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1;
			int ctrl = await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.Code == "1102").Select(a => a.ID).FirstOrDefaultAsync();
			int rev = await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.Code == "4101").Select(a => a.ID).FirstOrDefaultAsync();
			if (ctrl == 0 || rev == 0) return BadRequest(new { message = "need 1102/4101" });
			var cust = await _db.Customers.FirstOrDefaultAsync(c => c.CompanyID == company && c.Name == "ZZ-KWD-CUST");
			if (cust == null) { cust = new CrossBuy.Models.Context.Accounting.Customer { CompanyID = company, Name = "ZZ-KWD-CUST", ControlAccountId = ctrl, IsActive = true, CreatedAt = DateTime.UtcNow }; _db.Customers.Add(cust); await _db.SaveChangesAsync(); }
			long loads0 = CrossBuy.BL.JournalEntryService.RoundingDiffLoads;
			await using var tx = await CrossBuy.BL.ScopedTx.BeginOrJoinAsync(_db);
			// KWD (currencyId 5) line priced 0.755 — a 3rd decimal (fils) that 2dp rounding would destroy (→0.76).
			var (ok, err, inv) = await ar.CreateSalesInvoiceAsync(company, cust.ID, DateTime.Today, new List<CrossBuy.BL.SalesLineInput> {
				new CrossBuy.BL.SalesLineInput { ItemDescription = "ZZ KWD 3dp", Qty = 3, UnitPrice = 0.755m, DiscountAmount = 0, TaxRate = 0, RevenueAccountId = rev, ItemId = null, WarehouseId = null } }, "ZZ KWD", null, 5);
			object result;
			if (ok && inv != null)
			{
				var jl = await _db.JournalEntryLines.AsNoTracking().Where(l => l.JournalEntryId == inv.JournalEntryId).ToListAsync();
				decimal arLine = jl.Where(l => l.AccountId == ctrl).Sum(l => l.Debit);
				decimal jd = jl.Sum(l => l.Debit), jc = jl.Sum(l => l.Credit);
				// HM-2 rule: prove PERSISTED values by reading a FRESH row (AsNoTracking), not the tracked entity (which holds the in-memory computed value).
				var row = await _db.SalesInvoices.AsNoTracking().Where(x => x.ID == inv.ID).Select(x => new { x.GrandTotal, x.GrandTotalBase, x.ExchangeRate }).FirstAsync();
				result = new
				{
					posted = true,
					documentCurrency = "KWD", documentGrandTotal = row.GrandTotal, filsPreserved = row.GrandTotal == 2.265m,   // 3 × 0.755 = 2.265 (would be 2.27 or 2.26 at 2dp)
					grandTotalBase = row.GrandTotalBase, arJeLine1102 = arLine, columnEqualsJeLine = row.GrandTotalBase == arLine,
					jeBalanced = jd == jc, exchangeRate = row.ExchangeRate, roundingDiffLoaded = CrossBuy.BL.JournalEntryService.RoundingDiffLoads - loads0
				};
			}
			else result = new { posted = false, error = err };
			await tx.RollbackAsync();
			return Ok(new { note = "KWD invoice inside a rolled-back tx (zero persistence)", result });
		}

		// GET /api/dev/hm2-rounding-test?key=seed123 — HM-2 Batch 1: proves the centralized rounding-remainder rule in JournalEntryService
		// (load on eligible P&L / reject caller imbalance / reject when no eligible line). Each JE posts inside a rolled-back tx (zero persistence).
		[HttpGet("hm2-rounding-test")]
		public async Task<IActionResult> Hm2RoundingTest(string key, [FromServices] CrossBuy.BL.IJournalEntryService jes, [FromServices] CrossBuy.BL.ICurrencyRounding rounding)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1; var log = new List<object>();
			// البند ١: DecimalsAsync throws (not silent 2) for an undefined currency; null → functional explicitly.
			object decimalsProbe;
			try { int dpBogus = await rounding.DecimalsAsync(company, 999999); decimalsProbe = new { undefinedCurrency = "DID NOT THROW (returned " + dpBogus + ")" }; }
			catch (InvalidOperationException ex) { decimalsProbe = new { undefinedCurrency = "threw (correct)", message = ex.Message, functionalKwd = await rounding.DecimalsAsync(company, 5), functionalEgpViaNull = await rounding.DecimalsAsync(company, null) }; }
			async Task<int> Acc(string code) => await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.Code == code).Select(a => a.ID).FirstOrDefaultAsync();
			int rev = await Acc("4101"), exp = await Acc("520101"), ar = await Acc("1102"), ap = await Acc("2101");
			if (rev == 0 || exp == 0 || ar == 0 || ap == 0) { exp = exp == 0 ? await Acc("520109") : exp; if (rev == 0 || exp == 0 || ar == 0 || ap == 0) return BadRequest(new { message = "need accounts 4101/520101/1102/2101" }); }
			int cc = await _db.CostCenters.AsNoTracking().Where(x => x.CompanyID == company).OrderBy(x => x.ID).Select(x => x.ID).FirstOrDefaultAsync();

			async Task<object> TryJe(string tag, List<CrossBuy.BL.JournalLineInput> lines)
			{
				long before = CrossBuy.BL.JournalEntryService.RoundingDiffLoads;
				await using var tx = await CrossBuy.BL.ScopedTx.BeginOrJoinAsync(_db);
				var (ok, err, entry) = await jes.CreateAndPostNoTxAsync(new CrossBuy.BL.JournalEntryInput { CompanyID = company, EntryDate = DateTime.Today, JournalType = "Manual", SourceType = "HM2Test", Description = tag, Lines = lines }, null);
				object res;
				if (ok && entry != null)
				{
					decimal sd = entry.Lines.Sum(l => l.Debit), sc = entry.Lines.Sum(l => l.Credit);
					res = new { tag, posted = true, balanced = sd == sc, totalDr = sd, totalCr = sc, loadedThisJe = CrossBuy.BL.JournalEntryService.RoundingDiffLoads - before, lines = entry.Lines.OrderBy(l => l.LineNo).Select(l => new { l.AccountId, l.Debit, l.Credit }) };
				}
				else res = new { tag, posted = false, rejectedWith = err };
				await tx.RollbackAsync();
				return res;
			}

			CrossBuy.BL.JournalLineInput D(int a, decimal v) => new() { AccountId = a, Debit = v, Credit = 0, CostCenterId = cc };
			CrossBuy.BL.JournalLineInput C(int a, decimal v) => new() { AccountId = a, Debit = 0, Credit = v, CostCenterId = cc };

			// (1) rounding remainder — raw balances (100.004+50.004 = 150.008), 2dp rounding makes debit 150.00 vs credit 150.01 ⇒ −0.01 loaded on the largest eligible P&L line
			log.Add(await TryJe("remainder-loaded", new() { D(exp, 100.004m), D(exp, 50.004m), C(rev, 150.008m) }));
			// (2) opposite direction (credit side over-rounds ⇒ +0.01 loaded)
			log.Add(await TryJe("remainder-loaded-other-dir", new() { C(rev, 100.004m), C(rev, 50.004m), D(exp, 150.008m) }));
			// (3) CALLER imbalance (raw off by 1.00) ⇒ rejected, never swallowed
			log.Add(await TryJe("caller-imbalance-rejected", new() { D(exp, 100.00m), C(rev, 99.00m) }));
			// (4) rounding remainder but NO eligible P&L line (all balance-sheet AR/AP) ⇒ rejected
			log.Add(await TryJe("no-eligible-line-rejected", new() { D(ar, 100.004m), D(ar, 50.004m), C(ap, 150.008m) }));
			return Ok(new { note = "each JE posted inside a rolled-back tx (zero persistence)", decimalsProbe, totalLoadsSinceBoot = CrossBuy.BL.JournalEntryService.RoundingDiffLoads, results = log });
		}

		// GET /api/dev/hm1-double-post-test?key=seed123 — (HM-D16 د) does GRN receipt + purchase invoice on the SAME goods
		// double-debit inventory with no guard? On ZZ entities; fully reversed via services afterward.
		[HttpGet("hm1-double-post-test")]
		public async Task<IActionResult> Hm1DoublePostTest(string key, [FromServices] CrossBuy.BL.IPayableService ap, [FromServices] CrossBuy.BL.IProcurementService proc, [FromServices] CrossBuy.BL.IJournalEntryService jes)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1;
			var cat = await _db.ItemCategories.AsNoTracking().FirstOrDefaultAsync(c => c.CompanyID == company && c.InventoryAccountId != null);
			int baseUom = await _db.UnitsOfMeasure.AsNoTracking().Where(u => u.CompanyID == company).Select(u => u.ID).FirstOrDefaultAsync();
			int wh = await _db.Warehouses.AsNoTracking().Where(w => w.CompanyID == company).OrderBy(w => w.ID).Select(w => w.ID).FirstOrDefaultAsync();
			int invAcc = cat!.InventoryAccountId!.Value;
			int grniAcc = await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.Code == "210203").Select(a => a.ID).FirstAsync();
			var ven = await _db.Vendors.FirstOrDefaultAsync(v => v.CompanyID == company && v.Name == "ZZ-STEP0-VEN");
			var itm = await _db.Items.FirstOrDefaultAsync(i => i.CompanyID == company && i.ItemCode == "ZZ-STEP0-ITM");
			if (ven == null || itm == null) return BadRequest(new { message = "run hm1-step0-purchase-test first (needs ZZ-STEP0 vendor+item)" });
			int itemId = itm.ID;

			async Task<decimal> GlNet(int acc) => await _db.JournalEntryLines.AsNoTracking().Where(l => l.AccountId == acc).SumAsync(l => (decimal?)(l.Debit - l.Credit)) ?? 0m;
			async Task<decimal> Bal() { var (q, _, _) = await _stock.GetBalanceAsync(company, itemId, wh); return q; }

			decimal bal0 = await Bal(), inv0 = await GlNet(invAcc), grni0 = await GlNet(grniAcc);
			// (1) RECEIVE 4 via GRN
			var (grOk, grErr, gr) = await proc.CreateReceiptAsync(company, ven.ID, wh, null, DateTime.UtcNow, "ZZ dbl grn", new List<CrossBuy.BL.ReceiptLineInput> { new CrossBuy.BL.ReceiptLineInput { ItemId = itemId, Qty = 4, UoMId = baseUom, UnitCost = 20m } }, null);
			decimal balAfterGrn = await Bal();
			int grJe = await _db.StockMovements.AsNoTracking().Where(m => m.SourceType == "Receipt" && m.SourceId == gr!.ID && m.ItemId == itemId).Select(m => m.JournalEntryId ?? 0).FirstOrDefaultAsync();
			// (2) INVOICE the SAME 4 (no GRN reference)
			var (piOk, piErr, pi) = await ap.CreatePurchaseInvoiceAsync(company, ven.ID, DateTime.UtcNow, new List<CrossBuy.BL.PurchaseLineInput> { new CrossBuy.BL.PurchaseLineInput { ItemDescription = "ZZ dbl", Qty = 4, UnitPrice = 20m, TaxRate = 0, ExpenseAccountId = invAcc, ItemId = itemId, WarehouseId = wh } }, "ZZ dbl inv", null);
			decimal bal1 = await Bal(), inv1 = await GlNet(invAcc), grni1 = await GlNet(grniAcc);

			var result = new
			{
				intendedReceiveQty = 4,
				stock = new { before = bal0, afterGRN = balAfterGrn, afterInvoice = bal1, totalDelta = bal1 - bal0, doubled = (bal1 - bal0) == 8m },
				inventoryGL = new { deltaDebit = inv1 - inv0, doubled = (inv1 - inv0) == 160m },
				grni = new { delta = grni1 - grni0, leftOpen = (grni1 - grni0) != 0m, note = "receipt credits GRNI −80; invoice does NOT clear it" },
				anyPreventionOrWarning = (!grOk || !piOk) ? $"grn:{grErr} inv:{piErr}" : "NONE — both posted with no block/warning",
				verdict = ((bal1 - bal0) == 8m && (inv1 - inv0) == 160m) ? "DOUBLE-POSTING CONFIRMED: stock +8 and inventory GL +160 for 4 units received once" : "no doubling"
			};

			// ===== full reversal via services =====
			var rev = new List<object>();
			if (piOk && pi?.JournalEntryId != null)
			{
				var rok = (await jes.ReverseAsync(pi.JournalEntryId.Value, null, "HM-D16 double-post test teardown")).ok;
				// HM-D58-net: after reversing the invoice's JE, set the DOCUMENT status to match (no IPayableService cancel
				// path exists → direct status update, no delete, no touching the JE) so the AP subledger stops counting it —
				// else it becomes a Posted-doc/Reversed-JE orphan that drifts ap_sub (caught now by doc_je_status_mismatch).
				if (rok) { var piRow = await _db.PurchaseInvoices.FirstOrDefaultAsync(z => z.ID == pi.ID); if (piRow != null && piRow.Status == "Posted") { piRow.Status = "Cancelled"; await _db.SaveChangesAsync(); } }
				rev.Add(new { pi = pi.InvoiceNo, r = rok, statusSet = "Cancelled" });
			}
			if (grOk && grJe != 0) rev.Add(new { grn = gr!.ReceiptNo, r = (await jes.ReverseAsync(grJe, null, "HM-D16 double-post test teardown")).ok });
			var q = await Bal();
			if (q != 0) await _stock.PostMovementAsync(company, new CrossBuy.BL.MovementRequest { ItemId = itemId, WarehouseId = wh, Direction = (short)(q > 0 ? -1 : 1), Qty = Math.Abs(q), SourceType = "ZZ-STEP0-Teardown", PostToGl = false, Notes = "reverse double-post test" }, null);
			decimal balFinal = await Bal();
			return Ok(new { result, teardown = new { reversals = rev, balanceAfter = balFinal } });
		}

		// GET /api/dev/hm1-step0-teardown?key=seed123 — (أ) reverse the step-zero footprint VIA SERVICES (ReverseAsync + a reversing
		// movement), never delete. ZZ-STEP0 vendor/item stay as reusable scaffolding. Idempotent (skips already-reversed JEs).
		[HttpGet("hm1-step0-teardown")]
		public async Task<IActionResult> Hm1Step0Teardown(string key, [FromServices] CrossBuy.BL.IJournalEntryService jes)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1; var log = new List<object>();
			int itemId = await _db.Items.Where(i => i.CompanyID == company && i.ItemCode == "ZZ-STEP0-ITM").Select(i => i.ID).FirstOrDefaultAsync();
			int wh = await _db.Warehouses.AsNoTracking().Where(w => w.CompanyID == company).OrderBy(w => w.ID).Select(w => w.ID).FirstOrDefaultAsync();
			if (itemId == 0) return BadRequest(new { message = "ZZ-STEP0-ITM not found (run step0 first)" });
			// reverse the three JEs (invoice 8445 / GRN 8446 / return 8447) via services
			foreach (var je in new[] { 8445, 8446, 8447 })
			{
				var (rok, rerr, rid) = await jes.ReverseAsync(je, null, "HM-D14 step-zero teardown (reverse via services)");
				log.Add(new { je, reversed = rok, reversalId = rid, error = rerr });
			}
			// zero the ZZ item's stock via a reversing movement (PostToGl=false — GL already handled by the reversals)
			var (q, _, _) = await _stock.GetBalanceAsync(company, itemId, wh);
			object? mv = null;
			if (q != 0)
			{
				var (sok, serr, _) = await _stock.PostMovementAsync(company, new CrossBuy.BL.MovementRequest { ItemId = itemId, WarehouseId = wh, Direction = (short)(q > 0 ? -1 : 1), Qty = Math.Abs(q), SourceType = "ZZ-STEP0-Teardown", PostToGl = false, Notes = "reverse step-zero stock" }, null);
				mv = new { posted = sok, error = serr, zeroedQty = q };
			}
			var (qAfter, vAfter, _2) = await _stock.GetBalanceAsync(company, itemId, wh);
			return Ok(new { note = "step-zero effect reversed via services; ZZ-STEP0 entities kept", reversals = log, stockZeroing = mv, balanceAfter = new { qty = qAfter, value = vAfter } });
		}

		// GET /api/dev/hm1-guard-purchase-test?key=seed123 — (د⚠️) PROVES inv-resync-item's three-way guard MISJUDGES any item with
		// purchase history: the guard reads per-item GL only from movement-linked JEs, but a purchase-invoice movement is PostToGl=false
		// (JournalEntryId=NULL), so the purchase inventory debit is invisible to it ⇒ glVal≠movementsVal ⇒ it refuses a legitimate resync
		// as "movements suspect". Reproduced in ONE rolled-back tx (zero persistence): purchase-style IN (no JE link) → raw balance bump → resync.
		[HttpGet("hm1-guard-purchase-test")]
		public async Task<IActionResult> Hm1GuardPurchaseTest(string key)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1;
			var cat = await _db.ItemCategories.AsNoTracking().FirstOrDefaultAsync(c => c.CompanyID == company && c.InventoryAccountId != null);
			int baseUom = await _db.UnitsOfMeasure.AsNoTracking().Where(u => u.CompanyID == company).Select(u => u.ID).FirstOrDefaultAsync();
			int wh = await _db.Warehouses.AsNoTracking().Where(w => w.CompanyID == company).OrderBy(w => w.ID).Select(w => w.ID).FirstOrDefaultAsync();
			if (cat == null || baseUom == 0 || wh == 0) return BadRequest(new { message = "need category/uom/warehouse" });
			var itm = await _db.Items.FirstOrDefaultAsync(i => i.CompanyID == company && i.ItemCode == "ZZ-GUARDPUR-ITM");
			if (itm == null) { var (iok, _, it2) = await _itemSvc.CreateItemAsync(company, new CrossBuy.BL.ItemInput { ItemCode = "ZZ-GUARDPUR-ITM", Barcode = "ZZGUARDPUR", Name = "حارس شراء", NameEn = "guard purchase", ItemCategoryId = cat.ID, ItemType = CrossBuy.Models.Context.Inventory.ItemTypes.Stockable, BaseUoMId = baseUom, SalesPrice = 50m, OpeningCost = 20m, IsActive = true }, null); if (!iok) return BadRequest(new { message = "ZZ item create failed" }); itm = it2; }
			int itemId = itm!.ID;

			bool refused; object? body; decimal glSeen = 0, movSeen = 0;
			await using (var tx = await CrossBuy.BL.ScopedTx.BeginOrJoinAsync(_db))
			{
				// purchase-style receipt: movement WITHOUT a linked JE (PostToGl=false), exactly like PayableService:194
				await _stock.PostMovementAsync(company, new CrossBuy.BL.MovementRequest { ItemId = itemId, WarehouseId = wh, Direction = 1, Qty = 5, UnitCostInBase = 20m, SourceType = "PurchaseInvoice", PostToGl = false, Notes = "guard-test purchase" }, null);
				// a real balance drift (a lost-update-style +1) so resync is actually needed and reaches the guard
				await _db.Database.ExecuteSqlRawAsync("UPDATE StockBalances SET QtyOnHand = QtyOnHand + 1, TotalValue = TotalValue + 20 WHERE CompanyID = {0} AND ItemId = {1} AND WarehouseId = {2}", company, itemId, wh);
				var result = await InvResyncItem("seed123", itemId, wh, 1, "guard-purchase-test (movements are truth; SHOULD proceed, but guard will wrongly refuse)", callerBypassDisable: true);
				refused = result is BadRequestObjectResult;
				body = (result as ObjectResult)?.Value;
				movSeen = 100m;   // 5 × 20 (movements value)
				await tx.RollbackAsync();   // zero persistence
			}
			return Ok(new
			{
				verdict = refused ? "GUARD IS BROKEN for purchase-history items — it REFUSED a legitimate resync (movements are truth)" : "guard proceeded",
				refused, guardResponse = body,
				explanation = "purchase movement is PostToGl=false ⇒ JournalEntryId=NULL ⇒ guard's per-item glVal (movement-linked JEs only) misses the invoice inventory debit ⇒ glVal(0) ≠ movementsVal(100) ⇒ refuses as 'movements suspect'. A non-purchase item would pass."
			});
		}

		// GET /api/dev/hm1-step0-purchase-test?key=seed123 — STEP ZERO (blocking): does the purchase→receipt path work AFTER ب-3,
		// and does it create an inbound stock movement (SourceType? JournalEntryId?)? On FIXED ZZ entities only. Read-verifies, no teardown of the FK graph.
		[HttpGet("hm1-step0-purchase-test")]
		public async Task<IActionResult> Hm1Step0PurchaseTest(string key, [FromServices] CrossBuy.BL.IPayableService ap, [FromServices] CrossBuy.BL.IProcurementService proc)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1; var report = new List<object>();
			var cat = await _db.ItemCategories.AsNoTracking().FirstOrDefaultAsync(c => c.CompanyID == company && c.InventoryAccountId != null);
			int baseUom = await _db.UnitsOfMeasure.AsNoTracking().Where(u => u.CompanyID == company).Select(u => u.ID).FirstOrDefaultAsync();
			int wh = await _db.Warehouses.AsNoTracking().Where(w => w.CompanyID == company).OrderBy(w => w.ID).Select(w => w.ID).FirstOrDefaultAsync();
			int apCtrl = await _db.Vendors.AsNoTracking().Select(v => v.ControlAccountId).FirstOrDefaultAsync();   // reuse an existing AP control account
			if (cat == null || baseUom == 0 || wh == 0 || apCtrl == 0) return BadRequest(new { message = "need category(inv-acc)/uom/warehouse/existing-vendor-control-account" });

			// FIXED ZZ vendor + ZZ stockable item (reused across runs)
			var ven = await _db.Vendors.FirstOrDefaultAsync(v => v.CompanyID == company && v.Name == "ZZ-STEP0-VEN");
			if (ven == null) { ven = new CrossBuy.Models.Context.Accounting.Vendor { CompanyID = company, Name = "ZZ-STEP0-VEN", NameEn = "ZZ step0 vendor", ControlAccountId = apCtrl, IsActive = true, CreatedAt = DateTime.UtcNow }; _db.Vendors.Add(ven); await _db.SaveChangesAsync(); }
			var itm = await _db.Items.FirstOrDefaultAsync(i => i.CompanyID == company && i.ItemCode == "ZZ-STEP0-ITM");
			if (itm == null) { var (iok, ierr, it2) = await _itemSvc.CreateItemAsync(company, new CrossBuy.BL.ItemInput { ItemCode = "ZZ-STEP0-ITM", Barcode = "ZZSTEP0ITM", Name = "صنف صفر", NameEn = "step0 item", ItemCategoryId = cat.ID, ItemType = CrossBuy.Models.Context.Inventory.ItemTypes.Stockable, BaseUoMId = baseUom, SalesPrice = 50m, OpeningCost = 20m, IsActive = true }, null); if (!iok) return BadRequest(new { message = "ZZ item: " + ierr }); itm = it2; }
			int itemId = itm!.ID;

			async Task<(decimal q, decimal v)> Bal() { var (q, v, _) = await _stock.GetBalanceAsync(company, itemId, wh); return (q, v); }
			async Task<object> Probe(string tag, int? sourceId, string srcType)
			{
				if (sourceId == null) return new { tag, movementCreated = false };
				var m = await _db.StockMovements.AsNoTracking().Where(x => x.CompanyID == company && x.ItemId == itemId && x.SourceType == srcType && x.SourceId == sourceId).OrderByDescending(x => x.ID).FirstOrDefaultAsync();
				if (m == null) return new { tag, movementCreated = false, sourceType_searched = srcType, sourceId };
				return new { tag, movementCreated = true, sourceType_actual = m.SourceType, direction = m.Direction, qtyBase = m.QtyBase, hasJournalEntryId = m.JournalEntryId != null, journalEntryId = m.JournalEntryId };
			}

			// ===== (1) PURCHASE INVOICE for a ZZ stockable item =====
			var (pq0, pv0) = await Bal();
			var (piOk, piErr, piInv) = await ap.CreatePurchaseInvoiceAsync(company, ven.ID, DateTime.UtcNow, new List<CrossBuy.BL.PurchaseLineInput> {
				new CrossBuy.BL.PurchaseLineInput { ItemDescription = "ZZ step0", Qty = 5, UnitPrice = 20m, DiscountAmount = 0, TaxRate = 0, ExpenseAccountId = cat.InventoryAccountId!.Value, ItemId = itemId, WarehouseId = wh } }, "ZZ step0", null);
			var (pq1, pv1) = await Bal();
			report.Add(new { step = "1-purchase-invoice", ok = piOk, error = piErr, invoiceNo = piInv?.InvoiceNo, invoiceJournalEntryId = piInv?.JournalEntryId, balanceDelta = pq1 - pq0, movement = await Probe("purchase-invoice", piInv?.ID, "PurchaseInvoice") });

			// ===== (2) GRN (goods receipt) =====
			var (gq0, _) = await Bal();
			var (grOk, grErr, gr) = await proc.CreateReceiptAsync(company, ven.ID, wh, null, DateTime.UtcNow, "ZZ step0 grn", new List<CrossBuy.BL.ReceiptLineInput> {
				new CrossBuy.BL.ReceiptLineInput { ItemId = itemId, Qty = 3, UoMId = baseUom, UnitCost = 20m } }, null);
			var (gq1, _2) = await Bal();
			report.Add(new { step = "2-goods-receipt", ok = grOk, error = grErr, receiptNo = gr?.ReceiptNo, balanceDelta = gq1 - gq0, movement = await Probe("goods-receipt", gr?.ID, "GoodsReceipt") });

			// ===== (3) VENDOR RETURN =====
			var (rq0, _3) = await Bal();
			var (prOk, prErr, pr) = await ap.CreatePurchaseReturnAsync(company, ven.ID, piInv?.ID, DateTime.UtcNow, new List<CrossBuy.BL.PurchaseLineInput> {
				new CrossBuy.BL.PurchaseLineInput { ItemDescription = "ZZ step0 return", Qty = 1, UnitPrice = 20m, DiscountAmount = 0, TaxRate = 0, ExpenseAccountId = cat.InventoryAccountId!.Value, ItemId = itemId, WarehouseId = wh } }, "ZZ step0 return", null);
			var (rq1, _4) = await Bal();
			report.Add(new { step = "3-vendor-return", ok = prOk, error = prErr, returnNo = pr?.ReturnNo, balanceDelta = rq1 - rq0, movement = await Probe("vendor-return", pr?.ID, "PurchaseReturn") });

			return Ok(new { note = "STEP ZERO — ZZ entities only. Purchase→receipt path probed post-ب-3.", vendorId = ven.ID, itemId, report });
		}

		[HttpGet("hm1-d6-race-test")]
		public async Task<IActionResult> Hm1D6RaceTest(string key)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1;
			var cat = await _db.ItemCategories.AsNoTracking().FirstOrDefaultAsync(c => c.CompanyID == company && c.InventoryAccountId != null);
			int baseUom = await _db.UnitsOfMeasure.AsNoTracking().Where(u => u.CompanyID == company).Select(u => u.ID).FirstOrDefaultAsync();
			int wh = await _db.Warehouses.AsNoTracking().Where(w => w.CompanyID == company).OrderBy(w => w.ID).Select(w => w.ID).FirstOrDefaultAsync();
			if (cat == null || baseUom == 0 || wh == 0) return BadRequest(new { message = "need category/uom/warehouse" });
			// fixed ZZ item (reused; ends every run at 0 movements because each scenario is rolled back → HM-D6-clean)
			var itm = await _db.Items.FirstOrDefaultAsync(i => i.CompanyID == company && i.ItemCode == "ZZ-RACE-ITM");
			if (itm == null) { var (iok, _, it2) = await _itemSvc.CreateItemAsync(company, new CrossBuy.BL.ItemInput { ItemCode = "ZZ-RACE-ITM", Barcode = "ZZRACEITM", Name = "سباق D6", NameEn = "D6 race", ItemCategoryId = cat.ID, ItemType = CrossBuy.Models.Context.Inventory.ItemTypes.Stockable, BaseUoMId = baseUom, SalesPrice = 100m, OpeningCost = 30m, IsActive = true }, null); if (!iok) return BadRequest(new { message = "ZZ item create failed" }); itm = it2; }
			int itemId = itm!.ID;

			// up=true reproduces the DOCUMENTED +1 (balance HIGHER): main holds a stale-HIGH base while an external DEDUCT
			// (a concurrent sale) lands — exactly #5173. up=false reproduces −5 (external add). Both via the SAME mechanism.
			async Task<(decimal bal, decimal mv)> Scenario(bool bypass, bool up)
			{
				CrossBuy.BL.StockService._testBypassLockReadRefresh = bypass;
				await using var tx = await CrossBuy.BL.ScopedTx.BeginOrJoinAsync(_db);   // OWNER — rolled back at the end (zero persistence)
				// step 1: main context IN 10 → tracks bal=10 (DB=10, movements=10)
				await _stock.PostMovementAsync(company, new CrossBuy.BL.MovementRequest { ItemId = itemId, WarehouseId = wh, Direction = 1, Qty = 10, UnitCostInBase = 30m, SourceType = "Opening", PostToGl = false }, null);
				// step 2: EXTERNAL write the tracker can't observe (raw SQL) + its matching movement
				int extDir = up ? -1 : 1; decimal extQty = up ? 1 : 5; decimal extVal = up ? 30 : 150;
				await _db.Database.ExecuteSqlRawAsync("UPDATE StockBalances SET QtyOnHand = QtyOnHand + {0}, TotalValue = TotalValue + {1} WHERE CompanyID = {2} AND ItemId = {3} AND WarehouseId = {4}", extDir * extQty, extDir * extVal, company, itemId, wh);
				await _db.Database.ExecuteSqlRawAsync("INSERT INTO StockMovements (CompanyID, MovementDate, ItemId, WarehouseId, Direction, QtyBase, UoMId, QtyInUoM, UnitCost, TotalCost, SourceType, CreatedAt) VALUES ({0}, {1}, {2}, {3}, {4}, {5}, {6}, {5}, 30, {7}, 'ZZ-EXT', {1})", company, DateTime.UtcNow, itemId, wh, extDir, extQty, baseUom, extVal);
				// step 3: main op computes from its STALE base (10): up ⇒ OUT 1 (deduct from stale-high) ; down ⇒ IN 1
				if (up) await _stock.PostMovementAsync(company, new CrossBuy.BL.MovementRequest { ItemId = itemId, WarehouseId = wh, Direction = -1, Qty = 1, SourceType = "Issue", PostToGl = false }, null);
				else await _stock.PostMovementAsync(company, new CrossBuy.BL.MovementRequest { ItemId = itemId, WarehouseId = wh, Direction = 1, Qty = 1, UnitCostInBase = 30m, SourceType = "Opening", PostToGl = false }, null);
				decimal balNow = await _db.StockBalances.AsNoTracking().Where(b => b.ItemId == itemId && b.WarehouseId == wh).Select(b => b.QtyOnHand).FirstAsync();
				decimal mvNow = await _db.StockMovements.AsNoTracking().Where(m => m.ItemId == itemId && m.WarehouseId == wh).SumAsync(m => (decimal?)(m.Direction * m.QtyBase)) ?? 0m;
				await tx.RollbackAsync();   // undo EVERYTHING → zero persistence
				CrossBuy.BL.StockService._testBypassLockReadRefresh = false;
				return (balNow, mvNow);
			}

			var preUp = await Scenario(true, true);     // pre-fix, +1 direction (matches #5173): bal 9, mv 8 → +1
			var postUp = await Scenario(false, true);   // fixed: bal 8, mv 8
			var pre = await Scenario(true, false);      // pre-fix, −5 direction
			var post = await Scenario(false, false);    // fixed

			// same-item basket (fixed path, one tx, rolled back): line 2 must read line 1's result
			decimal basketBal, basketMv;
			await using (var tx2 = await CrossBuy.BL.ScopedTx.BeginOrJoinAsync(_db))
			{
				await _stock.PostMovementAsync(company, new CrossBuy.BL.MovementRequest { ItemId = itemId, WarehouseId = wh, Direction = 1, Qty = 10, UnitCostInBase = 30m, SourceType = "Opening", PostToGl = false }, null);
				await _stock.PostMovementAsync(company, new CrossBuy.BL.MovementRequest { ItemId = itemId, WarehouseId = wh, Direction = 1, Qty = 7, UnitCostInBase = 30m, SourceType = "Opening", PostToGl = false }, null);
				basketBal = await _db.StockBalances.AsNoTracking().Where(b => b.ItemId == itemId && b.WarehouseId == wh).Select(b => b.QtyOnHand).FirstAsync();
				basketMv = await _db.StockMovements.AsNoTracking().Where(m => m.ItemId == itemId && m.WarehouseId == wh).SumAsync(m => (decimal?)(m.Direction * m.QtyBase)) ?? 0m;
				await tx2.RollbackAsync();
			}

			bool upPlus1 = (preUp.bal - preUp.mv) == 1m;       // the DOCUMENTED +1 direction reproduced exactly
			bool upFixed = postUp.bal == postUp.mv;
			bool preFails = pre.bal != pre.mv;                 // pre-fix: balance ≠ net movements (the bug)
			bool postPasses = post.bal == post.mv;             // post-fix: balance == net movements
			bool basketOk = basketBal == 17m && basketMv == 17m; // line 2 saw line 1 (10+7)

			return Ok(new
			{
				pass = upPlus1 && upFixed && preFails && postPasses && basketOk,
				plus1_matches5173 = new
				{
					preFix = new { balance = preUp.bal, netMovements = preUp.mv, anomaly = preUp.bal - preUp.mv, reproduced = upPlus1 },
					postFix = new { balance = postUp.bal, netMovements = postUp.mv, anomaly = postUp.bal - postUp.mv, consistent = upFixed },
					timeline = "IN 10 (main tracks bal=10) → EXTERNAL sale OUT 1 (DB→9, movements 10−1=9, tracker BLIND) → main OUT 1 from its STALE base 10 ⇒ pre-fix 10−1=9 while net-movements=8 ⇒ +1 (balance HIGHER); post-fix Reload sees 9 ⇒ 9−1=8 == movements. Mirrors deploy/EVIDENCE-ZZ-B5B.md (a-retry 199 · b external→198 · c stale 199→198 vs 197 = +1)."
				},
				minus5_reverseDirection = new
				{
					preFix = new { balance = pre.bal, netMovements = pre.mv, anomaly = pre.bal - pre.mv, reproducedBug = preFails },
					postFix = new { balance = post.bal, netMovements = post.mv, anomaly = post.bal - post.mv, consistent = postPasses }
				},
				sameItemBasket = new { balance = basketBal, netMovements = basketMv, expected = 17, line2ReadLine1 = basketOk },
				note = "deterministic (raw-SQL external write, tracker-blind) inside a ROLLED-BACK tx → zero persistence. Real concurrent lock-wait timing deferred to Phase د measurement per instruction."
			});
		}

		// GET /api/dev/hm1-phase-d-measure?key=seed123 — Phase د item 11: Isolated vs Ambient JV allocation under 5 parallel
		// full sales; 20-line basket time; lock-wait. Fixed ZZ entities (topped-up). Numbers to decide the JvAllocationMode switch.
		[HttpGet("hm1-phase-d-measure")]
		public async Task<IActionResult> Hm1PhaseDMeasure(string key)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1;
			var cat = await _db.ItemCategories.AsNoTracking().FirstOrDefaultAsync(c => c.CompanyID == company && c.InventoryAccountId != null);
			int revenue = await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.Code == "4101").Select(a => a.ID).FirstOrDefaultAsync();
			int baseUom = await _db.UnitsOfMeasure.AsNoTracking().Where(u => u.CompanyID == company).Select(u => u.ID).FirstOrDefaultAsync();
			int wh = await _db.Warehouses.AsNoTracking().Where(w => w.CompanyID == company).OrderBy(w => w.ID).Select(w => w.ID).FirstOrDefaultAsync();
			if (cat == null || revenue == 0 || baseUom == 0 || wh == 0) return BadRequest(new { message = "need category/4101/uom/warehouse" });
			async Task<int> EnsureItem(string code)
			{
				var it = await _db.Items.FirstOrDefaultAsync(i => i.CompanyID == company && i.ItemCode == code);
				if (it == null) { var (ok, _, c2) = await _itemSvc.CreateItemAsync(company, new CrossBuy.BL.ItemInput { ItemCode = code, Barcode = code, Name = code, ItemCategoryId = cat.ID, ItemType = CrossBuy.Models.Context.Inventory.ItemTypes.Stockable, BaseUoMId = baseUom, SalesPrice = 100m, OpeningCost = 30m, IsActive = true }, null); if (!ok) return 0; it = c2; }
				var (q, _, _) = await _stock.GetBalanceAsync(company, it!.ID, wh); if (q < 200) await _stock.PostMovementAsync(company, new CrossBuy.BL.MovementRequest { ItemId = it.ID, WarehouseId = wh, Direction = 1, Qty = 1000, UnitCostInBase = 30m, SourceType = "Opening", PostToGl = true }, null);
				return it.ID;
			}
			int itemA = await EnsureItem("ZZ-MEAS-A");
			await _ar.SaveCustomerAsync(company, new CrossBuy.Models.Context.Accounting.Customer { Name = "عميل قياس د", Phone = "0", IsActive = true });
			int custId = await _db.Customers.Where(c => c.CompanyID == company && c.Name == "عميل قياس د").OrderByDescending(c => c.ID).Select(c => c.ID).FirstAsync();
			CrossBuy.BL.SalesLineInput L(int n = 1) => new() { ItemDescription = "meas", Qty = n, UnitPrice = 100m, TaxRate = 0, RevenueAccountId = revenue, ItemId = itemA, WarehouseId = wh };

			async Task<(long[] ms, int fails)> FiveParallel(string mode)
			{
				CrossBuy.BL.JournalEntryService._testJvModeOverride = mode;
				var tasks = Enumerable.Range(0, 5).Select(_ => Task.Run(async () =>
				{
					var sw = System.Diagnostics.Stopwatch.StartNew();
					using var sc = _scopes.CreateScope(); var ar = sc.ServiceProvider.GetRequiredService<CrossBuy.BL.IReceivableService>();
					var (ok, _, _) = await ar.CreateSalesInvoiceAsync(company, custId, DateTime.Today, new List<CrossBuy.BL.SalesLineInput> { L() }, "meas " + mode, null);
					sw.Stop(); return (ok, sw.ElapsedMilliseconds);
				})).ToArray();
				var r = await Task.WhenAll(tasks);
				CrossBuy.BL.JournalEntryService._testJvModeOverride = null;
				return (r.Select(x => x.ElapsedMilliseconds).OrderBy(x => x).ToArray(), r.Count(x => !x.ok));
			}

			var iso = await FiveParallel("Isolated");
			var amb = await FiveParallel("Ambient");

			// 20-line basket (single invoice) time
			var sw20 = System.Diagnostics.Stopwatch.StartNew();
			var lines20 = Enumerable.Range(0, 20).Select(_ => L()).ToList();
			var (b20ok, _, _) = await _ar.CreateSalesInvoiceAsync(company, custId, DateTime.Today, lines20, "meas 20-line", null);
			sw20.Stop();

			return Ok(new
			{
				isolated = new { perSaleMs = iso.ms, minMs = iso.ms.Min(), maxMs = iso.ms.Max(), lockWaitApproxMs = iso.ms.Max() - iso.ms.Min(), failures = iso.fails },
				ambient = new { perSaleMs = amb.ms, minMs = amb.ms.Min(), maxMs = amb.ms.Max(), lockWaitApproxMs = amb.ms.Max() - amb.ms.Min(), failures = amb.fails },
				basket20 = new { ok = b20ok, totalMs = sw20.ElapsedMilliseconds, perLineMs = sw20.ElapsedMilliseconds / 20.0 },
				connectionsPerSale = "1 ambient (held for the sale) + 1 short-lived ISOLATED connection per JE posted (sale JE + COGS JE + receipt JE…) ≈ 3–4; Ambient mode uses only the 1 ambient connection but serializes ALL sales on the single JV NumberSequences row",
				note = "fixed ZZ entities topped-up; measurement sales left in place (consistent). JvAllocationMode override is a Debug-only seam."
			});
		}
#endif

