		// GET /api/dev/hm2-rate-staleness-test?key=seed123 — HM-D23: the exchange-rate staleness policy (AccountingSettings.RateMaxAgeDays
		// + RateStaleBehavior). Four ZZ scenarios (KWD, each rolled-back): default(0)=no effect · Warn=proceed+counted · Reject=blocked
		// with an actionable message + zero effect · enter today's rate then retry=succeeds.
		[HttpGet("hm2-rate-staleness-test")]
		public async Task<IActionResult> Hm2RateStalenessTest(string key, [FromServices] CrossBuy.BL.IReceivableService ar)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1;
			int ctrl = await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.Code == "1102").Select(a => a.ID).FirstOrDefaultAsync();
			int rev = await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.Code == "4101").Select(a => a.ID).FirstOrDefaultAsync();
			var cust = await _db.Customers.FirstOrDefaultAsync(c => c.CompanyID == company && c.Name == "ZZ-KWD-CUST");
			if (cust == null) { cust = new CrossBuy.Models.Context.Accounting.Customer { CompanyID = company, Name = "ZZ-KWD-CUST", ControlAccountId = ctrl, IsActive = true, CreatedAt = DateTime.UtcNow }; _db.Customers.Add(cust); await _db.SaveChangesAsync(); }
			var line = new List<CrossBuy.BL.SalesLineInput> { new() { ItemDescription = "ZZ", Qty = 10, UnitPrice = 1.000m, DiscountAmount = 0, TaxRate = 0, RevenueAccountId = rev, ItemId = null, WarehouseId = null } };

			async Task SetPolicy(int maxAge, string behavior)
			{
				var s = await _db.AccountingSettings.FirstOrDefaultAsync(x => x.CompanyID == company);
				if (s == null) { s = new CrossBuy.Models.Context.Accounting.AccountingSettings { CompanyID = company }; _db.AccountingSettings.Add(s); }
				s.RateMaxAgeDays = maxAge; s.RateStaleBehavior = behavior; await _db.SaveChangesAsync();
			}
			async Task<object> Scenario(string tag, int maxAge, string behavior, bool insertTodayRate)
			{
				long before = CrossBuy.BL.CurrencyService.StaleRateSales;
				await using var tx = await CrossBuy.BL.ScopedTx.BeginOrJoinAsync(_db);
				await SetPolicy(maxAge, behavior);
				if (insertTodayRate) { _db.ExchangeRates.Add(new CrossBuy.Models.Context.Accounting.ExchangeRate { CurrencyId = 5, RateDate = DateTime.Today, Rate = 163m, RateType = "Sell" }); await _db.SaveChangesAsync(); }
				int invBefore = await _db.SalesInvoices.CountAsync(i => i.CustomerId == cust.ID);
				var (ok, err, inv) = await ar.CreateSalesInvoiceAsync(company, cust.ID, DateTime.Today, line, "ZZ stale", null, 5);   // KWD, rate looked up (no explicit)
				int invAfter = await _db.SalesInvoices.CountAsync(i => i.CustomerId == cust.ID);
				long delta = CrossBuy.BL.CurrencyService.StaleRateSales - before;
				var res = new { tag, maxAge, behavior, ok, err, invoiceCreated = inv != null, invoiceRowDelta = invAfter - invBefore, countedDelta = delta };
				await tx.RollbackAsync();
				return res;
			}
			var results = new List<object>
			{
				await Scenario("1: day-old policy off (MaxAge=0) → no effect (default)", 0, "Warn", false),
				await Scenario("2: 213-day rate, MaxAge=1, Warn → proceeds + counted", 1, "Warn", false),
				await Scenario("3: same, Reject → blocked, actionable msg, zero effect", 1, "Reject", false),
				await Scenario("4: Reject but enter TODAY's rate first → succeeds", 1, "Reject", true),
			};
			return Ok(new { note = "each scenario rolled back (zero persistence); KWD latest rate is 2026-01-01 (stale)", results });
		}

		// GET /api/dev/hm2-kwd-functional-company?key=seed123 — HM-2 Phase C ج-٥: ALL prior proofs are EGP-functional; the FUNCTIONAL-currency
		// cost path at 3dp was never exercised. Create a ZZ company whose FUNCTIONAL currency is KWD (3dp) and prove the stock cost path
		// rounds to 3dp (functional), not the old hardcoded 2dp. Rolled-back tx (zero persistence).
		[HttpGet("hm2-kwd-functional-company")]
		public async Task<IActionResult> Hm2KwdFunctionalCompany(string key, [FromServices] CrossBuy.BL.ICurrencyRounding rounding)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			int uom = await _db.UnitsOfMeasure.AsNoTracking().Select(u => u.ID).FirstAsync();
			await using var tx = await CrossBuy.BL.ScopedTx.BeginOrJoinAsync(_db);
			// (1) a company whose FUNCTIONAL currency is KWD (currency 5, 3dp)
			var co = await _db.Companies.FirstOrDefaultAsync(c => c.CompanyName == "ZZ-KWD-FUNC-CO");
			if (co == null) { co = new CrossBuy.Models.Context.Admin.Companies { CompanyName = "ZZ-KWD-FUNC-CO", Address = "t", PhoneNumber = "", Email = "", CountryID = 32, CompanyTypeId = 1, DefaultCurrencyId = 5 }; _db.Companies.Add(co); await _db.SaveChangesAsync(); }
			else { co.DefaultCurrencyId = 5; await _db.SaveChangesAsync(); }
			int company = co.CompanyID;
			int fdp = await rounding.DecimalsAsync(company, null);   // functional dp — MUST be 3 (KWD)
			// open fiscal period covering today (PostMovement's PeriodGuard requires one)
			if (!await _db.FiscalYears.AnyAsync(y => y.CompanyID == company))
			{
				var fy = new CrossBuy.Models.Context.Accounting.FiscalYear { CompanyID = company, Name = "ZZ-KWD-FY", StartDate = new DateTime(DateTime.Today.Year, 1, 1), EndDate = new DateTime(DateTime.Today.Year, 12, 31), Status = "Open" };
				_db.FiscalYears.Add(fy); await _db.SaveChangesAsync();
				_db.FiscalPeriods.Add(new CrossBuy.Models.Context.Accounting.FiscalPeriod { FiscalYearId = fy.ID, PeriodNo = (byte)DateTime.Today.Month, StartDate = new DateTime(DateTime.Today.Year, DateTime.Today.Month, 1), EndDate = new DateTime(DateTime.Today.Year, DateTime.Today.Month, 28), Status = "Open" });
				await _db.SaveChangesAsync();
			}
			// (2) minimal scaffold for that company
			await _whSvc.CreateWarehouseAsync(company, new CrossBuy.Models.Context.Inventory.Warehouse { Code = "ZZKWDWH", Name = "kwd wh", NameEn = "kwd wh" }, null);
			int wh = await _db.Warehouses.AsNoTracking().Where(w => w.CompanyID == company && w.Code == "ZZKWDWH").Select(w => w.ID).FirstAsync();
			// inventory GL accounts for THIS company (so GRN/count/assembly can post GL); functional = KWD (3dp)
			async Task<int> Acc(string code, string name, int typeId) { var a = await _db.Accounts.FirstOrDefaultAsync(x => x.CompanyID == company && x.Code == code); if (a == null) { a = new CrossBuy.Models.Context.Accounting.Account { CompanyID = company, Code = code, Name = name, NameEn = name, AccountTypeId = typeId, IsPostable = true, IsActive = true, CreatedAt = DateTime.UtcNow }; _db.Accounts.Add(a); await _db.SaveChangesAsync(); } return a.ID; }
			int invAcc = await Acc("1103", "مخزون", 1), grniAcc = await Acc("210203", "GRNI", 2), cogsAcc = await Acc("5101", "تكلفة مبيعات", 5), adjAcc = await Acc("5109", "تسوية مخزون", 5);
			var cat = await _db.ItemCategories.FirstOrDefaultAsync(c => c.CompanyID == company && c.Name == "ZZ-KWD-FCAT");
			if (cat == null) { cat = new CrossBuy.Models.Context.Inventory.ItemCategory { CompanyID = company, Name = "ZZ-KWD-FCAT", NameEn = "kwd fcat" }; _db.ItemCategories.Add(cat); }
			cat.InventoryAccountId = invAcc; cat.GrniAccountId = grniAcc; cat.CogsAccountId = cogsAcc; cat.AdjustmentAccountId = adjAcc; await _db.SaveChangesAsync();
			var it = await _db.Items.FirstOrDefaultAsync(i => i.CompanyID == company && i.ItemCode == "ZZ-KWD-FCOST");
			if (it == null) { var (iok, ierr, item) = await _itemSvc.CreateItemAsync(company, new CrossBuy.BL.ItemInput { ItemCode = "ZZ-KWD-FCOST", Barcode = "ZZKWDFCOST", Name = "كلفة", NameEn = "cost", ItemCategoryId = cat.ID, ItemType = "Stockable", BaseUoMId = uom, IsActive = true }, null); if (!iok) { await tx.RollbackAsync(); return BadRequest(new { message = "item: " + ierr }); } it = await _db.Items.FirstAsync(i => i.ID == item!.ID); }
			async Task<decimal> Gl(int acct) => await _db.JournalEntryLines.AsNoTracking().Where(l => l.AccountId == acct).SumAsync(l => l.Debit - l.Credit);
			// (3) GRN: goods receipt qty 3 @ functional unit cost 0.755 KWD, POSTS GL (Dr 1103 / Cr GRNI). value 2.265 (3dp).
			var (gok, gerr, gmv) = await _stock.PostMovementAsync(company, new CrossBuy.BL.MovementRequest { Date = DateTime.Today, ItemId = it.ID, WarehouseId = wh, Direction = 1, Qty = 3m, UnitCostInBase = 0.755m, SourceType = "Receipt", PostToGl = true }, null);
			var grnMv = gmv == null ? null : await _db.StockMovements.AsNoTracking().Where(m => m.ID == gmv.ID).Select(m => new { m.TotalCost, m.UnitCost, m.JournalEntryId }).FirstOrDefaultAsync();
			decimal inv1103AfterGrn = await Gl(invAcc);
			var balAfterGrn = await _db.StockBalances.AsNoTracking().Where(b => b.CompanyID == company && b.ItemId == it.ID && b.WarehouseId == wh).Select(b => new { b.TotalValue, b.AvgCost, b.QtyOnHand }).FirstAsync();
			var grnJl = grnMv?.JournalEntryId == null ? new List<CrossBuy.Models.Context.Accounting.JournalEntryLine>() : await _db.JournalEntryLines.AsNoTracking().Where(l => l.JournalEntryId == grnMv.JournalEntryId).ToListAsync();
			bool grnJeBal = grnJl.Count > 0 && grnJl.Sum(x => x.Debit) == grnJl.Sum(x => x.Credit);

			// (4) production/assembly (aggregation): build a composite from 2 component units of this item, assemble 1 → output cost = Σ components at 3dp
			var comp = await _db.Items.FirstOrDefaultAsync(i => i.CompanyID == company && i.ItemCode == "ZZ-KWD-FKIT");
			if (comp == null) { var (cok2, cerr2, citem) = await _itemSvc.CreateItemAsync(company, new CrossBuy.BL.ItemInput { ItemCode = "ZZ-KWD-FKIT", Barcode = "ZZKWDFKIT", Name = "حزمة", NameEn = "kit", ItemCategoryId = cat.ID, ItemType = "Composite", BaseUoMId = uom, IsActive = true }, null); if (!cok2) { await tx.RollbackAsync(); return BadRequest(new { message = "kit: " + cerr2 }); } comp = await _db.Items.FirstAsync(i => i.ID == citem!.ID); }
			comp.IsComposite = true; comp.CompositeType = "Assembly"; await _db.SaveChangesAsync();   // AssembleAsync requires an Assembly-type composite
			if (!await _db.ItemComponents.AnyAsync(c => c.CompanyID == company && c.ParentItemId == comp.ID))
			{ _db.ItemComponents.Add(new CrossBuy.Models.Context.Inventory.ItemComponent { CompanyID = company, ParentItemId = comp.ID, ComponentItemId = it.ID, Quantity = 2m }); await _db.SaveChangesAsync(); }
			var (aok, aerr, amv) = await _stock.AssembleAsync(company, comp.ID, wh, 1m, DateTime.Today, false, null);
			var kitMv = amv == null ? null : await _db.StockMovements.AsNoTracking().Where(m => m.ID == amv.ID).Select(m => new { m.TotalCost, m.UnitCost }).FirstOrDefaultAsync();

			// (5) stock count: count 1 of the remaining component stock (on-hand 1 after assembly consumed 2 of 3) → variance value 3dp
			var (cnok, cnerr, cnt) = await _stock.PostCountAsync(company, wh, DateTime.Today, "zz count", new List<CrossBuy.BL.CountLineInput> { new() { ItemId = it.ID, CountedQty = 0m } }, null);
			var cntMv = cnt == null ? null : await _db.StockMovements.AsNoTracking().Where(m => m.CompanyID == company && m.SourceType == "Adjustment" && m.SourceId == cnt.ID).Select(m => new { m.TotalCost, m.QtyBase }).FirstOrDefaultAsync();
			// stock_gl for THIS company: Σ StockBalances.TotalValue == GL 1103 net (must hold for a fresh company)
			decimal stockValCo = await _db.StockBalances.AsNoTracking().Where(b => b.CompanyID == company).SumAsync(b => (decimal?)b.TotalValue) ?? 0m;
			decimal gl1103Co = await Gl(invAcc);
			await tx.RollbackAsync();
			return Ok(new
			{
				note = "ZZ company with FUNCTIONAL currency = KWD (3dp); full cost path (GRN + assembly + count); rolled-back tx",
				functionalDpForCompany = fdp, functionalIsKwd3dp = fdp == 3,
				grn = new { ok = gok, err = gerr, totalCost = grnMv?.TotalCost, unitCost = grnMv?.UnitCost, gl1103 = inv1103AfterGrn, balanceTotalValue = balAfterGrn.TotalValue, avgCost = balAfterGrn.AvgCost, jeBalanced = grnJeBal, threeDp = grnMv?.TotalCost == 2.265m && inv1103AfterGrn == 2.265m && balAfterGrn.AvgCost == 0.755m },
				assembly = new { ok = aok, err = aerr, outputCost = kitMv?.TotalCost, outputUnitCost = kitMv?.UnitCost, aggregatedThreeDp = kitMv?.TotalCost == 1.510m },   // 2 × 0.755 = 1.510
				stockCount = new { ok = cnok, err = cnerr, adjustmentValue = cntMv?.TotalCost, adjustedQty = cntMv?.QtyBase, threeDp = cntMv != null },
				stockGlForCompany = new { stockValue = stockValCo, gl1103 = gl1103Co, matched = stockValCo == gl1103Co }
			});
		}

		// GET /api/dev/hm2-rate-precision-probe?key=seed123 — HM-2 Batch 5 item 4-أ: does an 8-decimal FX rate survive to the DOCUMENT,
		// or does CurrencyService.R4 (ToBaseAsync:83-84) + the `ExchangeRate = R4(rate)` write on every document cut it to 4dp?
		// Passes an explicit 8dp rate to EVERY document path, then reads the STORED rate from a FRESH AsNoTracking query (not the
		// tracked entity). Also reads back ExchangeRates.Rate to show the RATE TABLE keeps 8dp. Rolled-back tx (zero persistence).
		[HttpGet("hm2-rate-precision-probe")]
		public async Task<IActionResult> Hm2RatePrecisionProbe(string key, [FromServices] CrossBuy.BL.IReceivableService ar, [FromServices] CrossBuy.BL.IPayableService ap, [FromServices] CrossBuy.BL.ICurrencyRounding rounding)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1;
			int ctrl = await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.Code == "1102").Select(a => a.ID).FirstOrDefaultAsync();
			int apCtrl = await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.Code == "2101").Select(a => a.ID).FirstOrDefaultAsync();
			int rev = await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.Code == "4101").Select(a => a.ID).FirstOrDefaultAsync();
			int cash = await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.Code == "110101").Select(a => a.ID).FirstOrDefaultAsync();
			int exp = await _db.Accounts.AsNoTracking().Where(a => a.CompanyID == company && a.AccountTypeId == 5 && a.IsPostable).Select(a => a.ID).FirstOrDefaultAsync();
			int? cc = await _db.CostCenters.AsNoTracking().Where(c => c.CompanyID == company).Select(c => (int?)c.ID).FirstOrDefaultAsync();
			if (ctrl == 0 || apCtrl == 0 || rev == 0 || cash == 0 || exp == 0) return BadRequest(new { message = "need 1102/2101/4101/110101/expense" });
			var cust = await _db.Customers.FirstOrDefaultAsync(c => c.CompanyID == company && c.Name == "ZZ-KWD-CUST");
			if (cust == null) { cust = new CrossBuy.Models.Context.Accounting.Customer { CompanyID = company, Name = "ZZ-KWD-CUST", ControlAccountId = ctrl, IsActive = true, CreatedAt = DateTime.UtcNow }; _db.Customers.Add(cust); await _db.SaveChangesAsync(); }
			var ven = await _db.Vendors.FirstOrDefaultAsync(v => v.CompanyID == company && v.Name == "ZZ-KWD-VEN");
			if (ven == null) { ven = new CrossBuy.Models.Context.Accounting.Vendor { CompanyID = company, Name = "ZZ-KWD-VEN", ControlAccountId = apCtrl, IsActive = true, CreatedAt = DateTime.UtcNow }; _db.Vendors.Add(ven); await _db.SaveChangesAsync(); }

			decimal src = 3.14159265m;                                   // an 8-decimal rate
			decimal r4 = Math.Round(src, 4, MidpointRounding.AwayFromZero);   // 3.1416 — what R4 keeps

			await using var tx = await CrossBuy.BL.ScopedTx.BeginOrJoinAsync(_db);
			// write the rate via the EF ENTITY (the production path, which respects the model's (19,8)) — NOT raw SQL (whose default
			// parameter scale would itself truncate). Read back fresh to show the RATE TABLE keeps 8dp.
			var erRow = new CrossBuy.Models.Context.Accounting.ExchangeRate { CurrencyId = 5, RateDate = DateTime.Today, Rate = src, RateType = "ZZ-D-RATE" };
			_db.ExchangeRates.Add(erRow); await _db.SaveChangesAsync();
			decimal tableRate = await _db.ExchangeRates.AsNoTracking().Where(x => x.ID == erRow.ID).Select(x => x.Rate).FirstAsync();

			var sLine = new List<CrossBuy.BL.SalesLineInput> { new() { ItemDescription = "ZZ", Qty = 1, UnitPrice = 10m, DiscountAmount = 0, TaxRate = 0, RevenueAccountId = rev, ItemId = null, WarehouseId = null } };
			var (iok, ierr, inv) = await ar.CreateSalesInvoiceAsync(company, cust.ID, DateTime.Today, sLine, "ZZ rate", null, 5, src);
			decimal? siRate = inv == null ? null : await _db.SalesInvoices.AsNoTracking().Where(x => x.ID == inv.ID).Select(x => (decimal?)x.ExchangeRate).FirstAsync();
			var (rcok, rcerr) = await ar.CreateReceiptAsync(company, cust.ID, DateTime.Today, 5m, "Cash", cash, "ZZ rate", null, 5, src);
			decimal? rcRate = await _db.Receipts.AsNoTracking().Where(x => x.CustomerId == cust.ID).OrderByDescending(x => x.ID).Select(x => (decimal?)x.ExchangeRate).FirstOrDefaultAsync();
			var (srok, srerr, ret) = await ar.CreateSalesReturnAsync(company, cust.ID, inv?.ID, DateTime.Today, sLine, "ZZ rate", null, 5, src);
			decimal? srRate = ret == null ? null : await _db.SalesReturns.AsNoTracking().Where(x => x.ID == ret.ID).Select(x => (decimal?)x.ExchangeRate).FirstAsync();
			var pLine = new List<CrossBuy.BL.PurchaseLineInput> { new() { ItemDescription = "ZZ", Qty = 1, UnitPrice = 10m, DiscountAmount = 0, TaxRate = 0, ExpenseAccountId = exp, CostCenterId = cc } };
			var (piok, pierr, pinv) = await ap.CreatePurchaseInvoiceAsync(company, ven.ID, DateTime.Today, pLine, "ZZ rate", null, 5, src);
			decimal? piRate = pinv == null ? null : await _db.PurchaseInvoices.AsNoTracking().Where(x => x.ID == pinv.ID).Select(x => (decimal?)x.ExchangeRate).FirstAsync();
			var (pmok, pmerr) = await ap.CreatePaymentAsync(company, ven.ID, DateTime.Today, 5m, "Cash", cash, "ZZ rate", null, 0, 5, src);
			decimal? pmRate = await _db.Payments.AsNoTracking().Where(x => x.VendorId == ven.ID).OrderByDescending(x => x.ID).Select(x => (decimal?)x.ExchangeRate).FirstOrDefaultAsync();
			// HM-D29 reproducibility: recompute GrandTotalBase from the STORED rate (fresh read) — must equal the stored base exactly now.
			int fdp = await rounding.DecimalsAsync(company, null);
			var siRow = inv == null ? null : await _db.SalesInvoices.AsNoTracking().Where(x => x.ID == inv.ID).Select(x => new { x.GrandTotal, x.GrandTotalBase, x.ExchangeRate }).FirstAsync();
			decimal? reproBase = siRow == null ? null : Math.Round(siRow.GrandTotal * (siRow.ExchangeRate ?? 1m), fdp, MidpointRounding.AwayFromZero);
			bool baseReproducible = siRow != null && reproBase == siRow.GrandTotalBase;
			await tx.RollbackAsync();
			// existing docs UNCHANGED (forward-only fix; no backfill): sample 2 pre-existing invoices' stored rates outside the tx
			var existingSample = await _db.SalesInvoices.AsNoTracking().Where(x => x.CompanyID == company && x.ExchangeRate != null).OrderByDescending(x => x.ID).Skip(5).Take(2).Select(x => new { x.ID, x.CurrencyId, x.ExchangeRate }).ToListAsync();

			var docRates = new[] { siRate, rcRate, srRate, piRate, pmRate };
			return Ok(new
			{
				note = "rolled-back tx; explicit 8dp rate passed to EVERY path; document rate read fresh (AsNoTracking)",
				sourceRate_8dp = src, r4_expected = r4,
				exchangeRatesTable_keeps8dp = tableRate == src, exchangeRatesTable_value = tableRate,
				documentStoredRate = new { salesInvoice = siRate, receipt = rcRate, salesReturn = srRate, purchaseInvoice = piRate, payment = pmRate },
				everyDocumentKept8dp = docRates.All(x => x == src),
				storedGrandTotalBase = siRow?.GrandTotalBase, recomputedFromStoredRate = reproBase, baseReproducibleFromStoredRate = baseReproducible,
				existingDocsUnchanged_sample = existingSample,
				errors = new { ierr, rcerr, srerr, pierr, pmerr }
			});
		}

		// GET /api/dev/seed-currencies?key=seed123 — seed common currencies + recent exchange rates (Currency module test data)
		[HttpGet("seed-currencies")]
		public async Task<IActionResult> SeedCurrencies(string key)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			var defs = new (string code, string sym, string ar, string en, byte dp, decimal rate)[] {
				("USD", "$",   "دولار أمريكي", "US Dollar",   2, 49.50m),
				("EUR", "€",   "يورو",          "Euro",        2, 53.80m),
				("SAR", "ر.س", "ريال سعودي",    "Saudi Riyal", 2, 13.20m),
				("AED", "د.إ", "درهم إماراتي",  "UAE Dirham",  2, 13.50m),
			};
			int added = 0, rates = 0;
			foreach (var d in defs)
			{
				var cur = await _db.Currencies.FirstOrDefaultAsync(c => c.Code == d.code);
				if (cur == null)
				{
					cur = new CrossBuy.Models.Context.Accounting.Currency { Code = d.code, Symbol = d.sym, Name = d.ar, NameEn = d.en, DecimalPlaces = d.dp };
					_db.Currencies.Add(cur);
					await _db.SaveChangesAsync();
					added++;
				}
				for (int i = 0; i < 3; i++)
				{
					var dt = DateTime.Today.AddDays(-i);
					bool exists = await _db.ExchangeRates.AnyAsync(r => r.CurrencyId == cur.ID && r.RateDate == dt && r.RateType == "Central");
					if (!exists)
					{
						_db.ExchangeRates.Add(new CrossBuy.Models.Context.Accounting.ExchangeRate { CurrencyId = cur.ID, RateDate = dt, Rate = d.rate + i * 0.05m, RateType = "Central" });
						rates++;
					}
				}
			}
			await _db.SaveChangesAsync();
			return Ok(new { ok = true, currenciesAdded = added, ratesAdded = rates });
		}

		// GET /api/dev/seed-item-allmoves?key=seed123&code=ITM-0001 — give one item EVERY movement type (for the item card demo); keeps GL balanced & integrity green
		[HttpGet("seed-item-allmoves")]
		public async Task<IActionResult> SeedItemAllMoves(string key, string? code)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1;
			var c = (code ?? "ITM-0001").Trim();
			var item = await _db.Items.AsNoTracking().FirstOrDefaultAsync(i => i.CompanyID == company && i.ItemCode == c)
				?? await _db.Items.AsNoTracking().FirstOrDefaultAsync(i => i.CompanyID == company && i.IsActive && !i.IsComposite && i.ItemType == "Stockable");
			if (item == null) return BadRequest(new { message = "no stockable item found" });
			var whs = await _db.Warehouses.AsNoTracking().Where(w => w.CompanyID == company).OrderBy(w => w.ID).Take(2).ToListAsync();
			if (whs.Count < 1) return BadRequest(new { message = "need a warehouse" });
			int w1 = whs[0].ID, w2 = whs.Count > 1 ? whs[1].ID : whs[0].ID;
			var steps = new List<object>();
			async Task post(string label, int whId, short dir, decimal qty, decimal? cost, string src, bool gl)
			{
				var (ok, err, mv) = await _stock.PostMovementAsync(company, new CrossBuy.BL.MovementRequest
				{ Date = DateTime.UtcNow, ItemId = item.ID, WarehouseId = whId, Direction = dir, Qty = qty, UnitCostInBase = cost, SourceType = src, PostToGl = gl }, null);
				steps.Add(new { label, ok, err });
			}
			await post("Opening +100 @10", w1, 1, 100, 10m, "Opening", true);
			await post("PurchaseInvoice +60 @12", w1, 1, 60, 12m, "PurchaseInvoice", true);
			await post("Adjustment +10 @11", w1, 1, 10, 11m, "Adjustment", true);
			await post("SalesInvoice -25", w1, -1, 25, null, "SalesInvoice", true);
			await post("Issue -15", w1, -1, 15, null, "Issue", true);
			// inter-warehouse transfer (no GL — total inventory value unchanged → integrity stays green)
			var (tok, terr, tmv) = await _stock.PostMovementAsync(company, new CrossBuy.BL.MovementRequest
			{ Date = DateTime.UtcNow, ItemId = item.ID, WarehouseId = w1, Direction = -1, Qty = 20, SourceType = "TransferOut", PostToGl = false }, null);
			var outUnit = (tmv != null && tmv.QtyBase != 0) ? tmv.TotalCost / tmv.QtyBase : 11m;
			await _stock.PostMovementAsync(company, new CrossBuy.BL.MovementRequest
			{ Date = DateTime.UtcNow, ItemId = item.ID, WarehouseId = w2, Direction = 1, Qty = 20, UnitCostInBase = outUnit, SourceType = "TransferIn", PostToGl = false }, null);
			steps.Add(new { label = "Transfer 20 (WH1→WH2)", ok = tok, err = terr });

			var bals = await (from b in _db.StockBalances.AsNoTracking()
							  join wh in _db.Warehouses.AsNoTracking() on b.WarehouseId equals wh.ID
							  where b.CompanyID == company && b.ItemId == item.ID && b.QtyOnHand != 0
							  select new { wh.Code, b.QtyOnHand, b.TotalValue }).ToListAsync();
			var moveCount = await _db.StockMovements.CountAsync(m => m.CompanyID == company && m.ItemId == item.ID);
			var barcode = await _db.Items.Where(i => i.ID == item.ID).Select(i => i.Barcode).FirstOrDefaultAsync();
			return Ok(new { item = item.ItemCode, name = item.Name, barcode, totalQty = bals.Sum(x => x.QtyOnHand), warehouses = bals, movementCount = moveCount, steps });
		}

		// GET /api/dev/crm-test-campaign?key=seed123 — CRM campaigns: CRUD + attribution + ROI (self-cleaning, non-GL)
		[HttpGet("crm-test-campaign")]
		public async Task<IActionResult> CrmTestCampaign(string key)
		{
			if (key != "seed123") return Unauthorized(new { message = "bad key" });
			const int company = 1;
			var (cok, cerr) = await _crm.SaveCampaignAsync(company, new CrossBuy.Models.Context.Crm.Campaign { Name = "حملة اختبار", Channel = "Email", Status = "Active", Budget = 1000 }, "test");
			var camp = await _db.Campaigns.OrderByDescending(c => c.ID).FirstAsync(c => c.CompanyID == company);
			await _crm.SaveLeadAsync(company, new CrossBuy.Models.Context.Crm.Lead { Name = "محتمل حملة", Status = "New", CampaignId = camp.ID }, "test");
			var lead = await _db.Leads.OrderByDescending(l => l.ID).FirstAsync(l => l.CompanyID == company);
			await _crm.SaveOpportunityAsync(company, new CrossBuy.Models.Context.Crm.Opportunity { Title = "فرصة حملة", Stage = "Won", Amount = 2500, Probability = 100, CampaignId = camp.ID }, "test");
			var opp = await _db.Opportunities.OrderByDescending(o => o.ID).FirstAsync(o => o.CompanyID == company);
			var (rows, _) = await _crm.SearchCampaignsAsync(company, "حملة اختبار", null, 1, 25);
			var row = rows.FirstOrDefault(r => r.Id == camp.ID);
			var picks = await _crm.GetCampaignsForPickAsync(company);
			var inPick = picks.Any(p => p.id == camp.ID);
			var rowOk = row != null && row.Leads >= 1 && row.Opps >= 1 && row.Won >= 1 && row.WonValue == 2500m && row.RoiPct == 150.0m;
			// cleanup
			_db.Opportunities.Remove(await _db.Opportunities.FirstAsync(o => o.ID == opp.ID));
			_db.Leads.Remove(await _db.Leads.FirstAsync(l => l.ID == lead.ID));
			_db.Campaigns.Remove(await _db.Campaigns.FirstAsync(c => c.ID == camp.ID));
			await _db.SaveChangesAsync();
			return Ok(new { campaign = new { cok, cerr }, perf = row == null ? null : new { row.Leads, row.Opps, row.Won, row.WonValue, row.RoiPct }, inPick, allPass = rowOk && inPick });
		}

